          {
            "$ref": "#/definitions/tags"
          }
        ]
      }
    },
    "unsupportedHosts": {
      "description": "Unsuppored Hosts. This can be used to supress the template from being displayed in the new project dialog in Visual Studio.",
      "type": "array",
      "items": {
