      },
      "options": {
        "title": "Array of link options",
        "type": "object"
      },
      "class": {
        "title": "Class for task implementations",
        "type": "string"
      },
      "form_class": {
        "title": "Class for task implementations",
        "type": "string"
      },
      "provider": {
        "title": "The name of the module providing this link",
        "type": "string"
      },
      "metadata": {
        "$comment": "@todo Add a title",
        "type": "array"
      },
      "expanded": {
        "title": "Show the link as expanded",
        "oneOf": [
          {
            "type": "boolean"
          },
          {
            "type": "integer"
          }
        ]
      },
      "enabled": {
