      },
      "else": {
        "additionalProperties": false,
        "properties": {
          "description": {
            "type": "string"
          },
          "global": {
            "type": "boolean",
            "description": "Whether this command should work while Chrome does not have focus. Keyboard shortcut suggestions for global commands are limited to Ctrl+Shift+[0..9]"
          },
          "suggested_key": {
            "type": "object",
            "additionalProperties": false,
            "patternProperties": {
              "^(default|mac|windows|linux|chromeos)$": {
                "type": "string",
                "pattern": "^(Ctrl|Command|MacCtrl|Alt|Option)\\+(Shift\\+)?[A-Z]"
              }
            }
          }
        }
      }
    },
    "content_security_policy": {
      "type": "string",
      "description": "This introduces some fairly strict policies that will make extensions more secure by default, and provides you with the ability to create and enforce rules governing the types of content that can be loaded and executed by your extensions and applications.",
      "format": "content-security-policy",
      "default": "script-src 'self'; object-src 'self'"
    },
    "glob_pattern": {
      "type": "string",
      "format": "glob-pattern"
    },
    "icon": {
      "$ref": "#/definitions/uri"
    },
    "match_pattern": {
      "type": "string",
      "format": "match-pattern",
      "pattern": "^((\\*|http|https|file|ftp|chrome-extension):\\/\\/(\\*|\\*\\.[^\\/\\*]+|[^\\/\\*]+)?(\\/.*))|urn:(\\*|.*)|<all_urls>$"
    },
    "mime_type": {
      "type": "string",
      "format": "mime-type",
      "pattern": "^(?:application|audio|image|message|model|multipart|text|video)\\/[-+.\\w]+$"
    },
    "page": {
      "$ref": "#/definitions/uri"
    },
    "permissions": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "format": "permission"
      }
    },
    "scripts": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/uri"
      }
    },
    "uri": {
      "type": "string"
    },
    "version_string": {
      "type": "string",
      "pattern": "^(?:\\d{1,5}\\.){0,3}\\d{1,5}$"
    },
    "web_resource": {
      "type": "object",
      "required": ["resources"],
      "properties": {
        "resources": {
          "type": "array",
          "description": "An array of resources to be exposed. Resources are specified as strings and may contain * for wildcard matches. For example, \"/images/*\" exposes everything in the extension's /images directory recursively while \"*.png\" exposes all PNG files.",
          "items": {
            "$ref": "#/definitions/glob_pattern"
          }
        },
        "matches": {
          "type": "array",
          "description": "A list of URL match patterns specifying which pages can access the resources. Only the origin is used to match URLs; subdomains patterns (*.google.com) and paths are ignored.",
          "items": {
            "$ref": "#/definitions/match_pattern"
          }
        },
        "extension_ids": {
          "type": "array",
          "description": "A list of extension IDs, specifying which extensions can access the resources.",
          "items": {
            "type": "string"
          }
        },
        "use_dynamic_url": {
          "type": "boolean",
          "description": "If true, only allow resources to be accessible through dynamic ID. The dynamic ID is generated per session. It's regenerated on browser restart or extension reload."
        }
      }
    }
  },
  "dependencies": {
    "content_scripts": {
      "not": {
        "required": ["script_badge"]
      }
    },
    "script_badge": {
      "not": {
        "required": ["content_scripts"]
      }
    }
  },
  "else": {
    "properties": {
      "background": {
        "type": "object",
        "description": "The background page is an HTML page that runs in the extension process. It exists for the lifetime of your extension, and only one instance of it at a time is active.",
        "properties": {
          "persistent": {
            "type": "boolean",
            "description": "When false, makes the background page an event page (loaded only when needed).",
            "default": true
          },
          "page": {
            "$ref": "#/definitions/page",
            "description": "Specify the HTML of the background page.",
            "default": "background.html"
          },
          "scripts": {
            "$ref": "#/definitions/scripts",
            "description": "A background page will be generated by the extension system that includes each of the files listed in the scripts property.",
            "default": ["background.js"]
          }
        },
        "dependencies": {
          "page": {
            "not": {
              "required": ["scripts"]
            }
          },
          "scripts": {
            "not": {
              "required": ["page"]
            }
          }
        }
      },
      "browser_action": {
        "$ref": "#/definitions/action_v2",
        "description": "Use browser actions to put icons in the main Google Chrome toolbar, to the right of the address bar. In addition to its icon, a browser action can also have a tooltip, a badge, and a popup."
      },
      "page_action": {
        "$ref": "#/definitions/action_v2",
        "description": "Use the chrome.pageAction API to put icons inside the address bar. Page actions represent actions that can be taken on the current page, but that aren't applicable to all pages."
      },
      "content_security_policy": {
        "$ref": "#/definitions/content_security_policy"
      },
      "web_accessible_resources": {
        "type": "array",
        "description": "An array of strings specifying the paths (relative to the package root) of packaged resources that are expected to be usable in the context of a web page.",
        "minItems": 1,
        "uniqueItems": true,
        "items": {
          "$ref": "#/definitions/uri"
        }
      }
    },
    "dependencies": {
      "page_action": {
        "not": {
          "required": ["browser_action"]
        }
      },
      "browser_action": {
        "not": {
          "required": ["page_action"]
        }
      }
    }
  },
  "if": {
    "properties": {
      "manifest_version": {
        "const": 3
      }
    }
  },
  "properties": {
    "manifest_version": {
      "type": "number",
      "description": "One integer specifying the version of the manifest file format your package requires.",
      "enum": [2, 3]
    },
    "name": {
      "type": "string",
      "description": "The name of the extension",
      "maxLength": 45
    },
    "version": {
      "description": "One to four dot-separated integers identifying the version of this extension.",
      "$ref": "#/definitions/version_string"
    },
    "default_locale": {
      "type": "string",
      "description": "Specifies the subdirectory of _locales that contains the default strings for this extension.",
      "default": "en"
    },
    "description": {
      "type": "string",
      "description": "A plain text description of the extension",
      "maxLength": 132
    },
    "icons": {
      "type": "object",
      "description": "One or more icons that represent the extension, app, or theme. Recommended format: PNG; also BMP, GIF, ICO, JPEG.",
      "minProperties": 1,
      "properties": {
        "16": {
          "$ref": "#/definitions/icon",
          "description": "Used as the favicon for an extension's pages and infobar."
        },
        "48": {
          "$ref": "#/definitions/icon",
          "description": "Used on the extension management page (chrome://extensions)."
        },
        "128": {
          "$ref": "#/definitions/icon",
          "description": "Used during installation and in the Chrome Web Store."
        },
        "256": {
          "$ref": "#/definitions/icon",
          "description": "Used during installation and in the Chrome Web Store."
        }
      }
    },
    "chrome_url_overrides": {
      "type": "object",
      "description": "Override pages are a way to substitute an HTML file from your extension for a page that Google Chrome normally provides.",
      "additionalProperties": false,
      "maxProperties": 1,
      "properties": {
        "bookmarks": {
          "$ref": "#/definitions/page",
          "description": "The page that appears when the user chooses the Bookmark Manager menu item from the Chrome menu or, on Mac, the Bookmark Manager item from the Bookmarks menu. You can also get to this page by entering the URL chrome://bookmarks.",
          "default": "bookmarks.html"
        },
        "history": {
          "$ref": "#/definitions/page",
          "description": "The page that appears when the user chooses the History menu item from the Chrome menu or, on Mac, the Show Full History item from the History menu. You can also get to this page by entering the URL chrome://history.",
          "default": "history.html"
        },
        "newtab": {
          "$ref": "#/definitions/page",
          "description": "The page that appears when the user creates a new tab or window. You can also get to this page by entering the URL chrome://newtab.",
          "default": "newtab.html"
        }
      }
    },
    "commands": {
      "type": "object",
      "description": "Use the commands API to add keyboard shortcuts that trigger actions in your extension, for example, an action to open the browser action or send a command to the extension.",
      "patternProperties": {
        ".*": {
          "$ref": "#/definitions/command"
        },
        "^_execute_browser_action$": {
          "$ref": "#/definitions/command"
        },
        "^_execute_page_action$": {
          "$ref": "#/definitions/command"
        }
      }
    },
    "content_scripts": {
      "type": "array",
      "description": "Content scripts are JavaScript files that run in the context of web pages.",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "required": ["matches"],
        "additionalProperties": false,
        "properties": {
          "matches": {
            "type": "array",
            "description": "Specifies which pages this content script will be injected into.",
            "minItems": 1,
            "uniqueItems": true,
            "items": {
              "$ref": "#/definitions/match_pattern"
            }
          },
          "exclude_matches": {
            "type": "array",
            "description": "Excludes pages that this content script would otherwise be injected into.",
            "uniqueItems": true,
            "items": {
              "$ref": "#/definitions/match_pattern"
            }
          },
          "css": {
            "type": "array",
            "description": "The list of CSS files to be injected into matching pages. These are injected in the order they appear in this array, before any DOM is constructed or displayed for the page.",
            "uniqueItems": true,
            "items": {
              "$ref": "#/definitions/uri"
            }
          },
          "js": {
            "$ref": "#/definitions/scripts",
            "description": "The list of JavaScript files to be injected into matching pages. These are injected in the order they appear in this array."
          },
          "world": {
            "type": "string",
            "description": "The JavaScript world for a script to execute within.",
            "enum": ["ISOLATED", "MAIN"],
            "default": "ISOLATED"
          },
          "run_at": {
            "type": "string",
            "description": "Controls when the files in js are injected.",
            "enum": ["document_start", "document_end", "document_idle"],
            "default": "document_idle"
          },
          "all_frames": {
            "type": "boolean",
            "description": "Controls whether the content script runs in all frames of the matching page, or only the top frame.",
            "default": false
          },
          "include_globs": {
            "type": "array",
            "description": "Applied after matches to include only those URLs that also match this glob. Intended to emulate the @include Greasemonkey keyword.",
            "uniqueItems": true,
            "items": {
              "$ref": "#/definitions/glob_pattern"
            }
          },
          "exclude_globs": {
            "type": "array",
            "description": "Applied after matches to exclude URLs that match this glob. Intended to emulate the @exclude Greasemonkey keyword.",
            "uniqueItems": true,
            "items": {
              "$ref": "#/definitions/glob_pattern"
            }
          },
          "match_about_blank": {
            "type": "boolean",
            "description": "Whether to insert the content script on about:blank and about:srcdoc.",
            "default": false
          }
        }
      }
    },
    "devtools_page": {
      "$ref": "#/definitions/page",
      "description": "A DevTools extension adds functionality to the Chrome DevTools. It can add new UI panels and sidebars, interact with the inspected page, get information about network requests, and more."
    },
    "externally_connectable": {
      "description": "Declares which extensions, apps, and web pages can connect to your extension via runtime.connect and runtime.sendMessage.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "ids": {
          "type": "array",
          "items": {
            "type": "string",
            "description": "The IDs of extensions or apps that are allowed to connect. If left empty or unspecified, no extensions or apps can connect."
          }
        },
        "matches": {
          "type": "array",
          "items": {
            "type": "string",
            "description": "The URL patterns for web pages that are allowed to connect. This does not affect content scripts. If left empty or unspecified, no web pages can connect."
          }
        },
        "accepts_tls_channel_id": {
          "type": "boolean",
          "default": false,
          "description": "Indicates that the extension would like to make use of the TLS channel ID of the web page connecting to it. The web page must also opt to send the TLS channel ID to the extension via setting includeTlsChannelId to true in runtime.connect's connectInfo or runtime.sendMessage's options."
        }
      }
    },
    "file_browser_handlers": {
      "type": "array",
      "description": "You can use this API to enable users to upload files to your website.",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "default_title", "file_filters"],
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "description": "Used by event handling code to differentiate between multiple file handlers"
          },
          "default_title": {
            "type": "string",
            "description": "What the button will display."
          },
          "file_filters": {
            "type": "array",
            "description": "Filetypes to match.",
            "minItems": 1,
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    "homepage_url": {
      "$ref": "#/definitions/uri",
      "description": "The URL of the homepage for this extension."
    },
    "incognito": {
      "type": "string",
      "description": "Specify how this extension will behave if allowed to run in incognito mode.",
      "enum": ["spanning", "split", "not_allowed"],
      "default": "spanning"
    },
    "input_components": {
      "type": "array",
      "description": "Allows your extension to handle keystrokes, set the composition, and manage the candidate window.",
      "items": {
        "type": "object",
        "required": [
          "name",
          "type",
          "id",
          "description",
          "language",
          "layouts"
        ],
        "additionalProperties": false,
        "properties": {
          "name": {
            "type": "string"
          },
          "type": {
            "type": "string"
          },
          "id": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "language": {
            "type": "string"
          },
          "layouts": {
            "type": "array"
          }
        }
      }
    },
    "key": {
      "type": "string",
      "description": "This value can be used to control the unique ID of an extension, app, or theme when it is loaded during development."
    },
    "minimum_chrome_version": {
      "$ref": "#/definitions/version_string",
      "description": "The version of Chrome that your extension, app, or theme requires, if any."
    },
    "nacl_modules": {
      "type": "array",
      "description": "One or more mappings from MIME types to the Native Client module that handles each type.",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "required": ["path", "mime_type"],
        "additionalProperties": false,
        "properties": {
          "path": {
            "$ref": "#/definitions/uri",
            "description": "The location of a Native Client manifest (a .nmf file) within the extension directory."
          },
          "mime_type": {
            "$ref": "#/definitions/mime_type",
            "description": "The MIME type for which the Native Client module will be registered as content handler."
          }
        }
      }
    },
    "oauth2": {
      "type": "object",
      "description": "Use the Chrome Identity API to authenticate users: the getAuthToken for users logged into their Google Account and the launchWebAuthFlow for users logged into a non-Google account.",
      "required": ["client_id", "scopes"],
      "additionalProperties": false,
      "properties": {
        "client_id": {
          "type": "string",
          "description": "You need to register your app in the Google APIs Console to get the client ID."
        },
        "scopes": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        }
      }
    },
    "offline_enabled": {
      "type": "boolean",
      "description": "Whether the app or extension is expected to work offline. When Chrome detects that it is offline, apps with this field set to true will be highlighted on the New Tab page."
    },
    "omnibox": {
      "type": "object",
      "description": "The omnibox API allows you to register a keyword with Google Chrome's address bar, which is also known as the omnibox.",
      "required": ["keyword"],
      "additionalProperties": false,
      "properties": {
        "keyword": {
          "type": "string",
          "description": "The keyword that will trigger your extension."
        }
      }
    },
    "optional_permissions": {
      "$ref": "#/definitions/permissions",
      "description": "Use the chrome.permissions API to request declared optional permissions at run time rather than install time, so users understand why the permissions are needed and grant only those that are necessary."
    },
    "options_page": {
      "$ref": "#/definitions/page",
      "description": "To allow users to customize the behavior of your extension, you may wish to provide an options page. If you do, a link to it will be provided from the extensions management page at chrome://extensions. Clicking the Options link opens a new tab pointing at your options page.",
      "default": "options.html"
    },
    "options_ui": {
      "type": "object",
      "description": "To allow users to customize the behavior of your extension, you may wish to provide an options page. If you do, an Options link will be shown on the extensions management page at chrome://extensions which opens a dialogue containing your options page.",
      "required": ["page"],
      "properties": {
        "page": {
          "type": "string",
          "description": "The path to your options page, relative to your extension's root."
        },
        "chrome_style": {
          "type": "boolean",
          "default": true,
          "description": "If true, a Chrome user agent stylesheet will be applied to your options page. The default value is false, but we recommend you enable it for a consistent UI with Chrome."
        },
        "open_in_tab": {
          "type": "boolean",
          "default": false,
          "description": "If true, your extension's options page will be opened in a new tab rather than embedded in chrome://extensions. The default is false, and we recommend that you don't change it. This is only useful to delay the inevitable deprecation of the old options UI! It will be removed soon, so try not to use it. It will break."
        }
      }
    },
    "permissions": {
      "$ref": "#/definitions/permissions",
      "description": "Permissions help to limit damage if your extension or app is compromised by malware. Some permissions are also displayed to users before installation, as detailed in Permission Warnings."
    },
    "requirements": {
      "type": "object",
      "description": "Technologies required by the app or extension. Hosting sites such as the Chrome Web Store may use this list to dissuade users from installing apps or extensions that will not work on their computer.",
      "additionalProperties": false,
      "properties": {
        "3D": {
          "type": "object",
          "description": "The '3D' requirement denotes GPU hardware acceleration.",
          "required": ["features"],
          "additionalProperties": false,
          "properties": {
            "features": {
              "type": "array",
              "description": "List of the 3D-related features your app requires.",
              "minItems": 1,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "enum": ["webgl"]
              }
            }
          }
        },
        "plugins": {
          "type": "object",
          "description": "Indicates if an app or extension requires NPAPI to run. This requirement is enabled by default when the manifest includes the 'plugins' field.",
          "required": ["npapi"],
          "additionalProperties": false,
          "properties": {
            "npapi": {
              "type": "boolean",
              "default": true
            }
          }
        }
      }
    },
    "sandbox": {
      "type": "object",
      "description": "Defines an collection of app or extension pages that are to be served in a sandboxed unique origin, and optionally a Content Security Policy to use with them.",
      "required": ["pages"],
      "additionalProperties": false,
      "properties": {
        "pages": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/definitions/page"
          }
        },
        "content_security_policy": {
          "$ref": "#/definitions/content_security_policy",
          "default": "sandbox allow-scripts allow-forms"
        }
      }
    },
    "short_name": {
      "type": "string",
      "description": "The short name is typically used where there is insufficient space to display the full name.",
      "maxLength": 12
    },
    "update_url": {
      "$ref": "#/definitions/uri",
      "description": "If you publish using the Chrome Developer Dashboard, ignore this field. If you host your own extension or app: URL to an update manifest XML file."
    },
    "tts_engine": {
      "type": "object",
      "description": "Register itself as a speech engine.",
      "required": ["voices"],
      "additionalProperties": false,
      "properties": {
        "voices": {
          "type": "array",
          "description": "Voices the extension can synthesize.",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "object",
            "required": ["voice_name", "event_types"],
            "additionalProperties": false,
            "properties": {
              "voice_name": {
                "type": "string",
                "description": "Identifies the name of the voice and the engine used."
              },
              "lang": {
                "type": "string",
                "description": "Almost always, a voice can synthesize speech in just a single language. When an engine supports more than one language, it can easily register a separate voice for each language."
              },
              "gender": {
                "type": "string",
                "description": "If your voice corresponds to a male or female voice, you can use this parameter to help clients choose the most appropriate voice for their application."
              },
              "event_types": {
                "type": "array",
                "description": "Events sent to update the client on the progress of speech synthesis.",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "type": "string",
                  "description": "",
                  "enum": [
                    "start",
                    "word",
                    "sentence",
                    "marker",
                    "end",
                    "error"
                  ]
                }
              }
            }
          }
        }
      }
    },
    "version_name": {
      "type": "string",
      "description": "In addition to the version field, which is used for update purposes, version_name can be set to a descriptive version string and will be used for display purposes if present."
    },
    "chrome_settings_overrides": {},
    "content_pack": {},
    "current_locale": {},
    "import": {},
    "platforms": {},
    "signature": {},
    "spellcheck": {},
    "storage": {},
    "system_indicator": {}
  },
  "required": ["manifest_version", "name", "version"],
  "then": {
    "properties": {
      "background": {
        "type": "object",
        "description": "The background page is an HTML page that runs in the extension process. It exists for the lifetime of your extension, and only one instance of it at a time is active.",
        "properties": {
          "service_worker": {
            "type": "string",
            "description": "The service worker js file."
          },
          "type": {
            "type": "string",
            "enum": ["module"]
          }
        },
        "dependencies": {
          "page": {
            "not": {
              "required": ["scripts"]
            }
          },
          "scripts": {
            "not": {
              "required": ["page"]
            }
          }
        }
      },
      "host_permissions": {
        "$ref": "#/definitions/permissions"
      },
      "action": {
        "description": "Used to control the toolbar button for your extension in Chrome's UI.",
        "$ref": "#/definitions/action_v3"
      },
      "content_security_policy": {
        "type": "object",
        "properties": {
          "extension_pages": {
            "description": "This policy covers pages in your extension, including html files and service workers.",
            "$ref": "#/definitions/content_security_policy"
          },
          "sandbox": {
            "description": "This policy covers any sandboxed extension pages that your extension uses.",
            "$ref": "#/definitions/content_security_policy"
          }
        }
      },
      "web_accessible_resources": {
        "type": "array",
        "description": "An array of objects that declare resource access rules. Each object maps an array of extension resources to an array of URLs and/or extension IDs that can access those resources.",
        "minItems": 1,
        "uniqueItems": true,
        "items": {
          "$ref": "#/definitions/web_resource"
        }
      }
    },
    "$comment": "browser_action and page_action are no longer present in v3",
    "dependencies": {
      "browser_action": {
        "not": {
          "required": ["browser_action"]
        }
      },
      "page_action": {
        "not": {
          "required": ["page_action"]
        }
      }
    }
  },
  "title": "JSON schema for Google Chrome extension manifest files",
  "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "fossa-deps",
    "description": "fossa-deps for dependency specification for FOSSA CLI",
    "$defs": {
        "os": {
            "enum": [
                "alpine",
                "centos",
                "debian",
                "redhat",
                "ubuntu",
                "oraclelinux",
                "busybox",
                "sles",
                "fedora"
            ],
            "description": "Name of the distribution OS."
        },
        "referenced-app-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Name of the dependency. This name will be used to search for dependency in relevant registries."
                },
                "type": {
                    "enum": [
                        "bower",
                        "cargo",
                        "carthage",
                        "composer",
                        "cpan",
                        "renv",
                        "gem",
                        "git",
                        "go",
                        "hackage",
                        "hex",
                        "maven",
                        "npm",
                        "nuget",
                        "paket",
                        "pub",
                        "pypi",
                        "cocoapods",
                        "swift",
                        "url"
                    ],
                    "description": "Type of the dependency. It informs FOSSA which relevant registries to search for dependency's distribution."
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency. It informs FOSSA which version of the dependency to scan. If not provided, latest version will be used."
                }
            },
            "required": [
                "name",
                "type"
            ],
            "additionalProperties": false
        },
        "referenced-apk-deb-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Name of the dependency. This name will be used to search for dependency in relevant registries."
                },
                "type": {
                    "enum": [
                        "apk",
                        "deb"
                    ],
                    "description": "Type of the dependency. It informs FOSSA which relevant registries to search for dependency's distribution."
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency. It informs FOSSA which version of the dependency to scan. If not provided, latest version will be used."
                },
                "arch": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Architecture associated with this package"
                },
                "os": {
                    "$ref": "#/$defs/os"
                },
                "osVersion": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Version of the distribution OS."
                }
            },
            "required": [
                "name",
                "type",
                "arch",
                "os",
                "osVersion"
            ],
            "additionalProperties": false
        },
        "referenced-rpm-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Name of the dependency. This name will be used to search for dependency in relevant registries."
                  },
                "type": {
                    "enum": [
                        "rpm-generic"
                    ],
                    "description": "Type of the dependency. It informs FOSSA which relevant registries to search for dependency's distribution."
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency. It informs FOSSA which version of the dependency to scan. If not provided, latest version will be used."
                },
                "arch": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Architecture associated with this package"
                },
                "epoch": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Epoch associated with version (if any)."
                },
                "os": {
                    "$ref": "#/$defs/os"
                },
                "osVersion": {
                    "type": "string",
                    "minLength": 1,
                    "description": "Version of the distribution OS."
                }
            },
            "required": [
                "name",
                "type",
                "arch",
                "os",
                "osVersion"
            ],
            "additionalProperties": false
        },
        "referenced-dependency": {
            "oneOf": [
                {
                    "$ref": "#/$defs/referenced-app-dependency"
                },
                {
                    "$ref": "#/$defs/referenced-apk-deb-dependency"
                },
                {
                    "$ref": "#/$defs/referenced-rpm-dependency"
                }
            ]
        },
        "custom-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the dependency. This will be the name used in FOSSA's dashboard.",
                    "minLength": 1
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency. This will be the version used in FOSSA's dashboard.",
                    "minLength": 1
                },
                "license": {
                    "type": "string",
                    "description": "License of the dependency. This string will be used to infer license type.",
                    "minLength": 1
                },
                "metadata": {
                    "type": "object",
                    "properties": {
                        "description": {
                            "type": "string",
                            "description": "Description of the dependency (if any)"
                        },
                        "homepage": {
                            "type": "string",
                            "description": "Homepage of the dependency. This should be web address."
                        }
                    }
                }
            },
            "required": [
                "name",
                "version",
                "license"
            ],
            "additionalProperties": false
        },
        "vendored-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the dependency. This will be the name associated with this vendored dependency in FOSSA's dashboard",
                    "minLength": 1
                },
                "path": {
                    "type": "string",
                    "description": "Path to directory, which will be archived and upload to provided endpoint for license scanning.",
                    "minLength": 1
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency. This will be the version associated with this vendored dependency in FOSSA's dashboard"
                }
            },
            "required": [
                "name",
                "path"
            ],
            "additionalProperties": false
        },
        "remote-dependency": {
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the dependency. This will be the version used in FOSSA's dashboard.",
                    "minLength": 1
                },
                "url": {
                    "type": "string",
                    "description": "Url of the dependency's source code. This will be the downloaded by FOSSA for scanning with the analysis.",
                    "minLength": 1
                },
                "version": {
                    "type": "string",
                    "description": "Version of the dependency."
                },
                "metadata": {
                    "type": "object",
                    "properties": {
                        "description": {
                            "type": "string",
                            "description": "Description of the dependency (if any)"
                        },
                        "homepage": {
                            "type": "string",
                            "description": "Homepage of the dependency. This should be web address."
                        }
                    }
                }
            },
            "required": [
                "name",
                "url",
                "version"
            ],
            "additionalProperties": false
        }
    },
    "type": "object",
    "properties": {
        "version": {
            "type": "integer"
        },
        "referenced-dependencies": {
            "type": "array",
            "description": "Reference dependency to locate from registry and include it project's dependency and license scanning.",
            "items": {
                "$ref": "#/$defs/referenced-dependency"
            }
        },
        "custom-dependencies": {
            "type": "array",
            "description": "Custom dependency and their license for project",
            "items": {
                "$ref": "#/$defs/custom-dependency"
            }
        },
        "vendored-dependencies": {
            "type": "array",
            "description": "Local dependencies upload to server for license scanning",
            "items": {
                "$ref": "#/$defs/vendored-dependency"
            }
        },
        "remote-dependencies": {
            "type": "array",
            "description": "Remote dependencies to license scanning",
            "items": {
                "$ref": "#/$defs/remote-dependency"
            }
        }
    },
    "required": []
}

{
    "title": "NTangle - https://github.com/Avanade/ntangle",
    "$schema": "http://json-schema.org/draft-04/schema",
    "definitions": {
        "Root": {
            "type": "object",
            "title": "The 'Root' object (database-driven)",
            "description": "The 'RootConfig' object defines the global properties that are used to drive the underlying database-driven CDC-oriented code-generation.",
            "properties": {
                "schema": {
                    "type": "string",
                    "title": "The default 'Schema' name where the existing tables are defined within the database.",
                    "description": "This is used as the default 'Schema' for all child objects. Defaults to 'dbo' (literal)."
                },
                "cdcSchema": {
                    "type": "string",
                    "title": "The schema name for the _ntangle_ generated 'CDC'-related database artefacts.",
                    "description": "Defaults to 'NTangle' (literal)."
                },
                "cdcSchemaCreate": {
                    "type": "boolean",
                    "title": "Indicates whether to create the 'CdcSchema' within the database.",
                    "description": "Defaults to 'false'."
                },
                "versionTrackingTable": {
                    "type": "string",
                    "title": "The table name for the 'Cdc'-VersionTracking.",
                    "description": "Defaults to 'VersionTracking' (literal)."
                },
                "cdcEnable": {
                    "type": "boolean",
                    "title": "Indicates whether to enable 'Cdc' within the database for the tables that participate.",
                    "description": "Defaults to 'false'. This option can be overridden for each underlying table referenced."
                },
                "identifierMapping": {
                    "type": "boolean",
                    "title": "Indicates whether to include the generation of the generic 'CDC'-IdentifierMapping database capabilities.",
                    "description": "Where set to 'true' each underlying 'Table' and corresponding 'Join' must set 'IdentifierMapping' explicitly."
                },
                "identifierMappingType": {
                    "type": "string",
                    "title": "The type for the identifier mapping value.",
                    "description": "Defaults to 'String'.",
                    "enum": [
                        "String",
                        "Int",
                        "Long",
                        "Guid"
                    ]
                },
                "identifierMappingTable": {
                    "type": "string",
                    "title": "The table name for the 'Cdc'-IdentifierMapping.",
                    "description": "Defaults to 'IdentifierMapping' (literal)."
                },
                "identifierMappingStoredProcedure": {
                    "type": "string",
                    "title": "The stored procedure name for the 'Cdc'-IdentifierMapping create.",
                    "description": "Defaults to 'spIdentifierMappingCreate' (literal)."
                },
                "isDeletedColumn": {
                    "type": "string",
                    "title": "The column name for the 'IsDeleted' (logical delete) capability (if any).",
                    "description": "Defaults to 'IsDeleted'."
                },
                "autoDotNetRename": {
                    "type": "string",
                    "title": "The option to automatically rename the SQL Tables and Columns for use in .NET.",
                    "description": "Defaults to 'SnakeKebabToPascalCase' which will remove any underscores or hyphens separating each word and capitalize the first character of each; e.g. 'internal-customer_id' would be renamed as 'InternalCustomerId'. The 'PascalCase' option will capatilize the first character only.",
                    "enum": [
                        "None",
                        "PascalCase",
                        "SnakeKebabToPascalCase"
                    ]
                },
                "excludeColumnsFromETag": {
                    "type": "array",
                    "title": "The default list of 'Column' names that should be excluded from the generated ETag (used for the likes of duplicate send tracking)",
                    "items": {
                        "type": "string"
                    }
                },
                "jsonSerializer": {
                    "type": "string",
                    "title": "The JSON Serializer to use for JSON property attribution.",
                    "description": "Defaults to 'SystemText'.",
                    "enum": [
                        "SystemText",
                        "Newtonsoft"
                    ]
                },
                "service": {
                    "type": "string",
                    "title": "The type of service that manages the underlying orchestrator.",
                    "description": "Defaults to 'None'. A 'HostedService' is an 'IHostedService' implementation enabling long-running execution; whereas, 'Service' is intended for self-managed execution.",
                    "enum": [
                        "None",
                        "HostedService",
                        "Service"
                    ]
                },
                "eventSubjectRoot": {
                    "type": "string",
                    "title": "The root for the event name by prepending to all event subject names via CDC.",
                    "description": "Used to enable the sending of messages to the likes of EventHubs, Service Broker, Kafka, etc."
                },
                "eventSubjectFormat": {
                    "type": "string",
                    "title": "The default formatting for the Subject when an Event is published via CDC.",
                    "description": "Defaults to 'NameOnly'.",
                    "enum": [
                        "NameOnly",
                        "NameAndKey",
                        "NameAndTableKey"
                    ]
                },
                "eventActionFormat": {
                    "type": "string",
                    "title": "The formatting for the Action when an Event is published via CDC.",
                    "description": "Defaults to 'None' (no formatting required, i.e. as-is).",
                    "enum": [
                        "None",
                        "PastTense"
                    ]
                },
                "eventSourceKind": {
                    "type": "string",
                    "title": "The URI kind for the event source URIs for CDC.",
                    "description": "Defaults to 'Relative' (being a relative path).",
                    "enum": [
                        "None",
                        "Absolute",
                        "Relative",
                        "RelativeOrAbsolute"
                    ]
                },
                "eventSourceRoot": {
                    "type": "string",
                    "title": "The URI root for the event source by prepending to all event source URIs for CDC.",
                    "description": "The event source is only updated where an 'EventSourceKind' is not 'None'."
                },
                "eventSourceFormat": {
                    "type": "string",
                    "title": "The default formatting for the Source when an Event is published via CDC.",
                    "description": "Defaults to 'NameAndTableKey' (being the child 'Cdc.ModelName' appended with the corresponding table key).",
                    "enum": [
                        "NameOnly",
                        "NameAndKey",
                        "NameAndTableKey"
                    ]
                },
                "eventTypeRoot": {
                    "type": "string",
                    "title": "The root for the event type by prepending to all event type names via CDC.",
                    "description": "Used to enable the sending of messages to the likes of EventHubs, Service Broker, Kafka, etc. Defaults to 'EventSubjectRoot'."
                },
                "outbox": {
                    "type": "boolean",
                    "title": "Indicates whether to generate the event outbox SQL and .NET artefacts.",
                    "description": "Defaults to 'false'."
                },
                "outboxSchema": {
                    "type": "string",
                    "title": "The schema name of the event outbox table.",
                    "description": "Defaults to 'Outbox' (literal)."
                },
                "outboxSchemaCreate": {
                    "type": "boolean",
                    "title": "Indicates whether to create the 'OutboxSchema' within the database.",
                    "description": "Defaults to 'false'."
                },
                "outboxTable": {
                    "type": "string",
                    "title": "The name of the event outbox table.",
                    "description": "Defaults to 'EventOutbox' (literal)."
                },
                "outboxEnqueueStoredProcedure": {
                    "type": "string",
                    "title": "The stored procedure name for the event outbox enqueue.",
                    "description": "Defaults to 'spEventOutboxEnqueue' (literal)."
                },
                "outboxDequeueStoredProcedure": {
                    "type": "string",
                    "title": "The stored procedure name for the event outbox dequeue.",
                    "description": "Defaults to 'spEventOutboxDequeue' (literal)."
                },
                "pathBase": {
                    "type": "string",
                    "title": "The base path (directory) prefix for the Database-related artefacts; other 'Path*' properties append to this value when they are not specifically overridden.",
                    "description": "Defaults to 'AppName' (runtime parameter). For example 'Avanade.Application'."
                },
                "pathDatabase": {
                    "type": "string",
                    "title": "The path (directory) for the Schema Database-related artefacts.",
                    "description": "Defaults to 'PathBase' + '.Database' (literal). For example 'Avanade.Application.Database'."
                },
                "pathDatabaseSchema": {
                    "type": "string",
                    "title": "The path (directory) for the Schema Database-related artefacts.",
                    "description": "Defaults to 'PathDatabase' + '/Schema' (literal). For example 'Avanade.Application.Database/Schema'."
                },
                "pathDatabaseMigrations": {
                    "type": "string",
                    "title": "The path (directory) for the Schema Database-related artefacts.",
                    "description": "Defaults to 'PathDatabase' + '/Migrations' (literal). For example 'Avanade.Application.Database/Migrations'."
                },
                "pathDotNetPublisher": {
                    "type": "string",
                    "title": "The path (directory) for the CDC-related (.NET) artefacts.",
                    "description": "Defaults to 'PathBase' + '.Publisher' (literal). For example 'Avanade.Application.Publisher'."
                },
                "namespaceBase": {
                    "type": "string",
                    "title": "The base Namespace (root) for the .NET artefacts.",
                    "description": "Defaults to 'AppName' (runtime parameter). For example 'Avanade.Application'."
                },
                "namespacePublisher": {
                    "type": "string",
                    "title": "The Namespace (root) for the CDC-related Publisher .NET artefacts.",
                    "description": "Defaults to 'NamespaceBase' + '.Publisher' (literal). For example 'Avanade.Application.Publisher'."
                },
                "namespaceOutbox": {
                    "type": "string",
                    "title": "The Namespace (root) for the Outbox-related Publisher .NET artefacts.",
                    "description": "Defaults to 'NamespacePublisher'."
                },
                "tables": {
                    "type": "array",
                    "title": "The corresponding 'Table' collection.",
                    "description": "A 'Table' object provides the primary database table configuration for Change Data Capture (CDC), including multiple child table joins to form a composite entity.",
                    "items": {
                        "$ref": "#/definitions/Table"
                    }
                }
            }
        },
        "Table": {
            "type": "object",
            "title": "'Table' object (database-driven)",
            "description": "The 'Table' object enables the definition of the primary table, one-or-more child tables and their respective join relationships, to enable Change Data Capture (CDC) event publishing. The 'IncludeColumns' and 'ExcludeColumns' provide a shorthand to include or exclude selected columns; with the 'AliasColumns' providing a means to rename where required.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The name of the primary table."
                },
                "schema": {
                    "type": "string",
                    "title": "The default schema name used where not otherwise explicitly specified.",
                    "description": "Defaults to 'Root.Schema'."
                },
                "table": {
                    "type": "string",
                    "title": "The name of the primary table.",
                    "description": "Defaults to 'Name'. This is used to specify the actual underlying database table name (required where the 'Name' has been changed to enable uniqueness)."
                },
                "alias": {
                    "type": "string",
                    "title": "The table alias name (must be unique).",
                    "description": "Will automatically default where not specified; for example a table named 'Person' will default to 'p'."
                },
                "includeColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names to be included in the underlying generated output.",
                    "description": "Where not specified this indicates that all 'Columns' are to be included.",
                    "items": {
                        "type": "string"
                    }
                },
                "excludeColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names to be excluded from the underlying generated output.",
                    "description": "Where not specified this indicates no 'Columns' are to be excluded.",
                    "items": {
                        "type": "string"
                    }
                },
                "aliasColumns": {
                    "type": "array",
                    "title": "The list of 'Column' and 'Alias' pairs (split by a '^' lookup character) to enable column aliasing/renaming.",
                    "description": "Each alias value should be formatted as 'Column' + '^' + 'Alias'; e.g. 'PCODE^ProductCode'.",
                    "items": {
                        "type": "string"
                    }
                },
                "executeStoredProcedure": {
                    "type": "string",
                    "title": "The 'CDC' _execute_ batch stored procedure name.",
                    "description": "Defaults to 'sp' (literal) + 'Name' + 'BatchExecute' (literal); e.g. 'spNameBatchExecute'."
                },
                "completeStoredProcedure": {
                    "type": "string",
                    "title": "The 'CDC' _complete_ batch stored procedure name.",
                    "description": "Defaults to 'sp' (literal) + 'Name' + 'BatchComplete' (literal); e.g. 'spNameBatchComplete'."
                },
                "cdcSchema": {
                    "type": "string",
                    "title": "The schema name for the generated 'CDC'-related database artefacts.",
                    "description": "Defaults to 'Root.CdcSchema'."
                },
                "batchTrackingTable": {
                    "type": "string",
                    "title": "The corresponding 'CDC' Batch tracking table name.",
                    "description": "Defaults to 'Name' + 'BatchTracking' (literal)."
                },
                "cdcEnable": {
                    "type": "boolean",
                    "title": "Indicates whether to enable 'Cdc' within the database for the tables that participate.",
                    "description": "Defaults to 'false'. This option can be overridden for each underlying table referenced."
                },
                "model": {
                    "type": "string",
                    "title": "The .NET model name.",
                    "description": "Defaults to 'Name'."
                },
                "orchestratorCtorParams": {
                    "type": "array",
                    "title": "The list of additional (non-default) Dependency Injection (DI) parameters for the generated CDC 'Orchestrator' constructor.",
                    "description": "Each constructor parameter should be formatted as 'Type' + '^' + 'Name'; e.g. 'IConfiguration^Config'. Where the 'Name' portion is not specified it will be inferred.",
                    "items": {
                        "type": "string"
                    }
                },
                "database": {
                    "type": "string",
                    "title": "The .NET database 'IDatabase' Type name used in the constructor for Dependency Injection (DI).",
                    "description": "Defaults to 'IDatabase'."
                },
                "includeColumnsOnDelete": {
                    "type": "array",
                    "title": "The list of 'Column' names that should be included (in addition to the primary key) for a logical delete.",
                    "description": "Where a column is not specified in this list its corresponding .NET property will be automatically cleared by the 'CdcDataOrchestrator' as the data is technically considered as non-existing.",
                    "items": {
                        "type": "string"
                    }
                },
                "service": {
                    "type": "string",
                    "title": "The type of service that manages the underlying orchestrator.",
                    "description": "Defaults to 'Root.Service'. A 'HostedService' is an 'IHostedService' implementation enabling long-running execution; whereas, 'Service' is intended for self-managed execution.",
                    "enum": [
                        "None",
                        "HostedService",
                        "Service"
                    ]
                },
                "excludeColumnsFromETag": {
                    "type": "array",
                    "title": "The list of 'Column' names that should be excluded from the generated ETag (used for the likes of duplicate send tracking).",
                    "description": "Defaults to 'Root.CdcExcludeColumnsFromETag'.",
                    "items": {
                        "type": "string"
                    }
                },
                "tenantIdColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names that represent the tenant identifier.",
                    "items": {
                        "type": "string"
                    }
                },
                "partitionKey": {
                    "type": "string",
                    "title": "The partition key.",
                    "description": "A partition key can be specified using either 'PartitionKey' or 'PartitionKeyColumns'."
                },
                "partitionKeyColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names that represent the partition key.",
                    "description": "A partition key can be specified using either 'PartitionKey' or 'PartitionKeyColumns'.",
                    "items": {
                        "type": "string"
                    }
                },
                "eventSource": {
                    "type": "string",
                    "title": "The Event Source.",
                    "description": "Defaults to 'Schema' + '/' (literal) + 'Name' (as lowercase). Note: when used in code-generation the 'Root.EventSourceRoot' will be prepended where specified."
                },
                "eventSourceFormat": {
                    "type": "string",
                    "title": "The default formatting for the Source when an Event is published.",
                    "description": "Defaults to 'Root.EventSourceFormat'.",
                    "enum": [
                        "NameOnly",
                        "NameAndKey",
                        "NameAndTableKey"
                    ]
                },
                "eventSubject": {
                    "type": "string",
                    "title": "The Event Subject.",
                    "description": "Defaults to 'ModelName'. Note: when used in code-generation the 'Root.EventSubjectRoot' will be prepended where specified."
                },
                "eventSubjectFormat": {
                    "type": "string",
                    "title": "The default formatting for the Subject when an Event is published.",
                    "description": "Defaults to 'Root.EventSubjectFormat'.",
                    "enum": [
                        "NameOnly",
                        "NameAndKey",
                        "NameAndTableKey"
                    ]
                },
                "eventType": {
                    "type": "string",
                    "title": "The Event Type.",
                    "description": "Defaults to 'ModelName'. Note: when used in code-generation the 'Root.EventTypeRoot' will be prepended where specified."
                },
                "identifierMapping": {
                    "type": "boolean",
                    "title": "Indicates whether to perform Identifier Mapping (mapping to 'GlobalId') for the primary key.",
                    "description": "This indicates whether to create a new 'GlobalId' property on the _entity_ to house the global mapping identifier to be the reference outside of the specific database realm as a replacement to the existing primary key column(s)."
                },
                "identifierName": {
                    "type": "string",
                    "title": "The JSON name for the 'GlobalId' property where 'IdentifierMapping' is 'true'. Defaults to 'globalId'.",
                    "description": "This indicates whether to create a new 'GlobalId' property on the _entity_ to house the global mapping identifier to be the reference outside of the specific database realm as a replacement to the existing primary key column(s)."
                },
                "isDeletedColumn": {
                    "type": "string",
                    "title": "The column name for the 'IsDeleted' (logical delete) capability (if any).",
                    "description": "Defaults to 'Root.ColumnIsDeleted'."
                },
                "joins": {
                    "type": "array",
                    "title": "The corresponding 'Join' collection.",
                    "description": "A 'Join' object provides the configuration for a table join.",
                    "items": {
                        "$ref": "#/definitions/Join"
                    }
                },
                "where": {
                    "type": "array",
                    "title": "The corresponding 'Where' collection.",
                    "description": "A 'Where' object provides the configuration for a table where clause.",
                    "items": {
                        "$ref": "#/definitions/Where"
                    }
                },
                "mappings": {
                    "type": "array",
                    "title": "The corresponding 'TableMapping' collection.",
                    "items": {
                        "$ref": "#/definitions/TableMapping"
                    }
                }
            },
            "required": [
                "name"
            ]
        },
        "Join": {
            "type": "object",
            "title": "'Join' object (database-driven)",
            "description": "The 'Join' object defines a join to another (or same) table within the logical CDC entity.  The 'IncludeColumns' and 'ExcludeColumns' provide a shorthand to include or exclude selected columns; with the 'AliasColumns' providing a means to rename where required.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The unique name.",
                    "description": "A unique name is required where the same 'Table' is referenced more than once within a logical CDC entity. However, generally, this will represent the unique name of the table within the database."
                },
                "schema": {
                    "type": "string",
                    "title": "The schema name of the table to join.",
                    "description": "Defaults to 'Cdc.Schema'; i.e. same schema."
                },
                "table": {
                    "type": "string",
                    "title": "The name of the table to join.",
                    "description": "Defaults to 'Name'. This is used to specify the actual underlying database table name (required where the 'Name' has been changed to enable uniqueness)."
                },
                "alias": {
                    "type": "string",
                    "title": "The 'Schema' and 'Table' alias name.",
                    "description": "Will automatically default where not specified."
                },
                "type": {
                    "type": "string",
                    "title": "The SQL join type.",
                    "description": "Defaults to 'Cdc'. The 'Cdc' value indicates this is a related secondary table (within a logical CDC entity) that also has Change Data Capture turned on and equally needs to be monitored for changes.",
                    "enum": [
                        "Cdc",
                        "Inner",
                        "Left",
                        "Right",
                        "Full"
                    ]
                },
                "joinTo": {
                    "type": "string",
                    "title": "The name of the table to join to (must be previously specified).",
                    "description": "Defaults to parent 'Table.Name'."
                },
                "joinCardinality": {
                    "type": "string",
                    "title": "The join cardinality being whether there is a One-to-Many or One-to-One relationship.",
                    "description": "Defaults to 'OneToMany'. This represents the Parent ('JoinTo') to child (_this_) relationship.",
                    "enum": [
                        "OneToMany",
                        "OneToOne"
                    ]
                },
                "cdcEnable": {
                    "type": "boolean",
                    "title": "Indicates whether to enable 'Cdc' within the database for the tables that participate.",
                    "description": "Defaults to 'false'. This option can be overridden for each underlying table referenced."
                },
                "querySizeMultiplier": {
                    "type": "number",
                    "title": "The query size multiplier for the CDC-Join.",
                    "description": "Defaults to '1.0'. This is applied to the execute stored procedure '@MaxQuerySize' parameter to allow tailoring on the join query ('TOP') sizes to optimize selection. Must be greater than zero and less than or equal to 100."
                },
                "includeColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names to be included in the underlying generated output.",
                    "description": "Where not specified this indicates that all 'Columns' are to be included.",
                    "items": {
                        "type": "string"
                    }
                },
                "excludeColumns": {
                    "type": "array",
                    "title": "The list of 'Column' names to be excluded from the underlying generated output.",
                    "description": "Where not specified this indicates no 'Columns' are to be excluded.",
                    "items": {
                        "type": "string"
                    }
                },
                "aliasColumns": {
                    "type": "array",
                    "title": "The list of 'Column' and 'Alias' pairs (split by a '^' lookup character) to enable column renaming.",
                    "description": "Each alias value should be formatted as 'Column' + '^' + 'Alias'; e.g. 'PCODE^ProductCode'",
                    "items": {
                        "type": "string"
                    }
                },
                "model": {
                    "type": "string",
                    "title": "The .NET model name.",
                    "description": "Defaults to 'Name'."
                },
                "property": {
                    "type": "string",
                    "title": "The .NET property name.",
                    "description": "Defaults to 'Model' where 'JoinCardinality' is 'OneToOne'; otherwise, it will be the 'Model' pluralized."
                },
                "includeColumnsOnDelete": {
                    "type": "array",
                    "title": "The list of 'Column' names that should be included (in addition to the primary key) for a logical delete.",
                    "description": "Where a column is not specified in this list its corresponding .NET property will be automatically cleared by the 'CdcDataOrchestrator' as the data is technically considered as non-existing.",
                    "items": {
                        "type": "string"
                    }
                },
                "excludeColumnsFromETag": {
                    "type": "array",
                    "title": "The list of 'Column' names that should be excluded from the generated ETag (used for the likes of duplicate send tracking).",
                    "description": "Defaults to 'CodeGeneration.CdcExcludeColumnsFromETag'.",
                    "items": {
                        "type": "string"
                    }
                },
                "identifierMapping": {
                    "type": "boolean",
                    "title": "Indicates whether to perform Identifier Mapping (mapping to 'GlobalId') for the primary key.",
                    "description": "This indicates whether to create a new 'GlobalId' property on the _entity_ to house the global mapping identifier to be the reference outside of the specific database realm as a replacement to the existing primary key column(s)."
                },
                "identifierName": {
                    "type": "string",
                    "title": "The JSON name for the 'GlobalId' property where 'IdentifierMapping' is 'true'. Defaults to 'globalId'.",
                    "description": "This indicates whether to create a new 'GlobalId' property on the _entity_ to house the global mapping identifier to be the reference outside of the specific database realm as a replacement to the existing primary key column(s)."
                },
                "on": {
                    "type": "array",
                    "title": "The corresponding 'JoinOn' collection.",
                    "items": {
                        "$ref": "#/definitions/JoinOn"
                    }
                },
                "mappings": {
                    "type": "array",
                    "title": "The corresponding 'JoinMapping' collection.",
                    "items": {
                        "$ref": "#/definitions/JoinMapping"
                    }
                }
            },
            "required": [
                "name"
            ]
        },
        "JoinOn": {
            "type": "object",
            "title": "'JoinOn' object (database-driven)",
            "description": "The 'JoinOn' object defines the join on characteristics for a 'Join' object.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The name of the join column (from the 'Join' table)."
                },
                "toColumn": {
                    "type": "string",
                    "title": "The name of the join to column.",
                    "description": "Defaults to 'Name'; i.e. assumes same name."
                },
                "toStatement": {
                    "type": "string",
                    "title": "The SQL statement for the join on bypassing the corresponding 'ToColumn' specification."
                }
            },
            "required": [
                "name"
            ]
        },
        "JoinMapping": {
            "type": "object",
            "title": "'JoinMapping' object (database-driven)",
            "description": "The 'JoinMapping' object defines one or more related table identifier mappings.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The name of of the existing column that requires identifier mapping."
                },
                "schema": {
                    "type": "string",
                    "title": "The schema name of the related table.",
                    "description": "Defaults to the owning (parent) table schema."
                },
                "table": {
                    "type": "string",
                    "title": "The name of the related table."
                }
            },
            "required": [
                "name",
                "table"
            ]
        },
        "Where": {
            "type": "object",
            "title": "'Where' object (database-driven)",
            "description": "This should only be used where the column value is largely immutable; otherwise, unintended side-effects may occur. _NTangle_ uses the condition explictily and does not attempt to handle value change to infer creation or deletion of data as a result of the underlying change; as such, this should be used cautiously. Note that the 'where' is applied when querying the 'cdc.fn_cdc_get_all_changes_...' function, not the underlying table itself.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The column name.",
                    "description": "The column name."
                },
                "nullable": {
                    "type": "string",
                    "title": "The where nullability clause operator",
                    "description": "This enables statements such as 'WHERE (COL IS NULL)' or 'WHERE (COL IS NULL OR COL = VALUE)' (where .",
                    "enum": [
                        "ISNULL",
                        "ISNOTNULL"
                    ]
                },
                "operator": {
                    "type": "string",
                    "title": "The where clause equality operator",
                    "description": "Defaults to 'EQ' where 'Value' is specified.",
                    "enum": [
                        "EQ",
                        "NE",
                        "LT",
                        "LE",
                        "GT",
                        "GE",
                        "LIKE"
                    ]
                },
                "value": {
                    "type": "string",
                    "title": "The comparison value",
                    "description": "This must be valid formatted/escaped SQL."
                }
            },
            "required": [
                "name"
            ]
        },
        "TableMapping": {
            "type": "object",
            "title": "'TableMapping' object (database-driven)",
            "description": "The 'TableMapping' object defines one or more related table identifier mappings.",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "The name of of the existing column that requires identifier mapping."
                },
                "schema": {
                    "type": "string",
                    "title": "The schema name of the related table.",
                    "description": "Defaults to the owning (parent) table schema."
                },
                "table": {
                    "type": "string",
                    "title": "The name of the related table."
                }
            },
            "required": [
                "name",
                "table"
            ]
        }
    },
    "allOf": [
        {
            "$ref": "#/definitions/Root"
        }
    ]
}

