                  },
                  {
                    "type": "array",
                    "items": {
                      "type": "string",
                      "enum": ["Windows", "Linux", "OSX"]
                    }
                  }
                ]
              }
            }
          },
          {
            "description": "Host constraint. Allows to restrict the template to be run only on specific applications using template engine.",
            "properties": {
