                  },
                  {
                    "type": "array",
                    "items": {
                      "type": "string",
                      "description": "The supported version of the SDK. May be an exact version, float version or version range. Refer to https://docs.microsoft.com/en-us/nuget/concepts/package-versioning for more info."
                    }
                  }
                ]
              }
