    },
    "cyclomatic_complexity": {
      "description": "Examine the complexity of your application. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "value": {
          "type": "integer"
        }
      }
    },
    "duplicate_key": {
      "description": "Prevents defining duplicate keys in object literals and classes. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "empty_constructor_needs_parens": {
      "description": "Requires constructors with no parameters to include the parens. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "ensure_comprehensions": {
      "description": "This rule makes sure that parentheses are around comprehensions. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "eol_last": {
      "description": "Checks that the file ends with a single newline. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "indentation": {
      "description": "This rule imposes a standard number of spaces to be used for indentation. Since whitespace is significant in CoffeeScript, it's critical that a project chooses a standard indentation format and stays consistent. Other roads lead to darkness. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "value": {
          "type": "integer",
          "enum": [2, 4]
        }
      }
    },
    "line_endings": {
      "description": "This rule ensures your project uses only windows or unix line endings. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "value": {
          "type": "string",
          "enum": ["unix", "windows"]
        }
      }
    },
    "max_line_length": {
      "description": "This rule imposes a maximum line length on your code. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "value": {
          "type": "integer"
        },
        "limitComments": {
          "type": "boolean"
        }
      }
    },
    "missing_fat_arrows": {
      "description": "Warns when you use `this` inside a function that wasn't defined with a fat arrow. This rule does not apply to methods defined in a class, since they have `this` bound to the class instance (or the class itself, for class methods). [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "newlines_after_classes": {
      "description": "Checks the number of newlines between classes and other code. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "value": {
          "type": "integer"
        }
      }
    },
    "no_backticks": {
      "description": "Backticks allow snippets of JavaScript to be embedded in CoffeeScript. While some folks consider backticks useful in a few niche circumstances, they should be avoided because so none of JavaScript's 'bad parts', like with and eval, sneak into CoffeeScript. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_debugger": {
      "description": "This rule detects the `debugger` statement. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_empty_functions": {
      "description": "Disallows declaring empty functions. The goal of this rule is that unintentional empty callbacks can be detected. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_empty_param_list": {
      "description": "This rule prohibits empty parameter lists in function definitions. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_implicit_braces": {
      "description": "This rule prohibits implicit braces when declaring object literals. Implicit braces can make code more difficult to understand, especially when used in combination with optional parenthesis. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "strict": {
          "type": "boolean"
        }
      }
    },
    "no_implicit_parens": {
      "description": "This rule prohibits implicit parens on function calls. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_interpolation_in_single_quotes": {
      "description": "This rule prohibits string interpolation in a single quoted string. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_nested_string_interpolation": {
      "description": "This rule warns about nested string interpolation, as it tends to make code harder to read and understand. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_plusplus": {
      "description": "This rule forbids the increment and decrement arithmetic operators. Some people believe the `++` and `--` to be cryptic and the cause of bugs due to misunderstandings of their precedence rules. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_private_function_fat_arrows": {
      "description": "Warns when you use the fat arrow for a private function inside a class definition scope. It is not necessary and it does not do anything. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_stand_alone_at": {
      "description": "This rule checks that no stand alone `@` are in use, they are discouraged. [default level: ignore]",
      "type": "object",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_tabs": {
      "description": "This rule forbids tabs in indentation. Enough said. [default level: error]",
      "type": "object",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_this": {
      "description": "This rule prohibits `this`. Use `@` instead. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_throwing_strings": {
      "description": "This rule forbids throwing string literals or interpolations. While JavaScript (and CoffeeScript by extension) allow any expression to be thrown, it is best to only throw `Error` objects, because they contain valuable debugging information like the stack trace. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_trailing_semicolons": {
      "description": "This rule prohibits trailing semicolons, since they are needless cruft in CoffeeScript. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_trailing_whitespace": {
      "description": "This rule forbids trailing whitespace in your code, since it is needless cruft. [default level: error]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ],
      "properties": {
        "allowed_in_comments": {
          "type": "boolean"
        },
        "allowed_in_empty_lines": {
          "type": "boolean"
        }
      }
    },
    "no_unnecessary_double_quotes": {
      "description": "This rule prohibits double quotes unless string interpolation is used or the string contains single quotes. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "no_unnecessary_fat_arrows": {
      "description": "Disallows defining functions with fat arrows when `this` is not used within the function.  [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "non_empty_constructor_needs_parens": {
      "description": "Requires constructors with parameters to include the parens. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "prefer_english_operator": {
      "description": "This rule prohibits `&&`, `||`, `==`, `!=` and `!`. Use `and`, `or`, `is`, `isnt`, and `not` instead. `!!` (for converting to a boolean) is ignored. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "space_operators": {
      "description": "This rule enforces that operators have space around them.  [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "spacing_after_comma": {
      "description": "This rule checks to make sure you have a space after commas. [default level: ignore]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "transform_messes_up_line_numbers": {
      "description": "This rule detects when changes are made by transform function, and warns that line numbers are probably incorrect. [default level: warn]",
      "allOf": [
        {
          "$ref": "#/definitions/base"
        }
      ]
    }
  },
  "title": "JSON schema for coffeelint.json files",
  "type": "object"
}

{
	"title": "JSON schema for WordPress block theme global settings and styles",
	"$schema": "http://json-schema.org/draft-04/schema#",
	"definitions": {
		"//": {
			"explainer": "https://developer.wordpress.org/themes/advanced-topics/theme-json/",
			"createTheme": "https://developer.wordpress.org/block-editor/how-to-guides/themes/create-block-theme/",
			"reference": "https://developer.wordpress.org/block-editor/how-to-guides/themes/theme-json/"
		},
		"behaviorsBlocksPropertiesComplete": {
			"type": "object",
			"properties": {
				"lightbox": {
					"description": "Settings related to the lightbox behavior.",
					"type": "object",
					"properties": {
						"enabled": {
							"description": "Allow users to enable the lightbox behavior.",
							"type": "boolean",
							"default": false
						},
						"animation": {
							"description": "Set lightbox animation. Possible values: `fade`, `zoom`, `''` (empty string).",
							"type": "string",
							"enum": [ "fade", "zoom", "" ]
						}
					},
					"additionalProperties": false
				}
			},
			"additionalProperties": false
		},
		"refComplete": {
			"type": "object",
			"properties": {
				"ref": {
					"description": "A reference to another property value. e.g. `styles.color.text`",
					"type": "string"
				}
			}
		},
		"settingsPropertiesAppearanceTools": {
			"type": "object",
			"properties": {
				"appearanceTools": {
					"description": "Setting that enables the following UI tools:\n\n- border: color, radius, style, width\n- color: link\n- dimensions: minHeight\n- position: sticky\n- spacing: blockGap, margin, padding\n- typography: lineHeight",
					"type": "boolean",
					"default": false
				}
			}
		},
		"settingsPropertiesUseRootPaddingAwareAlignments": {
			"properties": {
				"useRootPaddingAwareAlignments": {
					"description": "_**Note:** Since WordPress 6.1._\n\nEnables root padding (the values from `styles.spacing.padding`) to be applied to the contents of full-width blocks instead of the root block.\n\nPlease note that when using this setting, `styles.spacing.padding` should always be set as an object with `top`, `right`, `bottom`, `left` values declared separately.",
					"type": "boolean",
					"default": false
				}
			}
		},
		"settingsPropertiesBorder": {
			"type": "object",
			"properties": {
				"border": {
					"description": "Settings related to borders.",
					"type": "object",
					"properties": {
						"color": {
							"description": "Allow users to set custom border colors.",
							"type": "boolean",
							"default": false
						},
						"radius": {
							"description": "Allow users to set custom border radius.",
							"type": "boolean",
							"default": false
						},
						"style": {
							"description": "Allow users to set custom border styles.",
							"type": "boolean",
							"default": false
						},
						"width": {
							"description": "Allow users to set custom border widths.",
							"type": "boolean",
							"default": false
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesShadow": {
			"type": "object",
			"properties": {
				"shadow": {
					"description": "Settings related to shadows.",
					"type": "object",
					"properties": {
						"defaultPresets": {
							"description": "Allow users to choose shadows from the default shadow presets.",
							"type": "boolean",
							"default": true
						},
						"presets": {
							"description": "Shadow presets for the shadow picker.\nGenerates a single custom property (`--wp--preset--shadow--{slug}`) per preset value.",
							"type": "array",
							"items": {
								"type": "object",
								"properties": {
									"name": {
										"description": "Name of the shadow preset, translatable.",
										"type": "string"
									},
									"slug": {
										"description": "Kebab-case unique identifier for the shadow preset.",
										"type": "string"
									},
									"shadow": {
										"description": "CSS box-shadow value",
										"type": "string"
									}
								},
								"required": [ "name", "slug", "shadow" ],
								"additionalProperties": false
							}
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesColor": {
			"type": "object",
			"properties": {
				"color": {
					"description": "Settings related to colors.",
					"type": "object",
					"properties": {
						"background": {
							"description": "Allow users to set background colors.",
							"type": "boolean",
							"default": true
						},
						"custom": {
							"description": "Allow users to select custom colors.",
							"type": "boolean",
							"default": true
						},
						"customDuotone": {
							"description": "Allow users to create custom duotone filters.",
							"type": "boolean",
							"default": true
						},
						"customGradient": {
							"description": "Allow users to create custom gradients.",
							"type": "boolean",
							"default": true
						},
						"defaultDuotone": {
							"description": "Allow users to choose filters from the default duotone filter presets.",
							"type": "boolean",
							"default": true
						},
						"defaultGradients": {
							"description": "Allow users to choose colors from the default gradients.",
							"type": "boolean",
							"default": true
						},
						"defaultPalette": {
							"description": "Allow users to choose colors from the default palette.",
							"type": "boolean",
							"default": true
						},
						"duotone": {
							"description": "Duotone presets for the duotone picker.\nDoesn't generate classes or properties.",
							"type": "array",
							"items": {
								"type": "object",
								"properties": {
									"name": {
										"description": "Name of the duotone preset, translatable.",
										"type": "string"
									},
									"slug": {
										"description": "Kebab-case unique identifier for the duotone preset.",
										"type": "string"
									},
									"colors": {
										"description": "List of colors from dark to light.",
										"type": "array",
										"items": {
											"description": "CSS hex or rgb string.",
											"type": "string"
										}
									}
								},
								"required": [ "name", "slug", "colors" ],
								"additionalProperties": false
							}
						},
						"gradients": {
							"description": "Gradient presets for the gradient picker.\nGenerates a single class (`.has-{slug}-background`) and custom property (`--wp--preset--gradient--{slug}`) per preset value.",
							"type": "array",
							"items": {
								"type": "object",
								"properties": {
									"name": {
										"description": "Name of the gradient preset, translatable.",
										"type": "string"
									},
									"slug": {
										"description": "Kebab-case unique identifier for the gradient preset.",
										"type": "string"
									},
									"gradient": {
										"description": "CSS gradient string.",
										"type": "string"
									}
								},
								"required": [ "name", "slug", "gradient" ],
								"additionalProperties": false
							}
						},
						"link": {
							"description": "Allow users to set link colors.",
							"type": "boolean",
							"default": false
						},
						"palette": {
							"description": "Color palette presets for the color picker.\nGenerates three classes (`.has-{slug}-color`, `.has-{slug}-background-color`, and `.has-{slug}-border-color`) and a single custom property (`--wp--preset--color--{slug}`) per preset value.",
							"type": "array",
							"items": {
								"type": "object",
								"properties": {
									"name": {
										"description": "Name of the color preset, translatable.",
										"type": "string"
									},
									"slug": {
										"description": "Kebab-case unique identifier for the color preset.",
										"type": "string"
									},
									"color": {
										"description": "CSS hex or rgb(a) string.",
										"type": "string"
									}
								},
								"required": [ "name", "slug", "color" ],
								"additionalProperties": false
							}
						},
						"text": {
							"description": "Allow users to set text colors.",
							"type": "boolean",
							"default": true
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesDimensions": {
			"type": "object",
			"properties": {
				"dimensions": {
					"description": "Settings related to dimensions.",
					"type": "object",
					"properties": {
						"minHeight": {
							"description": "Allow users to set custom minimum height.",
							"type": "boolean",
							"default": false
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesLayout": {
			"type": "object",
			"properties": {
				"layout": {
					"description": "Settings related to layout.",
					"type": "object",
					"properties": {
						"contentSize": {
							"description": "Sets the max-width of the content.",
							"type": "string"
						},
						"wideSize": {
							"description": "Sets the max-width of wide (`.alignwide`) content. Also used as the maximum viewport when calculating fluid font sizes",
							"type": "string"
						},
						"allowEditing": {
							"description": "Disable the layout UI controls.",
							"type": "boolean",
							"default": true
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesPosition": {
			"type": "object",
			"properties": {
				"position": {
					"description": "Settings related to position.",
					"type": "object",
					"properties": {
						"sticky": {
							"description": "Allow users to set sticky position.",
							"type": "boolean",
							"default": false
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesSpacing": {
			"type": "object",
			"properties": {
				"spacing": {
					"description": "Settings related to spacing.",
					"type": "object",
					"properties": {
						"blockGap": {
							"description": "Enables `--wp--style--block-gap` to be generated from styles.spacing.blockGap.\nA value of `null` instead of `false` further disables layout styles from being generated.",
							"oneOf": [
								{ "type": "boolean" },
								{ "type": "null" }
							],
							"default": null
						},
						"margin": {
							"description": "Allow users to set a custom margin.",
							"type": "boolean",
							"default": false
						},
						"padding": {
							"description": "Allow users to set a custom padding.",
							"type": "boolean",
							"default": false
						},
						"units": {
							"description": "List of units the user can use for spacing values.",
							"type": "array",
							"items": {
								"type": "string"
							},
							"default": [ "px", "em", "rem", "vh", "vw", "%" ]
						},
						"customSpacingSize": {
							"description": "Allow users to set custom space sizes.",
							"type": "boolean",
							"default": true
						},
						"spacingSizes": {
							"description": "Space size presets for the space size selector.\nGenerates a custom property (`--wp--preset--spacing--{slug}`) per preset value.",
							"type": "array",
							"items": {
								"type": "object",
								"properties": {
									"name": {
										"description": "Name of the space size preset, translatable.",
										"type": "string"
									},
									"slug": {
										"description": "Unique identifier for the space size preset. For best cross theme compatibility these should be in the form '10','20','30','40','50','60', etc. with '50' representing the 'Medium' size step.",
										"type": "string"
									},
									"size": {
										"description": "CSS space-size value, including units.",
										"type": "string"
									}
								},
								"additionalProperties": false
							}
						},
						"spacingScale": {
							"description": "Settings to auto-generate space size presets for the space size selector.\nGenerates a custom property (--wp--preset--spacing--{slug}`) per preset value.",
							"type": "object",
							"properties": {
								"operator": {
									"description": "With + or * depending on whether scale is generated by increment or multiplier.",
									"type": "string",
									"enum": [ "+", "*" ],
									"default": "*"
								},
								"increment": {
									"description": "The amount to increment each step by.",
									"type": "number",
									"default": 1.5
								},
								"steps": {
									"description": "Number of steps to generate in scale.",
									"type": "integer",
									"default": 7
								},
								"mediumStep": {
									"description": "The value to medium setting in the scale.",
									"type": "number",
									"default": 1.5
								},
								"unit": {
									"description": "Unit that the scale uses, eg. rem, em, px.",
									"type": "string",
									"enum": [
										"px",
										"em",
										"rem",
										"vh",
										"vw",
										"%"
									],
									"default": "rem"
								}
							},
							"additionalProperties": false
						}
					},
					"additionalProperties": false
				}
			}
		},
		"settingsPropertiesTypography": {
			"type": "object",
			"properties": {
				"typography": {
					"description": "Settings related to typography.",
					"type": "object",
					"properties": {
						"customFontSize": {
							"description": "Allow users to set custom font sizes.",
							"type": "boolean",
							"default": true
						},
						"fontStyle": {
							"description": "Allow users to set custom font styles.",
							"type": "boolean",
							"default": true
						},
						"fontWeight": {
							"description": "Allow users to set custom font weights.",
							"type": "boolean",
							"default": true
						},
						"fluid": {
							"description": "Enables fluid typography and allows users to set global fluid typography parameters.",
							"oneOf": [
								{
									"type": "object",
									"properties": {
										"minFontSize": {
											"description": "Allow users to set a global minimum font size boundary in px, rem or em. Custom font sizes below this value will not be clamped, and all calculated minimum font sizes will be, at a minimum, this value.",
											"type": "string"
										},
										"maxViewportWidth": {
											"description": "Allow users to set custom a max viewport width in px, rem or em, used to set the maximum size boundary of a fluid font size.",
