{
  "$comment": "Schema derived from https://raw.githubusercontent.com/dotnet/core/main/release-notes/releases-index.json and https://github.com/dotnet/deployment-tools/blob/main/src/Microsoft.Deployment.DotNet.Releases/src/Product.cs",
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": false,
  "definitions": {
    "dateYYYYMMDD": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
      "description": "A date in the format YYYY-MM-DD",
      "$comment": "If we targeted draft-07 we could use the 'date' format instead of this format pattern. We cannot use the 'date-time' format because our existing values don't validate against it."
    },
    "releaseVersion": {
      "type": "string",
      "description": "A SemVer-compatible version string",
      "pattern": "^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$"
    },
    "releaseType": {
      "type": "string",
      "enum": ["sts", "lts"],
      "description": "An enumeration describing the different releaes types of a product",
      "$comment": "If we targeted draft-06 we could use oneOf/const in combination to add descriptions to the enum values"
    },
    "supportPhase": {
      "type": "string",
      "enum": ["preview", "go-live", "active", "maintenance", "eol"],
      "description": "An enumeration describing the different support phases of a product",
      "$comment": "If we targeted draft-06 we could use oneOf/const in combination to add descriptions to the enum values"
    },
    "product": {
      "type": "object",
      "properties": {
        "channel-version": {
          "type": "string",
          "title": "ProductVersion",
          "description": "The version of the product, e.g '5.0' or '1.1'",
          "pattern": "^[0-9]+\\.[0-9]+$"
        },
        "eol-date": {
          "oneOf": [
            {
              "$ref": "#/definitions/dateYYYYMMDD"
            },
            {
              "type": "null"
            }
          ],
          "title": "EndOfLifeDate",
          "description": "The end-of-life (EOL) date for this Product when it is considered to be out of support. The value may be `null` if the EOL date is undetermined, e.g. when a product is still a prerelease."
        },
        "security": {
          "type": "boolean",
          "title": "LatestReleaseIncludesSecurityUpdate",
          "description": "`true` if the latest release of this product includes a security update, `false` otherwise."
        },
        "latest-release-date": {
          "$ref": "#/definitions/dateYYYYMMDD",
          "title": "LatestReleaseDate",
          "description": "The date of the latest release of this product."
        },
        "latest-release": {
          "$ref": "#/definitions/releaseVersion",
          "title": "LatestReleaseVersion",
          "description": "The version of the latest release"
        },
        "latest-runtime": {
          "$ref": "#/definitions/releaseVersion",
          "title": "LatestRuntimeVersion",
          "description": "The version of the runtime included in the latest release"
        },
        "latest-sdk": {
          "$ref": "#/definitions/releaseVersion",
          "title": "LatestSdkVersion",
          "description": "The version of the SDK included in the latest release.  This is usually the SDK with the highest feature band. A ProductRelease may include multiple SDKs across different feature bands, all of which carry the same runtime version."
        },
        "product": {
          "type": "string",
          "title": "ProductName",
          "description": "The name of the product."
        },
        "releases.json": {
          "description": "The URL pointing to the releases.json file that contains information about all the releases  associated with this Product.",
          "type": "string",
          "format": "uri",
          "$comment": "Since this is always an absolute uri, the 'uri' format is unambiguous"
        },
        "release-type": {
          "$ref": "#/definitions/releaseType",
          "description": "The type of Product release indicating whether the release is Standard Term Support (sts) or Long Term Support (lts)."
        },
        "support-phase": {
          "$ref": "#/definitions/supportPhase",
          "description": "The support phase of the Product."
        }
      },
      "required": [
        "channel-version",
        "security",
        "latest-release-date",
        "latest-release",
        "latest-runtime",
        "latest-sdk",
        "product",
        "releases.json",
        "release-type",
        "support-phase"
      ],
      "additionalProperties": false
    }
  },
  "description": "A collection of manifests for .NET products, which is updated with each preview and stable release of the .NET SDK and/or Runtime",
  "id": "https://json.schemastore.org/dotnet-releases-index.json",
  "properties": {
    "releases-index": {
      "type": "array",
      "description": "A collection of all released products",
      "items": {
        "$ref": "#/definitions/product"
      }
    }
  },
  "required": ["releases-index"],
  "title": "JSON schema for .NET product collection manifests",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "description": "BizTalk Server Application Inventory Schema",
  "id": "http://schema.management.azure.com/schemas/2017-04-01/BizTalkServerApplicationSchema.json#",
  "properties": {
    "BizTalkAssemblies": {
      "type": "array",
      "description": "Array of BizTalk Reference Assemblies to be deployed.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Filename of the BizTalk Referenced Assembly."
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.dll",
            "description": "Relative output filepath for the Referenced Assembly. \r\nExample: bins\\\\bts1.dll"
          }
        }
      }
    },
    "BindingsFiles": {
      "type": "array",
      "description": "Array of Binding Files used in Deployment.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Filename of the Bindings File."
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.xml",
            "description": "Relative output filepath for the Bindings File.\r\nExample: bindings\\\\binding1.xml"
          }
        }
      }
    },
    "Assemblies": {
      "type": "array",
      "description": "Array of Reference Assemblies to be deployed.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Filename of the Referenced Assembly."
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.dll",
            "description": "Relative output filepath for the Unmanaged Referenced Assembly. \r\nExample: bins\\\\bts1.dll"
          }
        }
      }
    },
    "PreProcessingScripts": {
      "type": "array",
      "description": "Pre-Processing Scripts used in Deployment.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Filename of the Pre Processing Script."
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.\\w+",
            "description": "Relative output filepath for the Pre Processing Script.\r\nExample: bins\\\\Script1.vbs"
          },
          "Arguments": {
            "type": "string",
            "pattern": "\\w+(,\\w+)*",
            "description": "Arguments for the Pre Processing Script .\r\nExample: arg1,arg2"
          }
        }
      }
    },
    "PostProcessingScripts": {
      "type": "array",
      "description": "Post-Processing Scripts used in Deployment.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Filename of the Post Processing Script."
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.\\w+",
            "description": "Relative output filepath for the Post Processing Script.\r\nExample: Script\\\\Script1.vbs"
          },
          "Arguments": {
            "type": "string",
            "pattern": "\\w+(,\\w+)*",
            "description": "Arguments for the Post Processing Script .\r\nExample: arg1,arg2"
          }
        }
      }
    },
    "Files": {
      "type": "array",
      "description": "File used in Deployment.",
      "items": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string",
            "description": "Name of the File"
          },
          "Path": {
            "type": "string",
            "pattern": "\\w+[\\\\](\\w+\\.)*\\w+\\.\\w+",
            "description": "Relative output filepath for the Files.\r\nExample: File\\\\File.txt"
          }
        }
      }
    },
    "DeploymentSequence": {
      "type": "array",
      "description": "Sequence of Binding Files, Reference Assemblies, Pre-Processing and Post-Processing Scripts used in Deployment.",
      "items": {
        "type": "string"
      }
    }
  },
  "required": ["BizTalkAssemblies", "BindingsFiles", "DeploymentSequence"],
  "title": "BizTalkServerApplicationInventorySchema",
  "type": "object"
}

{
  "title": "JSON schema for Renovate config files (https://renovatebot.com/)",
  "$schema": "http://json-schema.org/draft-04/schema#",
  "type": "object",
  "properties": {
    "addLabels": {
      "description": "Labels to add to Pull Request.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "additionalBranchPrefix": {
      "description": "Additional string value to be appended to `branchPrefix`.",
      "type": "string",
      "default": ""
    },
    "additionalReviewers": {
      "description": "Additional reviewers for Pull Requests (in contrast to `reviewers`, this option adds to the existing reviewer list, rather than replacing it).",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "allowCustomCrateRegistries": {
      "description": "Set this to `true` to allow custom crate registries.",
      "type": "boolean",
      "default": false
    },
    "allowPlugins": {
      "description": "Set this to `true` if repositories are allowed to run install plugins.",
      "type": "boolean",
      "default": false
    },
    "allowPostUpgradeCommandTemplating": {
      "description": "Set this to `false` to disable template compilation for post-upgrade commands.",
      "type": "boolean",
      "default": true
    },
    "allowScripts": {
      "description": "Set this to `true` if repositories are allowed to run install scripts.",
      "type": "boolean",
      "default": false
    },
    "allowedPostUpgradeCommands": {
      "description": "A list of regular expressions that decide which post-upgrade tasks are allowed.",
      "type": "array",
      "items": {
        "type": "string"
      },
      "default": []
    },
    "ansible": {
      "description": "Configuration object for the ansible manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)tasks/[^/]+\\.ya?ml$"
        ]
      },
      "$ref": "#"
    },
    "ansible-galaxy": {
      "description": "Configuration object for the ansible-galaxy manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)requirements\\.ya?ml$",
          "(^|/)galaxy\\.ya?ml$"
        ]
      },
      "$ref": "#"
    },
    "argocd": {
      "description": "Configuration object for the argocd manager",
      "type": "object",
      "default": {
        "fileMatch": []
      },
      "$ref": "#"
    },
    "asdf": {
      "description": "Configuration object for the asdf manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)\\.tool-versions$"
        ]
      },
      "$ref": "#"
    },
    "assignAutomerge": {
      "description": "Assign reviewers and assignees even if the PR is to be automerged.",
      "type": "boolean",
      "default": false
    },
    "assignees": {
      "description": "Assignees for Pull Request (either username or email address depending on the platform).",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "assigneesFromCodeOwners": {
      "description": "Determine assignees based on configured code owners and changes in PR.",
      "type": "boolean",
      "default": false
    },
    "assigneesSampleSize": {
      "description": "Take a random sample of given size from `assignees`.",
      "type": "integer",
      "default": null
    },
    "autoApprove": {
      "description": "Set to `true` to automatically approve PRs.",
      "type": "boolean",
      "default": false
    },
    "autoReplaceGlobalMatch": {
      "description": "Control whether replacement regular expressions are global matches or only the first match.",
      "type": "boolean",
      "default": true
    },
    "autodiscover": {
      "description": "Autodiscover all repositories.",
      "type": "boolean",
      "default": false
    },
    "autodiscoverFilter": {
      "description": "Filter the list of autodiscovered repositories.",
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "string"
        }
      ],
      "default": null
    },
    "autodiscoverTopics": {
      "description": "Filter the list of autodiscovered repositories by topics.",
      "type": "array",
      "items": {
        "type": "string"
      },
      "default": null
    },
    "automerge": {
      "description": "Whether to automerge branches/PRs automatically, without human intervention.",
      "type": "boolean",
      "default": false
    },
    "automergeComment": {
      "description": "PR comment to add to trigger automerge. Only used if `automergeType=pr-comment`.",
      "type": "string",
      "default": "automergeComment"
    },
    "automergeSchedule": {
      "description": "Limit automerge to these times of day or week.",
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "string"
        }
      ],
      "default": [
        "at any time"
      ]
    },
    "automergeStrategy": {
      "description": "The merge strategy to use when automerging PRs. Used only if `automergeType=pr`.",
      "type": "string",
      "enum": [
        "auto",
        "fast-forward",
        "merge-commit",
        "rebase",
        "squash"
      ],
      "default": "auto"
    },
    "automergeType": {
      "description": "How to automerge, if enabled.",
      "type": "string",
      "enum": [
        "branch",
        "pr",
        "pr-comment"
      ],
      "default": "pr"
    },
    "azure-pipelines": {
      "description": "Configuration object for the azure-pipelines manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "azure.*pipelines?.*\\.ya?ml$"
        ],
        "enabled": false
      },
      "$ref": "#"
