        "versioning": "ruby"
      },
      "$ref": "#"
    },
    "sbt": {
      "description": "Configuration object for the sbt manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "\\.sbt$",
          "project/[^/]*\\.scala$",
          "project/build\\.properties$"
        ],
        "versioning": "ivy"
      },
      "$ref": "#"
    },
    "schedule": {
      "description": "Limit branch creation to these times of day or week.",
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "string"
        }
