    "separateMajorMinor": {
      "description": "If set to `false`, Renovate will upgrade dependencies to their latest release only. Renovate will not separate major or minor branches.",
      "type": "boolean"
    },
    "separateMinorPatch": {
      "description": "If set to `true`, Renovate will separate `minor` and `patch` updates into separate branches.",
      "type": "boolean",
      "default": false
    },
    "separateMultipleMajor": {
      "description": "If set to `true`, PRs will be raised separately for each available `major` upgrade version.",
      "type": "boolean",
      "default": false
    },
    "setup-cfg": {
      "description": "Configuration object for the setup-cfg manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)setup\\.cfg$"
        ],
        "versioning": "pep440"
      },
      "$ref": "#"
    },
    "skipInstalls": {
      "description": "Skip installing modules/dependencies if lock file updating is possible without a full install.",
      "type": "boolean",
      "default": null
    },
    "stopUpdatingLabel": {
      "description": "Label to make Renovate stop updating a PR.",
      "type": "string",
      "default": "stop-updating"
    },
    "suppressNotifications": {
      "description": "Options to suppress various types of warnings and other notifications.",
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "artifactErrors",
          "branchAutomergeFailure",
          "configErrorIssue",
          "dependencyLookupWarnings",
          "deprecationWarningIssues",
          "lockFileErrors",
          "missingCredentialsError",
          "onboardingClose",
          "prEditedNotification",
          "prIgnoreNotification"
        ]
      },
      "default": [
        "deprecationWarningIssues"
      ]
    },
    "swift": {
      "description": "Configuration object for the swift manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)Package\\.swift"
        ],
        "versioning": "swift",
        "pinDigests": false
      },
      "$ref": "#"
    },
    "tekton": {
      "description": "Configuration object for the tekton manager",
      "type": "object",
      "default": {
        "fileMatch": []
      },
      "$ref": "#"
    },
    "terraform": {
      "description": "Configuration object for the terraform manager",
      "type": "object",
      "default": {
        "commitMessageTopic": "Terraform {{depName}}",
        "fileMatch": [
          "\\.tf$"
        ],
        "pinDigests": false
      },
      "$ref": "#"
    },
    "terraform-version": {
      "description": "Configuration object for the terraform-version manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)\\.terraform-version$"
        ],
        "versioning": "hashicorp",
        "extractVersion": "^v(?<version>.*)$"
      },
      "$ref": "#"
    },
    "terragrunt": {
      "description": "Configuration object for the terragrunt manager",
      "type": "object",
      "default": {
        "commitMessageTopic": "Terragrunt dependency {{depName}}",
        "fileMatch": [
          "(^|/)terragrunt\\.hcl$"
        ]
      },
      "$ref": "#"
    },
    "terragrunt-version": {
      "description": "Configuration object for the terragrunt-version manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)\\.terragrunt-version$"
        ],
        "versioning": "hashicorp",
        "extractVersion": "^v(?<version>.+)$"
      },
      "$ref": "#"
    },
    "tflint-plugin": {
      "description": "Configuration object for the tflint-plugin manager",
      "type": "object",
      "default": {
        "commitMessageTopic": "TFLint plugin {{depName}}",
        "fileMatch": [
          "\\.tflint\\.hcl$"
        ],
        "extractVersion": "^v(?<version>.*)$"
      },
      "$ref": "#"
    },
    "timezone": {
      "description": "[IANA Time Zone](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones)",
      "type": "string"
    },
    "token": {
      "description": "Repository Auth Token.",
      "type": "string"
    },
    "transitiveRemediation": {
      "description": "Enable remediation of transitive dependencies.",
      "type": "boolean",
      "default": false
    },
    "travis": {
      "description": "Configuration object for the travis manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "^\\.travis\\.ya?ml$"
        ],
        "major": {
          "enabled": false
        },
        "versioning": "node"
      },
      "$ref": "#"
    },
    "unicodeEmoji": {
      "description": "Enable or disable Unicode emoji.",
      "type": "boolean",
      "default": true
    },
    "updateInternalDeps": {
      "description": "Whether to update internal dep versions in a monorepo. Works on Lerna or Yarn Workspaces.",
      "type": "boolean",
      "default": false
    },
    "updateLockFiles": {
      "description": "Set to `false` to disable lock file updating.",
      "type": "boolean"
    },
    "updateNotScheduled": {
      "description": "Whether to update branches when not scheduled. Renovate will not create branches outside of the schedule.",
      "type": "boolean"
    },
    "updatePinnedDependencies": {
      "description": "Whether to update pinned (single version) dependencies or not.",
      "type": "boolean",
      "default": true
    },
    "useBaseBranchConfig": {
      "description": "Whether to read configuration from `baseBranches` instead of only the default branch.",
      "type": "string",
      "enum": [
        "merge",
        "none"
      ],
      "default": "none"
    },
    "userStrings": {
      "description": "User-facing strings for the Renovate comment when a PR is closed.",
      "type": "object",
      "default": {
        "ignoreTopic": "Renovate Ignore Notification",
        "ignoreMajor": "Because you closed this PR without merging, Renovate will ignore this update. You will not get PRs for *any* future {{{newMajor}}}.x releases. But if you manually upgrade to {{{newMajor}}}.x then Renovate will re-enable `minor` and `patch` updates automatically.",
        "ignoreDigest": "Because you closed this PR without merging, Renovate will ignore this update. You will not get PRs for the `{{{depName}}}` `{{{newDigestShort}}}` update again.",
        "ignoreOther": "Because you closed this PR without merging, Renovate will ignore this update ({{{newValue}}}). You will get a PR once a newer version is released. To ignore this dependency forever, add it to the `ignoreDeps` array of your Renovate config."
      }
    },
    "username": {
      "description": "Username for authentication.",
      "type": "string"
    },
    "velaci": {
      "description": "Configuration object for the velaci manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "(^|/)\\.vela\\.ya?ml$"
        ]
      },
      "$ref": "#"
    },
    "versioning": {
      "description": "Versioning to use for filtering and comparisons.",
      "type": "string",
      "oneOf": [
        {
          "enum": [
            "aws-machine-image",
            "azure-rest-api",
            "bazel-module",
            "cargo",
            "composer",
            "conan",
            "deb",
            "debian",
            "docker",
            "git",
            "go-mod-directive",
            "gradle",
            "hashicorp",
            "helm",
            "hermit",
            "hex",
            "ivy",
            "kubernetes-api",
            "loose",
            "maven",
            "nixpkgs",
            "node",
            "npm",
            "nuget",
            "pep440",
            "perl",
            "poetry",
            "python",
            "redhat",
            "regex",
            "rez",
            "ruby",
            "semver",
            "semver-coerced",
            "swift",
            "ubuntu"
          ]
        },
        {
          "type": "string",
          "pattern": "^regex:"
        }
      ]
    },
    "vulnerabilityAlerts": {
      "description": "Config to apply when a PR is needed due to a vulnerability in the existing package version.",
      "type": "object",
      "default": {
        "groupName": null,
        "schedule": [],
        "dependencyDashboardApproval": false,
        "minimumReleaseAge": null,
        "rangeStrategy": "update-lockfile",
        "commitMessageSuffix": "[SECURITY]",
        "branchTopic": "{{{datasource}}}-{{{depName}}}-vulnerability",
        "prCreation": "immediate"
      },
      "$ref": "#"
    },
    "woodpecker": {
      "description": "Configuration object for the woodpecker manager",
      "type": "object",
      "default": {
        "fileMatch": [
          "^\\.woodpecker(?:/[^/]+)?\\.ya?ml$"
        ]
      },
      "$ref": "#"
    },
    "writeDiscoveredRepos": {
      "description": "Writes discovered repositories to a JSON file and then exit.",
      "type": "string"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "allOf": [
    {
      "$ref": "#/definitions/job"
    }
  ],
  "definitions": {
    "possiblySecretString": {
      "anyOf": [
        {
          "type": "string",
          "description": "This value will be used directly (regular string)"
        },
        {
          "type": "number",
          "description": "This value will be treated as a string even though it is a number"
        },
        {
          "title": "secret string",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "secure": {
              "type": "string",
              "description": "This should have been encrypted by the same user account to which the project belongs"
            }
          }
        }
      ]
    },
    "commitFilter": {
      "title": "commit filter",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "message": {
          "type": "string",
          "format": "regex",
          "description": "Regex for matching commit message"
        },
        "author": {
          "description": "Commit author's username, name, email or regexp matching one of these.",
          "anyOf": [
            {
              "type": "string",
              "format": "regex"
            },
            {
              "type": "string"
            }
          ]
        },
        "files": {
          "type": "array",
          "description": "Only specific files (glob patterns)",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "command": {
      "title": "command",
      "oneOf": [
        {
          "type": "string",
          "description": "Run a batch command"
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "ps": {
              "type": "string",
              "description": "Run a PowerShell command"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "pwsh": {
              "type": "string",
              "description": "Run a PowerShell Core command"
            }
          }
        },
        {
          "type": "object",
          "description": "Run a batch command",
          "additionalProperties": false,
          "properties": {
            "cmd": {
              "type": "string"
            }
          }
        },
        {
          "type": "object",
          "description": "Run a Bash command",
          "additionalProperties": false,
          "properties": {
            "sh": {
              "type": "string"
            }
          }
        }
      ]
    },
    "envVarHash": {
      "title": "environment variable hash",
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/possiblySecretString"
      }
    },
    "platform": {
      "enum": ["x86", "x64", "ARM", "ARM64", "Win32", "Any CPU"]
    },
    "configuration": {
      "type": "string"
    },
    "imageName": {
      "enum": [
        "macOS",
        "macOS-Mojave",
        "macos-bigsur",
        "macos-monterey",
        "Previous macOS",
        "Previous macOS-Mojave",
        "Ubuntu",
        "Ubuntu1604",
        "Ubuntu1804",
        "Ubuntu2004",
        "Previous Ubuntu",
        "Previous Ubuntu1604",
        "Previous Ubuntu1804",
        "Previous Ubuntu2004",
        "Visual Studio 2013",
        "Visual Studio 2015",
        "Visual Studio 2017",
        "Visual Studio 2019",
        "Visual Studio 2022",
        "Visual Studio 2017 Preview",
        "Visual Studio 2019 Preview",
        "Previous Visual Studio 2013",
        "Previous Visual Studio 2015",
        "Previous Visual Studio 2017",
        "Previous Visual Studio 2019",
        "Previous Visual Studio 2022",
        "zhaw18",
        "WMF 5"
      ]
    },
    "image": {
      "description": "Build worker image (VM template) -DEV_VERSION",
