        },
        "clone_folder": {
          "type": "string",
          "description": "Clone directory"
        },
        "shallow_clone": {
          "type": "boolean",
          "description": "Fetch repository as zip archive",
          "default": false
        },
        "clone_depth": {
          "description": "Set git clone depth",
          "type": "integer"
        },
        "hosts": {
          "title": "host options",
          "type": "object",
          "description": "Setting up etc\\hosts file",
          "additionalProperties": {
            "type": "string",
            "anyOf": [
              {
                "format": "ipv4"
              },
              {
                "format": "ipv6"
              }
            ]
          }
        },
        "environment": {
          "description": "Environment variables",
