                "publish_azure": {
                  "type": "boolean",
                  "description": "Package Azure Cloud Service projects and push to artifacts"
                },
                "publish_aspnet_core": {
                  "type": "boolean",
                  "description": "Package ASP.NET Core projects"
                },
                "publish_core_console": {
                  "type": "boolean",
                  "description": "Package .NET Core console projects"
                },
                "publish_nuget": {
                  "type": "boolean",
