      "title": "Languages",
      "type": "array",
      "items": {
        "anyOf": [
          {
            "$ref": "#/definitions/supportedProgrammingLanguage"
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "title": "Name",
                "$ref": "#/definitions/supportedProgrammingLanguage"
              },
              "production": {
                "title": "Production",
                "$ref": "#/definitions/fileFilter"
              },
              "test": {
                "title": "Test",
                "$ref": "#/definitions/fileFilter"
              }
            }
          }
        ]
      }
    },
    "exclude": {
      "$ref": "#/definitions/excludeFileFilter"
    }
  },
  "title": "Better Code Hub",
  "type": "object"
}

{
  "title": "JSON schema for Outblocks project configuration files",
  "$schema": "http://json-schema.org/draft-04/schema",
  "$ref": "#/definitions/OutblocksProject",
  "definitions": {
    "OutblocksProject": {
      "title": "Outblocks",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "name": {
          "type": "string"
        },
        "dns": {
          "description": "Project-wide DNS setup.",
          "$ref": "#/definitions/DNS"
        },
        "state": {
          "description": "Project-wide state source.",
          "$ref": "#/definitions/State"
        },
        "secrets": {
          "description": "Project-wide secrets provider.",
          "$ref": "#/definitions/Secrets"
        },
        "dependencies": {
          "description": "Project-wide dependencies to provision.",
          "$ref": "#/definitions/Dependencies"
        },
        "monitoring": {
          "description": "Project monitoring setup.",
          "$ref": "#/definitions/Monitoring"
        },
        "plugins": {
          "description": "Project-wide plugins.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/Plugin"
          }
        },
        "defaults": {
          "description": "Project-wide default app settings.",
          "$ref": "#/definitions/Defaults"
        }
      }
    },
    "DNS": {
      "title": "DNS",
      "type": "array",
      "items": {
        "additionalProperties": false,
        "properties": {
          "domain": {
            "type": "string"
          },
          "domains": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "plugin": {
            "type": "string"
          },
          "ssl": {
            "description": "SSL configuration.",
            "$ref": "#/definitions/SSL"
          }
        },
        "oneOf": [
          {
            "required": [
              "domain"
            ]
          },
          {
            "required": [
              "domains"
            ]
          }
        ]
      }
    },
    "SSL": {
      "title": "SSL",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "cert_file": {
          "description": "Public key file path. Required to be in PEM format.",
          "type": "string"
        },
        "key_file": {
          "description": "Private key file path. Required to be in PEM format.",
          "type": "string"
        },
        "cert": {
          "description": "Public key value in PEM format.",
          "type": "string"
        },
        "key": {
          "description": "Private key value in PEM format.",
          "type": "string"
        }
      }
    },
    "State": {
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "type": {
          "description": "State type, plugin specific value e.g. 'gcp' for gcp plugin or use 'local' for local state.",
          "type": "string"
        },
        "path": {
          "description": "Path of local state, used only when state type is 'local'.",
          "type": "string"
        }
      },
      "required": [
        "type"
      ],
      "title": "State"
    },
    "Secrets": {
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "type": {
          "description": "Secrets provider type, plugin specific value e.g. 'gcp' for gcp plugin.",
          "type": "string"
        }
      },
      "title": "Secrets"
    },
    "Dependencies": {
      "title": "Dependencies",
      "type": "object",
      "additionalProperties": false,
      "patternProperties": {
        "^[_a-zA-Z][a-zA-Z0-9_-]*$": {
          "type": "object",
          "properties": {
            "type": {
              "description": "The type of the dependency.",
              "type": "string"
            },
            "deploy": {
              "description": "Deploy config.",
              "$ref": "#/definitions/DependencyDeploy"
            },
            "run": {
              "description": "Run config.",
              "$ref": "#/definitions/DependencyRun"
            }
          },
          "required": [
            "type"
          ],
          "allOf": [
            {
              "if": {
                "properties": {
                  "type": {
                    "const": "storage"
                  }
                }
              },
              "then": {
                "properties": {
                  "versioning": {
                    "description": "Enables versioning for objects.",
                    "type": "boolean"
                  },
                  "location": {
                    "description": "Specify location for storage, refer to cloud provider docs for possible options.",
                    "type": "string"
                  },
                  "public": {
                    "description": "Makes whole storage public so that all objects can be accessed.",
                    "type": "boolean"
                  },
                  "max_versions": {
                    "description": "Maximum amount of versions to keep.",
                    "type": "integer"
                  },
                  "delete_in_days": {
                    "description": "Delete new objects after X days.",
                    "type": "integer"
                  },
                  "expire_versions_in_days": {
                    "description": "Expire archived versions after X days.",
                    "type": "integer"
                  },
                  "cors": {
                    "description": "CORS settings.",
                    "type": "array",
                    "items": {
                      "$ref": "#/definitions/DependencyStorageCORS"
                    }
                  }
                }
              }
            },
            {
              "if": {
                "anyOf": [
                  {
                    "properties": {
                      "type": {
                        "const": "mysql"
                      }
                    }
                  },
                  {
                    "properties": {
                      "type": {
                        "const": "postgresql"
                      }
                    }
                  }
                ]
              },
              "then": {
                "properties": {
                  "version": {
                    "description": "Specify version of database, refer to cloud provider docs for possible options.",
                    "type": "string"
                  },
                  "high_availability": {
                    "description": "Makes database highly available meaning it will have a read replica available in case of master failure.",
                    "type": "boolean"
                  },
                  "tier": {
                    "description": "Specify tier of database, refer to cloud provider docs for possible options.",
                    "type": "string"
                  },
                  "flags": {
                    "description": "Database flags, refer to cloud provider docs for possible options.",
                    "type": "object",
                    "additionalProperties": {
                      "type": "string"
                    }
                  },
                  "users": {
                    "description": "Database users.",
                    "type": "object",
                    "additionalProperties": {
                      "$ref": "#/definitions/DependencyDatabaseUser"
                    }
                  }
                }
              }
            }
          ]
        }
      }
    },
    "DependencyDatabaseUser": {
      "title": "Database user",
      "type": "object",
      "properties": {
        "password": {
          "description": "Explicitly set password, defaults to a randomly generated string.",
          "type": "string"
        },
        "hostname": {
          "description": "Hostname that user is allowed to connect from. Not all databases may support it.",
          "type": "string"
        }
      }
    },
    "DependencyStorageCORS": {
      "title": "Storage CORS",
      "type": "object",
      "properties": {
        "origins": {
          "description": "The list of Origins eligible to receive CORS response headers. Note: \"*\" is permitted in the list of origins, and means \"any Origin\".",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "methods": {
          "description": "The list of HTTP methods on which to include CORS response headers, (GET, OPTIONS, POST, etc) Note: \"*\" is permitted in the list of methods, and means \"any method\".",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "response_headers": {
          "description": "The list of HTTP headers other than the simple response headers to give permission for the user-agent to share across domains.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "max_age_in_seconds": {
          "description": "The value in seconds to return in the Access-Control-Max-Age header used in preflight responses.",
          "type": "integer"
        }
      }
    },
    "DependencyRun": {
      "title": "Run",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "type": "string"
        }
      }
    },
    "DependencyDeploy": {
      "title": "Deploy",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "type": "string"
        }
      }
    },
    "Monitoring": {
      "title": "Monitoring",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "plugin": {
          "description": "Monitoring plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "channels": {
          "description": "Monitoring notification channels.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/MonitoringChannel"
          }
        },
        "targets": {
          "description": "Monitoring targets.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/MonitoringTarget"
          }
        }
      }
    },
    "MonitoringChannel": {
      "title": "Monitoring channels",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "type": {
          "description": "Notification channel type. Possible values: slack, email.",
          "type": "string",
          "enum": [
            "slack",
            "email"
          ]
        }
      },
      "required": [
        "type"
      ],
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "slack"
              }
            }
          },
          "then": {
            "properties": {
              "token": {
                "description": "Bot user oauth token used for slack notification.",
                "type": "string"
              },
              "channel": {
                "description": "Channel used for slack notification.",
                "type": "string"
              }
            },
            "required": [
              "type",
              "token",
              "channel"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "email"
              }
            }
          },
          "then": {
            "properties": {
              "email": {
                "description": "Email used for email channel type.",
                "type": "string"
              }
            },
            "required": [
              "type",
              "email"
            ]
          }
        }
      ]
    },
    "MonitoringTarget": {
      "title": "Monitoring target",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "url": {
          "description": "Target full url.",
          "type": "string"
        },
        "frequency": {
          "description": "Check frequency in minutes. Defaults to 5 minutes.",
          "type": "integer",
          "enum": [
            1,
            5,
            10,
            15
          ]
        },
        "locations": {
          "description": "Check locations to use. Defaults to 'all'.",
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "required": [
        "url"
      ]
    },
    "Plugin": {
      "title": "Plugin",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "name": {
          "type": "string"
        }
      },
      "required": [
        "name"
      ]
    },
    "Defaults": {
      "title": "Defaults",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "deploy": {
          "description": "Deploy config.",
          "$ref": "#/definitions/DefaultDeploy"
        },
        "dns": {
          "description": "DNS config.",
          "$ref": "#/definitions/DefaultDNS"
        },
        "run": {
          "description": "Run config.",
          "$ref": "#/definitions/DefaultRun"
        }
      }
    },
    "DefaultDeploy": {
      "title": "Deploy defaults",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Deploy plugin override. Defaults to first supported plugin available.",
          "type": "string"
        }
      },
      "env": {
        "description": "Additional environment variables added to every app that supports environment variables.",
        "type": "object",
        "additionalProperties": {
          "type": "string"
        }
      }
    },
    "DefaultDNS": {
      "title": "DNS defaults",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "DNS plugin override. Defaults to first supported plugin available.",
          "type": "string"
        }
      }
    },
    "DefaultRun": {
      "title": "Run defaults",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Run plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "env": {
          "description": "Additional environment variables added to every app that supports environment variables.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "id": "https://json.schemastore.org/nightwatch.json",
  "properties": {
    "custom_commands_path": {
      "type": ["null", "string", "array"],
      "description": "Location(s) where custom commands will be loaded from.",
      "items": {
        "type": "string"
      },
      "default": null
    },
    "custom_assertions_path": {
      "type": ["null", "string", "array"],
      "description": "Location(s) where custom assertions will be loaded from.",
      "items": {
        "type": "string"
      },
      "default": null
    },
    "page_objects_path": {
      "type": ["null", "string", "array"],
      "description": "Location(s) where page object files will be loaded from.",
      "default": null
    },
    "globals_path": {
      "type": ["null", "string"],
      "description": "Location of an external globals module which will be loaded and made available to the test as a property globals on the main client instance.",
      "default": null
    },
    "globals": {
      "type": "object",
      "description": "An object which will be made available on the main test api, throughout the test execution",
      "properties": {
        "abortOnAssertionFailure": {
          "type": "boolean",
          "description": "This controls whether to abort the test execution when an assertion failed and skip the rest. It's being used in waitFor commands and expect assertions",
          "default": true
        },
        "abortOnElementLocateError": {
          "type": "boolean",
          "description": "This controls whether to abort the test execution when an element cannot be located; an error is logged in all cases, but this also enables skipping the rest of the testcase; It's being used in element commands such as .click() or .getText()",
          "default": false
        },
        "waitForConditionPollInterval": {
          "type": "integer",
          "description": "This will overwrite the default polling interval (currently 500ms) for waitFor commands and expect assertions that use retry",
          "default": 500
        },
        "waitForConditionTimeout": {
          "type": "integer",
          "description": "Default timeout value in milliseconds for waitFor commands and implicit waitFor value for expect assertions",
          "default": 5000
        },
        "throwOnMultipleElementsReturned": {
          "type": "boolean",
          "description": "This will cause waitFor commands on elements to throw an error if multiple elements are found using the given locate strategy and selector",
          "default": false
        },
        "suppressWarningsOnMultipleElementsReturned": {
          "type": "boolean",
          "description": "By default a warning is printed if multiple elements are found using the given locate strategy and selector; set this to true to suppress those warnings",
          "default": false
        },
        "asyncHookTimeout": {
          "type": "integer",
          "description": "Controls the timeout value for async hooks. Expects the done() callback to be invoked within this time or an error is thrown",
          "default": 10000
        },
        "unitTestsTimeout": {
          "type": "integer",
          "description": "Controls the timeout value for when running async unit tests. Expects the done() callback to be invoked within this time or an error is thrown",
          "default": 2000
        },
        "customReporterCallbackTimeout": {
          "type": "integer",
          "description": "Controls the timeout value for when executing the global async reporter. Expects the done() callback to be invoked within this time or an error is thrown",
          "default": 20000
        },
        "retryAssertionTimeout": {
          "type": "integer",
          "description": "Automatically retrying failed assertions - You can tell Nightwatch to automatically retry failed assertions until a given timeout is reached, before the test runner gives up and fails the test.",
          "default": 5000
        },
        "reporter": {}
      }
    },
    "dotenv": {
      "type": "object",
      "description": "Configuration settings for the dotenv module - a zero-dependency module that loads environment variables from a .env file into process.env. More details on https://www.npmjs.com/package/dotenv"
    },
    "persist_globals": {
      "type": "boolean",
      "description": "Persist the same globals object between runs or have a (deep) copy of it per each test; this can be useful when persisting data between test suites is needed, such as a cookie or session information",
      "default": false
    },
    "output_folder": {
      "type": "string",
      "description": "The location where the JUnit XML report files will be saved. Set this to false if you want to disable XML reporting",
      "default": "tests_output"
    },
    "src_folders": {
      "type": ["null", "string", "array"],
      "description": "A string or array of folders (excluding subfolders) where the tests are located.",
      "items": {
        "type": "string"
      },
      "default": null
    },
    "live_output": {
      "type": "boolean",
      "description": "Used when running in parallel to determine if the output should be collected and displayed at the end.",
      "default": false
    },
    "disable_colors": {
      "type": "boolean",
      "description": "Used to disable colored output in the terminal.",
      "default": false
    },
    "parallel_process_delay": {
      "type": "integer",
      "description": "Used when running in parallel to specify the delay (in milliseconds) between starting the child processes",
      "default": 10
    },
    "selenium": {
      "type": "object",
      "description": "An object containing Selenium Server related configuration options",
      "properties": {
        "start_process": {
          "type": "boolean",
          "default": false
        },
        "cli_args": {
          "type": ["object", "array"]
        },
        "server_path": {
          "type": ["null", "string"],
          "default": null
        },
        "log_path": {
          "type": ["string", "boolean"],
          "default": ""
        },
        "port": {},
        "check_process_delay": {
          "type": "integer",
          "default": 500
        },
        "max_status_poll_tries": {
          "type": "integer",
          "default": 15
        },
        "status_poll_interval": {
          "type": "integer",
          "default": 200
        }
      }
    },
    "start_session": {
      "type": "boolean",
      "description": "Whether or not to automatically start the Selenium/WebDriver session. If running unit tests, this should be set tot false.",
      "default": true
    },
    "end_session_on_fail": {
      "type": "boolean",
      "description": "End the session automatically when the test is being terminated, usually after a failed assertion.",
      "default": true
    },
    "skip_testcases_on_fail": {
      "description": "Skip the remaining test cases from the current test suite, when one test case fails."
    },
    "test_workers": {
      "type": ["boolean", "object"],
      "description": "Whether or not to run individual test files in parallel.",
      "default": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        },
        "workers": {
          "type": ["string", "number"],
          "description": "Automatically compute the number of workers based on CPU cores with \"auto\" or manually specify the number of workers"
        },
        "node_options": {
          "type": ["string", "array"],
          "description": "Pass node arguments to individual workers (all of the process.execArgv using \"auto\" or selectively pass node arguments via [\"--inspect\"])",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "test_runner": {
      "type": "string",
      "description": "Specifies which test runner to use: default|mocha",
      "default": "default"
    },
    "webdriver": {
      "type": "object",
      "description": "Defines options used to connect to the WebDriver/Selenium server",
      "properties": {
        "start_process": {
          "type": "boolean",
          "default": false
        },
        "cli_args": {
          "type": ["object", "array"]
        },
        "server_path": {
          "type": ["null", "string"],
          "default": null
        },
        "log_path": {
          "type": "string"
        },
        "use_legacy_jsonwire": {},
        "check_process_delay": {
          "type": "integer",
          "description": "Time to wait (in ms) before starting to check the Webdriver server is up and running",
          "default": 100
        },
        "max_status_poll_tries": {
          "type": "integer",
          "description": "Maximum number of ping status check attempts before returning a timeout error",
          "default": 10
        },
        "status_poll_interval": {
          "type": "integer",
          "description": "Interval (in ms) to use between status ping checks when checking if the Webdriver server is up and running",
          "default": 200
        },
        "process_create_timeout": {
          "type": "integer",
          "description": "The entire time (in ms) to wait for the Node.js process to be created and running (default is 2 min), including spawning the child process and checking the status",
          "default": 120000
        },
        "host": {},
        "port": {},
        "ssl": {},
        "proxy": {},
        "timeout_options": {
          "type": "object",
          "properties": {
            "timeout": {},
            "retry_attempts": {}
          }
        },
        "default_path_prefix": {},
        "username": {},
        "access_key": {}
      }
    },
    "test_settings": {
      "type": "object"
    },
    "launch_url": {
      "type": "string",
      "description": "A url which can be used later in the tests as the main url to load.",
      "default": ""
    },
    "silent": {
      "type": "boolean",
      "description": "set to false if you want to show the extended http traffic command logs from the WebDriver server.",
      "default": true
    },
    "output": {
      "type": "boolean",
      "description": "Used to disable terminal output completely.",
      "default": true
    },
    "detailed_output": {
      "type": "boolean",
      "description": "Set this to false if you'd like to only see the test case name displayed and pass/fail status.",
      "default": true
    },
    "output_timestamp": {
      "type": "boolean",
      "description": "Set this to true if you'd like to see timestamps next to the logging output",
      "default": false
    },
    "disable_error_log": {
      "type": "boolean",
      "description": "Set this to true if you'd like to not display errors during the execution of the test (they are shown at the end always).",
      "default": false
    },
    "screenshots": {
      "type": "boolean",
      "description": "Take error and failure screenshots during test execution",
      "default": false
    },
    "log_screenshot_data": {
      "type": "boolean",
      "description": "Used to enable showing the Base64 image data in the (verbose) log when taking screenshots.",
      "default": false
    },
    "desiredCapabilities": {
      "type": "object",
      "properties": {
        "browserName": {
          "type": "string"
        }
      }
    },
    "exclude": {
      "type": ["null", "array"],
      "description": "An array of folders or file patterns to be skipped (relative to the main source folder).",
      "items": {
        "type": "string"
      },
      "default": null
    },
    "filter": {
      "type": ["null", "string"],
      "description": "Folder or file pattern to be used when loading the tests. Files that don't match this pattern will be ignored.",
      "default": null
    },
    "skipgroup": {
      "type": "string",
      "description": "Skip a group of tests (a subfolder); can be a list of comma-separated values (no space)",
      "default": ""
    },
    "sync_test_names": {
      "type": "boolean",
      "default": true
    },
    "skiptags": {
      "type": "string",
      "description": "Skip tests by tag name; can be a list of comma-separated values (no space)",
      "default": ""
    },
    "use_xpath": {
      "type": "boolean",
      "description": "Use xpath as the default locator strategy",
      "default": false
    },
    "parallel_mode": {
      "type": "boolean",
      "default": false
    },
    "report_prefix": {
      "type": "string",
      "default": ""
    },
    "unit_tests_mode": {
      "type": "boolean",
      "default": false
    },
    "default_reporter": {
      "type": "string",
      "default": "junit"
    }
  },
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/lefthook.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "Skip": {
      "description": "Skip all or specific commands and scripts",
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
    },
    "Only": {
      "description": "Force the command, script, or hook to execute only in certain conditions. This acts like the opposite of skip.",
      "oneOf": [
        {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "ref": {
                "type": "string"
              }
            }
          }
        },
        {
          "type": "string"
        }
      ]
    },
    "Tags": {
      "description": "Specify tags for commands and scripts, useful for excluding",
      "type": "string"
    },
    "Env": {
      "type": "object",
      "description": "Specify environment variables for the command or script.",
      "additionalProperties": {
        "type": "string"
      }
    },
    "FailText": {
      "description": "Text to show when the command or script fails.",
      "type": "string"
    },
    "StageFixed": {
      "description": "Only for the 'pre-commit' hooks, this automatically calls 'git add' after running the command or script.",
      "type": "boolean"
    },
    "Interactive": {
      "description": "Whether to use interactive mode and provide a STDIN for a command or script.",
      "type": "boolean"
    },
    "GitHook": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "skip": {
          "$ref": "#/definitions/Skip"
        },
        "only": {
          "$ref": "#/definitions/Only"
        },
        "files": {
          "description": "A custom git command for files to be referenced in {files} template.",
          "type": "string"
        },
        "parallel": {
          "description": "Whether run commands and scripts concurrently.",
          "type": "boolean",
          "default": false
        },
        "piped": {
          "description": "Whether run commands and scripts sequentially. Will stop execution if one of the commands/scripts fail.",
          "default": false,
          "type": "boolean"
        },
        "follow": {
          "description": "Follow the STDOUT of the running commands and scripts.",
          "type": "boolean",
          "default": false
        },
        "exclude_tags": {
          "type": "string",
          "description": "Tags or command names that you want to exclude."
        },
        "commands": {
          "description": "Commands to be executed for the hook.",
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/Command"
          }
        },
        "scripts": {
          "description": "Scripts to be executed for the hook.",
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/Script"
          }
        }
      }
    },
    "Command": {
      "type": "object",
      "additionalProperties": false,
      "required": ["run"],
      "properties": {
        "run": {
          "description": "The command that is executed for the hook",
          "type": "string"
        },
        "skip": {
          "$ref": "#/definitions/Skip"
        },
        "only": {
          "$ref": "#/definitions/Only"
        },
        "tags": {
          "$ref": "#/definitions/Tags"
        },
        "glob": {
          "description": "Set a glob to filter files for your command.",
          "type": "string"
        },
        "files": {
          "description": "Custom Git commit for files to be referenced in {files} template for the 'run' setting.",
          "type": "string"
        },
        "env": {
          "$ref": "#/definitions/Env"
        },
        "root": {
          "type": "string",
          "description": "Change the CWD for the command you execute."
        },
        "exclude": {
          "description": "Provide a regular expression to exclude some files from being passed to the 'run' command.",
          "type": "string"
        },
        "fail_text": {
          "$ref": "#/definitions/FailText"
        },
        "stage_fixed": {
          "$ref": "#/definitions/StageFixed"
        },
        "interactive": {
          "$ref": "#/definitions/Interactive"
        }
      }
    },
    "Script": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "runner": {
          "type": "string"
        },
        "skip": {
          "$ref": "#/definitions/Skip"
        },
        "only": {
          "$ref": "#/definitions/Only"
        },
        "tags": {
          "$ref": "#/definitions/Tags"
        },
        "env": {
          "$ref": "#/definitions/Env"
        },
        "fail_text": {
          "$ref": "#/definitions/FailText"
        },
        "stage_fixed": {
          "$ref": "#/definitions/StageFixed"
        },
        "interactive": {
          "$ref": "#/definitions/Interactive"
        }
      }
    }
  },
  "properties": {
    "colors": {
      "description": "Whether enable or disable colorful output of Lefthook.",
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "object",
          "additionalProperties": {
            "oneOf": [
              {
                "type": "number"
              },
              {
                "type": "string"
              }
            ]
          }
        }
      ]
    },
    "no_tty": {
      "description": "Whether hide spinner and other interactive things.",
      "type": "boolean"
    },
    "extends": {
      "description": "Specify files to extend config with.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "min_version": {
      "description": "Specify a minimum version for the lefthook binary.",
      "type": "string"
    },
    "skip_output": {
      "description": "Manage verbosity by skipping the printing of output of some steps.",
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": [
          "meta",
          "success",
          "failure",
          "summary",
          "execution",
          "execution_out",
          "execution_info",
          "skips"
        ]
      }
    },
    "source_dir": {
      "description": "Change a directory for script files. Directory for script files contains folders with git hook names which contain script files.",
      "type": "string",
      "default": ".lefthook/"
    },
    "source_dir_local": {
      "description": "Change a directory for local script files (not stored in VCS).",
      "type": "string",
      "default": ".lefthook-local/"
    },
    "rc": {
      "description": "Provide an rc file, which is actually a simple sh script",
      "type": "string"
    },
    "remote": {
      "description": "Remote configs enable sharing of lefthook configuration across many projects.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "git_url": {
          "description": "A URL to Git repository. It will be accessed with priveleges of the machine lefthook runs on.",
          "type": "string"
        },
        "ref": {
          "description": "An optional branch or tag name.",
          "type": "string"
        },
        "config": {
          "description": "An optional config path from remote's root.",
          "type": "string"
        }
      }
    },
    "pre-applypatch": {
      "$ref": "#/definitions/GitHook"
    },
    "applypatch-msg": {
      "$ref": "#/definitions/GitHook"
    },
    "post-applypatch": {
      "$ref": "#/definitions/GitHook"
    },
    "commit-msg": {
      "$ref": "#/definitions/GitHook"
    },
    "fsmonitor-watchman": {
      "$ref": "#/definitions/GitHook"
    },
    "p4-changelist": {
      "$ref": "#/definitions/GitHook"
    },
    "p4-post-changelist": {
      "$ref": "#/definitions/GitHook"
    },
    "p4-pre-submit": {
      "$ref": "#/definitions/GitHook"
    },
    "p4-prepare-changelist": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-commit": {
      "$ref": "#/definitions/GitHook"
    },
    "post-commit": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-receive": {
      "$ref": "#/definitions/GitHook"
    },
    "proc-receive": {
      "$ref": "#/definitions/GitHook"
    },
    "post-receive": {
      "$ref": "#/definitions/GitHook"
    },
    "post-merge": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-rebase": {
      "$ref": "#/definitions/GitHook"
    },
    "rebase": {
      "$ref": "#/definitions/GitHook"
    },
    "update": {
      "$ref": "#/definitions/GitHook"
    },
    "post-update": {
      "$ref": "#/definitions/GitHook"
    },
    "post-rewrite": {
      "$ref": "#/definitions/GitHook"
    },
    "post-checkout": {
      "$ref": "#/definitions/GitHook"
    },
    "post-index-change": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-auto-gc": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-merge-commit": {
      "$ref": "#/definitions/GitHook"
    },
    "pre-push": {
      "$ref": "#/definitions/GitHook"
    },
    "prepare-commit-msg": {
      "$ref": "#/definitions/GitHook"
    },
    "push-to-checkout": {
      "$ref": "#/definitions/GitHook"
    },
    "reference-transaction": {
      "$ref": "#/definitions/GitHook"
    },
    "sendemail-validate": {
      "$ref": "#/definitions/GitHook"
    }
  },
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": false,
  "definitions": {
    "apidoc": {
      "title": "API documentation",
      "type": "object",
      "properties": {
        "version": {
          "type": "string",
          "description": "Specifies the version of the API Builder specification that this file is written for. The latest version can be found by visiting /apicollective/apibuilder-spec."
        }
      },
      "required": ["version"],
      "additionalProperties": false
    },
    "info": {
      "title": "contact information",
      "type": "object",
      "properties": {
        "contact": {
          "description": "Specifies contact information for this service.",
          "$ref": "#/definitions/contact"
        },
        "license": {
          "description": "Specifies the license under which this service is released.",
          "$ref": "#/definitions/license"
        }
      },
      "additionalProperties": false
    },
    "contact": {
      "title": "contact information",
      "type": "object",
      "description": "Specifies contact information for this service",
      "properties": {
        "name": {
          "type": "string",
          "description": "Identifying name of the contact person/organization"
        },
        "url": {
          "type": "string",
          "description": "URL pointing to the contact information"
        },
        "email": {
          "type": "string",
          "description": "Email address of the contact person/organization"
        }
      },
      "additionalProperties": false
    },
    "license": {
      "title": "license",
      "type": "object",
      "description": "specifies the license under which this service is released",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the license - e.g. MIT"
        },
        "url": {
          "type": "string",
          "description": "URL of the license itself"
        }
      },
      "required": ["name"],
      "additionalProperties": false
    },
    "import": {
      "title": "import",
      "type": "object",
      "properties": {
        "uri": {
          "type": "string",
          "description": "The complete URI to the service specification that we are importing. Within API Builder, you can find the URL to the service specification by clicking on the \"service.json\" link for a service."
        }
      },
      "required": ["uri"],
      "additionalProperties": false
    },
    "header": {
      "title": "header",
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "The name of the header."
        },
        "type": {
          "type": "string",
          "description": "The type of this header. Acceptable values are either the name of an enum or string. To specify a collection (meaning multiple values for this header can be provided), the type name can be wrapped with \"[]\". For example, to specify that the type is a collection of strings, use \"[string]\"."
        },
        "required": {
          "type": "boolean",
          "default": true,
          "description": "boolean: true|false. By default, all headers are considered required. To make a parameter optional, set \"required\" to false."
        },
        "default": {
          "description": "The default value for this header. If specified, generated clients will automatically include this header in all requests. Default values must be specified as strings."
        },
        "description": {
          "type": "string",
          "description": "Optional description for what this header provides. Supports GFM."
        },
        "attributes": {
          "type": "array",
          "description": "JSON Array defining additional meta data about this header for use by generators.",
          "items": {
            "$ref": "#/definitions/attribute"
          }
        },
        "deprecation": {
          "$ref": "#/definitions/deprecation"
        }
      },
      "required": ["name", "type"],
      "additionalProperties": false
    },
    "annotation": {
      "title": "annotation",
      "type": "object",
      "patternProperties": {
        "^[a-zA-Z0-9_]*$": {
          "title": "annotation",
          "type": "object",
          "description": "An annotation is just a short key that can be used to tag any field in any model of this API.",
          "properties": {
            "description": {
              "type": "string",
              "description": "Describes what the annotation is used for."
            },
            "deprecation": {
              "$ref": "#/definitions/deprecation"
            }
          },
          "additionalProperties": false
        }
      }
    },
    "attribute": {
      "title": "attribute",
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "the name and identifier of the attribute."
        },
        "value": {
          "title": "json object",
          "type": "object",
          "description": "a JSON object that is usually utilized by a downstream Generator."
        },
        "description": {
          "type": "string"
        }
      },
      "required": ["name", "value"],
      "additionalProperties": false
    },
    "deprecation": {
      "title": "json object",
      "type": "object",
      "description": "JSON Object that indicates that this object is deprecated.",
      "properties": {
        "description": {
          "type": "string",
          "description": "Optional, but recommended to contain notes for what the user is supposed to do now that this property is deprecated. Supports GFM."
        }
      },
      "additionalProperties": false
    },
    "enum": {
      "title": "enumeration",
      "type": "object",
      "patternProperties": {
        "^[a-zA-Z0-9_]*$": {
          "title": "name",
          "type": "object",
          "description": "The name of the enum. Names must be alphanumeric and must start with a letter. Valid characters are a-z, A-Z, 0-9 and _ characters. The name must be unique in the set of names assigned to enums, interfaces, models, or unions types.",
          "properties": {
            "plural": {
              "type": "string",
              "description": "Specifies the optional, plural form of the name. By default, we will pluralize the name using a basic set of english heuristics. The plural is used as a default in cases where it is more natural to specify web services. For example, the default path for a resource will be the plural."
            },
            "description": {
              "type": "string",
              "description": "Optional longer description for this enum."
            },
            "values": {
              "type": "array",
              "description": "JSON Array of EnumValue objects. Each element defines a valid value and an optional description.",
              "items": {
                "$ref": "#/definitions/enumvalues"
              }
            },
            "attributes": {
              "type": "array",
              "description": "JSON Array defining additional meta data about this enum for use by generators.",
              "items": {
                "$ref": "#/definitions/attribute"
              }
            },
            "deprecation": {
              "$ref": "#/definitions/deprecation"
            }
          },
          "required": ["values"],
          "additionalProperties": false
        }
      }
    },
    "enumvalues": {
      "title": "evaluates",
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "The name of the value. Names must start with a letter."
        },
        "value": {
          "type": "string",
          "description": "The actual string representation of this value when serializing. If not specified, defaults to 'name'."
        },
        "description": {
          "type": "string",
          "description": "Optional description for what this enum value provides. Supports GFM."
        },
        "attributes": {
          "type": "array",
          "description": "JSON Array defining additional meta data about this enum value for use by generators.",
          "items": {
            "$ref": "#/definitions/attribute"
          }
        },
        "deprecation": {
          "$ref": "#/definitions/deprecation"
        }
      },
      "required": ["name"],
      "additionalProperties": false
    },
    "interface": {
      "title": "interface",
      "type": "object",
      "patternProperties": {
        "^[a-zA-Z0-9_]*$": {
          "title": "name",
          "type": "object",
          "description": "Name specifies the name of the interface. Names must be alphanumeric and start with a letter. Valid characters are a-z, A-Z, 0-9 and _ characters. The name must be unique in the set of names assigned to enums, interfaces, or models. Note you may define an interface and a union of the same name.",
          "properties": {
            "plural": {
              "type": "string",
              "description": "Specifies the optional, plural form of the name. By default, we will pluralize the name using a basic set of english heuristics. The plural is used as a default in cases where it is more natural to specify web services. For example, the default path for a resource will be the plural."
            },
            "description": {
              "type": "string",
              "description": "Optional description for what this model provides. Supports GFM."
            },
            "fields": {
              "type": "array",
              "description": "JSON Array of 0 or more Fields.",
              "items": {
                "$ref": "#/definitions/field"
              }
            },
            "attributes": {
              "type": "array",
              "description": "JSON Array defining additional meta data about this model for use by generators.",
              "items": {
                "$ref": "#/definitions/attribute"
              }
            },
            "deprecation": {
              "$ref": "#/definitions/deprecation"
            }
          },
          "additionalProperties": false
        }
      }
    },
    "field": {
      "title": "field",
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Specifies the name of the field. Names must be alphanumeric and start with a letter. Valid characters are a-z, A-Z, 0-9 and _ characters.",
          "pattern": "^[a-zA-Z0-9_]*$"
        },
        "type": {
          "type": "string",
          "description": "Specifies the type of this field. Acceptable values include the name of either an enum, a model, or a (primitive type). To specify a List, the type name can be wrapped with \"[]\". For example, to specify that the type is a collection of strings, use \"[string]\". To specify a Map, the type name can be prefixed with \"map[type]\". For example, to specify that the type is a Map of string to long, use \"map[long]\". Note that for map, the keys must be strings (per the JSON specification)."
        },
        "description": {
          "type": "string",
          "description": "Optional description for what this field provides. Supports GFM."
        },
        "required": {
          "type": "boolean",
          "default": true,
          "description": "By default, all fields are considered required. To make a field optional, set \"required\" to false. When a field is marked as required, it must be present in any form of a model for that form to be valid. In client-server scenario, this means that any defaults that are present in the model must be applied by the client. If you want a default to be applied by the receiver, you should mark the field as \"required\": false"
        },
        "default": {
          "description": "Optional default value. The value must be valid for the type specified for this field. For example, if you specify a field named 'limit' with type 'integer', an acceptable default would be 10."
        },
        "example": {
          "type": "string",
          "description": "Optional - an example value for this field used only in the produced documentation"
        },
        "minimum": {
          "type": "integer",
          "description": "Optional - For a string, refers to the minimum length. For an array, the minimum number of elements in the array. For example, a value of 1 for an array would indicate the array must have at least 1 element."
        },
        "maximum": {
          "type": "integer",
          "description": "Optional - For a string, refers to the maximum length. For an array, the maximum number of elements in the array. For example, a value of 1 for an array would indicate the array must have at most 1 element."
        },
        "attributes": {
          "type": "array",
          "description": "JSON Array defining additional meta data about this field for use by generators.",
          "items": {
            "$ref": "#/definitions/attribute"
          }
        },
        "deprecation": {
          "$ref": "#/definitions/deprecation"
        },
        "annotations": {
          "type": "array",
          "description": "JSON Array of type string where each value indicates the name of a declared annotation (optional),",
          "items": {
            "type": "string"
          }
        }
      },
      "required": ["name", "type"],
      "additionalProperties": false
    },
    "model": {
      "title": "model",
      "type": "object",
      "description": "specifies the name of the model. Names must be alphanumeric and start with a letter. Valid characters are a-z, A-Z, 0-9 and _ characters. The name must be unique in the set of names assigned to enums, interfaces, models, or unions types.",
      "patternProperties": {
        "^[a-zA-Z0-9_]*$": {
          "title": "model",
          "type": "object",
          "properties": {
            "description": {
              "type": "string",
              "description": "Description for what this model provides."
            },
            "plural": {
              "type": "string",
              "description": "Specifies the optional, plural form of the name. By default, we will pluralize the name using a basic set of english heuristics. The plural is used as a default in cases where it is more natural to specify web services. For example, the default path for a resource will be the plural."
            },
            "interfaces": {
              "type": "array",
              "description": "JSON Array of type string where each value indicates the name of a declared interface",
              "items": {
                "type": "string"
              }
            },
            "fields": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/field"
              }
            },
            "attributes": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/attribute"
              }
            },
            "deprecation": {
              "$ref": "#/definitions/deprecation"
            }
          }
        }
      },
      "additionalProperties": false
    },
    "union": {
      "title": "union",
      "type": "object",
      "patternProperties": {
        "^[a-zA-Z0-9_]*$": {
          "type": "object",
          "description": "Name specifies the name of the interface. Names must be alphanumeric and start with a letter. Valid characters are a-z, A-Z, 0-9 and _ characters. The name must be unique in the set of names assigned to enums, unions, or models. Note you may define an interface and a union of the same name, but in this case it is required to list that interface in the interfaces field.",
          "properties": {
            "plural": {
              "type": "string",
              "description": "Specifies the optional, plural form of the name. By default, we will pluralize the name using a basic set of english heuristics. The plural is used as a default in cases where it is more natural to specify web services. For example, the default path for a resource will be the plural."
            },
            "discriminator": {
              "type": "string",
              "description": "Specifies an optional, but recommended, name for a type discriminator field which can then be used in serialization / deserialization to identify the type of object. For example, if not specified, a code generator may serialize the union type into a JSON structure of { \"type\" => object }. If a discriminator is provided, the same code generator can flatten the JSON representation to, for example: { \"discriminator\" => \"xxx\", \"field1\" => \"yyy\" }. If provided, the name of the discriminator field must be unique across all of the fields across all of the types of this union."
            },
            "description": {
              "type": "string",
              "description": "Optional description for what this union provides. Supports GFM."
            },
            "interfaces": {
              "type": "array",
              "description": "JSON Array of type string where each value indicates the name of a declared interface",
              "items": {
                "type": "string"
              }
            },
            "types": {
              "type": "array",
              "description": "Specifies the individual types that are part of this union type.",
              "items": {
                "$ref": "#/definitions/uniontype"
              }
            },
            "attributes": {
