      "if": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/recipe"
          }
        }
      },
      "then": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/recipe"
          },
          "name": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "displayName": {
            "type": "string"
          },
          "tags": {
            "$ref": "#/$defs/tags"
          },
          "estimatedEffortPerOccurrence": {
            "type": "string",
            "format": "duration"
