          "causesAnotherCycle": {
            "type": "boolean",
            "default": false
          },
          "recipeList": {
            "$ref": "#/$defs/recipeList"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    },
    {
      "if": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/category"
          }
        }
      },
      "then": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/category"
          },
          "name": {
            "type": "string"
          },
          "packageName": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "tags": {
            "$ref": "#/$defs/tags"
          },
          "root": {
            "type": "boolean",
            "default": false
          },
          "priority": {
            "type": "integer",
            "default": 0
          }
        },
        "required": [
          "packageName"
        ],
        "additionalProperties": false
      }
    },
    {
      "if": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/style"
          }
        }
      },
      "then": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/style"
          },
          "name": {
            "type": "string"
          },
          "displayName": {
            "type": "string"
          },
          "description": {
            "type": "string"
          },
          "tags": {
            "$ref": "#/$defs/tags"
          },
          "styleConfigs": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/style"
            }
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    },
    {
      "if": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/example"
          }
        }
      },
      "then": {
        "properties": {
          "type": {
            "const": "specs.openrewrite.org/v1beta/example"
          },
