                            "description": "Vendored dependencies are scanned by the \"CLI-side license scan\" method, as described in https://github.com/fossas/fossa-cli/blob/master/docs/features/vendored-dependencies.md"
                        }
                    ]
                },
                "licenseScanPathFilters": {
                    "type": "object",
                    "description": "licenseScanPathFilters allows you to filter which files are scanned when doing a CLILicenseScan. This setting does not apply if you use the ArchiveUpload method of scanning vendoredDependencies.",
                    "properties": {
                        "only": {
                            "type": "array",
                            "description": "A list of globs that will be used to filter paths. If there are any entries in the `only` list, then only paths that match one or more of the globs in the `only` list will be scanned for licenses.",
                            "items": {
                                "type": "string"
                            }
                        },
                        "exclude": {
                            "type": "array",
                            "description": "A list of globs that will be used to filter paths. If there are any entries in the `exclude` list, then paths that match any of the `exclude` entries will not be scanned for licenses.",
                            "items": {
                                "type": "string"
                            }
                        }
                    }
                }
            }
        }
    },
    "type": "object",
    "properties": {
        "version": {
            "type": "integer",
            "const": 3,
            "description": "Specifies the version of configuration file. Versions 1 and 2 were used by CLI versions up until CLI 2.0.0 and are no longer supported.\n\nCLI 2.x and greater only supports version 3."
        },
        "server": {
            "type": "string",
            "minLength": 1,
            "description": "Sets the endpoint that the CLI will send requests to. This field should only be modified if your FOSSA account lives on a different server than app.fossa.com.\n\nThis is most commonly needed with on-premise instances of FOSSA."
        },
        "apiKey": {
            "type": "string",
            "minLength": 1,
            "description": "Sets the https://docs.fossa.com/docs/api-reference#api-tokens that is required for accessing the FOSSA API and uploading data (e.g. `fossa analyze`) or retrieving information (e.g. `fossa test`) about a project."
        },
        "project": {
            "$ref": "#/$defs/project"
        },
        "telemetry": {
            "$ref": "#/$defs/telemetry"
        },
        "vendoredDependencies": {
            "$ref": "#/$defs/vendoredDependencies"
        },
        "revision": {
            "type": "array",
            "items": {
                "$ref": "#/$defs/revision"
            }
        },
        "targets": {
            "type": "object",
            "description": "The targets filtering allows you to specify the exact targets which be should be scanned.",
            "properties": {
                "only": {
                    "type": "array",
                    "description": "The list of `only` targets that should be scanned.",
                    "items": {
                        "$ref": "#/$defs/targetFilter"
                    }
                },
                "exclude": {
                    "type": "array",
                    "description": "The list of `exclude` targets which should be excluded from scanning. The targets listed in the exclude section will override the targets listed in the only sections.\n\nThis feature is used most effectively to remove specific targets from a directory.",
                    "items": {
                        "$ref": "#/$defs/targetFilter"
                    }
                }
            }
        },
        "paths": {
            "type": "object",
            "description": "The paths filtering section allows you to specify which paths should be scanned and which should not. The paths should be listed as their location from the root of your project.",
            "properties": {
                "only": {
                    "type": "array",
                    "description": "The list of paths to only allow scanning within.",
                    "items": {
                        "type": "string"
                    }
                },
                "exclude": {
                    "type": "array",
                    "description": "The list of paths to exclude from scanning in your directory.",
                    "items": {
                        "type": "string"
                    }
                }
            }
        }
    },
    "required": [
        "version"
    ]
}

{
  "$id": "https://github.com/hyperjumptech/monika/main/monika-config-schema.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "urlFormat": {
      "type": "string",
      "pattern": "^https?://"
    },
    "incidentThreshold": {
      "type": "integer",
      "description": "Number of times an alert should return true before Monika sends incident notifications",
      "default": 5
    },
    "recoveryThreshold": {
      "type": "integer",
      "description": "Number of times an alert should return false before Monika sends recovery notifications",
      "default": 5
    },
    "interval": {
      "title": "Interval",
      "type": "integer",
      "description": "The number of seconds to repeat the probe",
      "default": 10
    },
    "postgres": {
      "title": "Postgres",
      "type": "array",
      "description": "Monitor postgres readiness",
      "items": {
        "type": "object",
        "anyOf": [
          {
            "required": ["uri"],
            "additionalProperties": false,
            "properties": {
              "uri": {
                "title": "URI connection",
                "type": "string",
                "description": "Postgres uri connection configuration",
                "examples": ["postgres://user:password@172.1.0.1:5432/mydb"]
              }
            }
          },
          {
            "required": ["host", "port", "database"],
            "additionalProperties": true,
            "properties": {
              "host": {
                "type": "string",
                "description": "Postgres host address to connect to",
                "default": "172.15.0.1"
              },
              "port": {
                "title": "Port",
                "type": "integer",
                "description": "Postgres port to connect to",
                "default": "5432"
              },
              "database": {
                "title": "Database",
                "type": "string",
                "description": "Name of the database",
                "default": ""
              },
              "username": {
                "title": "Username",
                "type": "string",
                "description": "Username with access to the database",
                "default": ""
              },
              "password": {
                "title": "Password",
                "type": "string",
                "description": "User's database password",
                "default": ""
              }
            }
          }
        ]
      }
    },
    "redis": {
      "title": "Redis",
      "type": "array",
      "description": "Monitor redis health ",
      "items": {
        "type": "object",
        "anyOf": [
          {
            "required": ["uri"],
            "additionalProperties": true,
            "properties": {
              "uri": {
                "title": "URI connection",
                "type": "string",
                "description": "redis uri connection configuration",
                "examples": ["redis://alice:mypassword@172.15.0.2:6379"]
              }
            }
          },
          {
            "required": ["host", "port"],
            "additionalProperties": true,
            "properties": {
              "host": {
                "title": "Redis host",
                "description": "The hostname or IP address of the redis server",
                "type": "string",
                "default": "172.15.0.1",
                "examples": ["localhost", "192.168.0.1"]
              },
              "port": {
                "title": "Port number",
                "description": "Port number used for the redis",
                "type": "integer",
                "default": "6379"
              },
              "password": {
                "title": "Password",
                "description": "Password used for the redis AUTH, if set.",
                "type": "string",
                "default": ""
              },
              "username": {
                "title": "Username",
                "description": "Username used for the redis AUTH, if set.",
                "type": "string",
                "default": ""
              }
            }
          }
        ]
      }
    },
    "mongo": {
      "title": "MongoDB",
      "type": "array",
      "description": "Monitor MongoDB health ",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "required": [],
        "properties": {
          "uri": {
            "title": "MongoDB URI",
            "description": "The hostname or IP address of the MongoDB server",
            "type": "string",
            "examples": ["mongodb://user:password@127.0.0.1:27017/database"],
            "default": "mongodb://127.0.0.1:27017"
          },
          "host": {
            "title": "MongoDB host",
            "description": "The hostname or IP address of the MongoDB server",
            "type": "string",
            "examples": ["localhost", "127.0.0.1"],
            "default": "0.0.0.0.0"
          },
          "port": {
            "title": "Port number",
            "description": "Port number used for the MongoDB",
            "type": "integer",
            "examples": ["27017"],
            "default": "27017"
          },
          "password": {
            "title": "Password",
            "description": "Password used for the MongoDB AUTH, if set.",
            "type": "string",
            "default": ""
          },
          "username": {
            "title": "Username",
            "description": "Username used for the MongoDB AUTH, if set.",
            "type": "string",
            "default": ""
          }
        }
      }
    },
    "mariadb": {
      "title": "MariaDB/Mysql",
      "type": "array",
      "description": "Monitor MariaDB/Mysql health ",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["host", "port", "username", "password", "database"],
        "properties": {
          "host": {
            "title": "Database host",
            "description": "The hostname or IP address of the database server",
            "type": "string",
            "examples": ["localhost", "127.0.0.1", "172.11.0.1"],
            "default": "0.0.0.0"
          },
          "port": {
            "title": "Port number",
            "description": "Port number used by your database server",
            "type": "integer",
            "default": "3306"
          },
          "username": {
            "title": "Username",
            "description": "User with access to the database",
            "type": "string",
            "default": ""
          },
          "password": {
            "title": "Password",
            "description": "User password for authentication",
            "type": "string",
            "default": ""
          },
          "database": {
            "title": "Database",
            "default": "Name of the database"
          }
        }
      }
    },
    "requests": {
      "title": "Requests",
      "type": "array",
      "description": "The http or ping request to probe for",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["url"],
        "properties": {
          "method": {
            "title": "HTTP Method",
            "type": "string",
            "description": "The http method",
            "enum": ["GET", "POST", "DELETE", "PUT", "PATCH"],
            "default": "GET"
          },
          "url": {
            "title": "Url",
            "type": "string",
            "description": "The remote URL address to probe",
            "default": "https://api.github.com/zen",
            "examples": ["https://github.com", "https://httpbin.org/status/200"]
          },
          "timeout": {
            "title": "Timeout",
            "type": "integer",
            "description": "Set the timeout for the request in milliseconds, default is 10 seconds",
            "default": 10000
          },
          "saveBody": {
            "title": "SaveBody",
            "type": "boolean",
            "description": "Should response body be saved in the database",
            "default": false
          },
          "alerts": {
            "$ref": "#/definitions/alerts"
          },
          "ping": {
            "title": "Ping",
            "type": "boolean",
            "description": "If defined and to true, the request is an ICMP ping"
          },
          "allowUnauthorized": {
            "title": "AllowUnauthorized",
            "type": "boolean",
            "description": "If defined and to true, the request will ignore SSL certificate validity"
          },
          "body": {
            "$ref": "#/definitions/body"
          },
          "headers": {
            "$ref": "#/definitions/headers"
          }
        }
      }
    },
    "socket": {
      "title": "Socket",
      "type": "object",
      "description": "Socket is a TCP type request",
      "additionalProperties": false,
      "required": ["host", "port", "data"],
      "properties": {
        "host": {
          "type": "string",
          "description": "Address to your host"
        },
        "port": {
          "title": "Port",
          "type": "integer",
          "description": "Host port to connect to"
        },
        "data": {
          "title": "Data",
          "type": "string",
          "description": "Data payload for the request"
        }
      }
    },
    "alerts": {
      "title": "Alerts",
      "type": "array",
      "description": "The condition which will trigger an alert and the subsequent notification",
      "items": {
        "type": "object",
        "anyOf": [
          {
            "required": ["assertion", "message"],
            "additionalProperties": false,
            "properties": {
              "assertion": {
                "title": "Assertion",
                "type": "string",
                "description": "An expression that will trigger an alert when its is logically true. See the assertions here: https://monika.hyperjump.tech/guides/alerts#alert-query",
                "default": "response.status != 200"
              },
              "message": {
                "title": "Message",
                "type": "string",
                "description": "Message that will be sent to the notification channel",
                "default": "Http Response status code is not 200!"
              }
            }
          },
          {
            "required": ["query", "message"],
            "additionalProperties": false,
            "properties": {
              "query": {
                "title": "Query",
                "type": "string",
                "description": "Note: Query is deprecated, please use assertion",
                "default": "response.status != 200"
              },
              "message": {
                "title": "Message",
                "type": "string",
                "description": "Message that will be sent to the notification channel",
                "default": "Http Response status code is not 200!"
              }
            }
          }
        ]
      }
    },
    "body": {
      "title": "Body",
      "description": "The data bytes transmitted in an HTTP transaction message immediately following the headers if there are any"
    },
    "headers": {
      "title": "Headers",
      "type": "object",
      "description": "A list of strings sent and received by both the client program and server on every HTTP request and response",
      "additionalProperties": true,
      "properties": {
        "Accept": {
          "type": "string",
          "description": "Media type(s) that is/are acceptable for the response"
        },
        "Accept-Charset": {
          "type": "string",
          "description": "Character sets that are acceptable"
        },
        "Accept-Encoding": {
          "type": "string",
          "description": "List of acceptable encodings"
        },
        "Authorization": {
          "type": "string",
          "description": "Authentication credentials for HTTP authentication"
        },
        "Cache-Control": {
          "type": "string",
          "description": "Used to specify directives that must be obeyed by all caching mechanisms along the request-response chain"
        },
        "Cookie": {
          "type": "string",
          "description": "An HTTP cookie previously sent by the server with Set-Cookie"
        },
        "Connection": {
          "type": "string",
          "description": "General header that allows the sender or client to specify options that are desired for that particular connection"
        },
        "Content-Type": {
          "type": "string",
          "description": "The Media type of the body of the request (used with POST and PUT requests"
        },
        "Keep-Alive": {
          "type": "string",
          "description": "General header used to inform how long a persistent connection should stay open"
        },
        "Origin": {
          "type": "string",
          "description": "Initiates a request for cross-origin resource sharing (asks server for Access-Control-* response fields)"
        },
        "Referer": {
          "type": "string",
          "description": "This is the address of the previous web page (referrer) from which a link to the currently requested page was followed"
        },
        "User-Agent": {
          "type": "string",
          "description": "The user agent string of the user agent"
        }
      }
    }
  },
  "description": "Monika monitoring configuration schema",
  "properties": {
    "probes": {
      "title": "Probes",
      "type": "array",
      "description": "Probe is a description of the target, methods, timing and payloads to begin monitoring/probing a target.",
