            "jh",
            "md2",
            "md4",
            "md5",
            "md6",
            "radioGatun",
            "ripeMD",
            "ripeMD128",
            "ripeMD160",
            "ripeMD320",
            "sdhash",
            "sha1",
            "sha224",
            "sha256",
            "sha384",
            "sha512",
            "sha3",
            "skein",
            "snefru",
            "spectralHash",
            "ssdeep",
            "swifft",
            "tiger",
            "tlsh",
            "whirlpool"
          ]
        }
      },
