          "format": "uri"
        },
        "properties": {
          "description": "Key/value pairs that provide additional information about the rule.",
          "type": "object",
          "additionalProperties": true,
          "properties": {
            "tags": {
              "description": "A set of distinct strings that provide additional information.",
              "type": "array",
              "uniqueItems": true,
              "default": [],
              "items": {
                "type": "string"
              }
            }
          }
        }
      },
      "required": ["id"]
