            },
            "i18nFormat": {
              "type": "string",
              "description": "Format of the localization file specified with --i18n-file.",
              "x-deprecated": "Deprecated since 9.0"
            },
            "i18nLocale": {
              "type": "string",
              "description": "Locale to use for i18n.",
              "x-deprecated": "Deprecated since 9.0"
            },
            "i18nMissingTranslation": {
              "$ref": "#/definitions/buildersOptions/missingTranslation"
            },
            "outputHashing": {
              "type": "string",
              "description": "Define the output filename cache-busting hashing mode.",
              "default": "none",
              "enum": [
                "none",
                "all",
                "media",
                "bundles"
              ]
            },
            "deleteOutputPath": {
              "type": "boolean",
              "description": "delete-output-path",
              "default": true
            },
            "preserveSymlinks": {
              "type": "boolean",
              "description": "Do not use the real path when resolving modules."
            },
            "extractLicenses": {
              "type": "boolean",
              "description": "Extract all licenses in a separate file, in the case of production builds only.",
              "default": true
            },
            "showCircularDependencies": {
              "type": "boolean",
              "description": "Show circular dependency warnings on builds.",
              "default": true
            },
            "namedChunks": {
              "type": "boolean",
              "description": "Use file name for lazy loaded chunks.",
              "default": true
            },
            "bundleDependencies": {
              "description": "Available on server platform only. Which external dependencies to bundle into the module. By default, all of node_modules will be bundled.",
              "default": true,
              "oneOf": [
                {
                  "type": "boolean"
                },
                {
                  "type": "string",
                  "enum": [
                    "none",
                    "all"
                  ]
                }
              ]
            },
            "externalDependencies": {
              "description": "Exclude the listed external dependencies from being bundled into the bundle. Instead, the created bundle relies on these dependencies to be available during runtime.",
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": []
            },
            "statsJson": {
              "type": "boolean",
              "description": "Generates a 'stats.json' file which can be analyzed using tools such as 'webpack-bundle-analyzer'.",
              "default": false
            },
            "forkTypeChecker": {
              "type": "boolean",
              "description": "Run the TypeScript type checker in a forked process.",
              "default": true
            },
            "lazyModules": {
              "description": "List of additional NgModule files that will be lazy loaded. Lazy router modules with be discovered automatically.",
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": []
            }
          },
          "additionalProperties": false,
          "definitions": {
            "fileReplacement": {
              "oneOf": [
                {
                  "type": "object",
                  "properties": {
                    "src": {
                      "type": "string"
                    },
                    "replaceWith": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "src",
                    "replaceWith"
                  ]
                },
                {
                  "type": "object",
                  "properties": {
                    "replace": {
                      "type": "string"
                    },
                    "with": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "replace",
                    "with"
                  ]
                }
              ]
            }
          }
        },
        "tslint": {
          "description": "TSlint target options for Architect.",
          "type": "object",
          "properties": {
            "tslintConfig": {
              "type": "string",
              "description": "The name of the TSLint configuration file."
            },
            "tsConfig": {
              "description": "The name of the TypeScript configuration file.",
              "oneOf": [
                { "type": "string" },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            },
            "fix": {
              "type": "boolean",
              "description": "Fixes linting errors (may overwrite linted files).",
              "default": false
            },
            "typeCheck": {
              "type": "boolean",
              "description": "Controls the type check for linting.",
              "default": false
            },
            "force": {
              "type": "boolean",
              "description": "Succeeds even if there was linting errors.",
              "default": false
            },
            "silent": {
              "type": "boolean",
              "description": "Show output text.",
              "default": false
            },
            "format": {
              "type": "string",
              "description": "Output format (prose, json, stylish, verbose, pmd, msbuild, checkstyle, vso, fileslist, codeFrame).",
              "default": "stylish",
              "anyOf": [
                {
                  "enum": [
                    "checkstyle",
                    "codeFrame",
                    "filesList",
                    "json",
                    "junit",
                    "msbuild",
                    "pmd",
                    "prose",
                    "stylish",
                    "tap",
                    "verbose",
                    "vso"
                  ]
                },
                { "minLength": 1 }
              ]
            },
            "exclude": {
              "type": "array",
              "description": "Files to exclude from linting.",
              "default": [],
              "items": {
                "type": "string"
              }
            },
            "files": {
              "type": "array",
              "description": "Files to include in linting.",
              "default": [],
              "items": {
                "type": "string"
              }
            }
          },
          "additionalProperties": false
        }
      }
    },
    "buildersOptions": {
      "missingTranslation": {
        "type": "string",
        "description": "How to handle missing translations for i18n.",
        "enum": ["warning", "error", "ignore"],
        "default": "warning"
      },
      "localize": {
        "oneOf": [
          {
            "type": "boolean",
            "description": "Translate all locales."
          },
          {
            "type": "array",
            "description": "List of locales ID's to translate.",
            "minItems": 1,
            "items": {
              "type": "string",
              "pattern": "^[a-zA-Z]{2,3}(-[a-zA-Z]{4})?(-([a-zA-Z]{2}|[0-9]{3}))?(-[a-zA-Z]{5,8})?(-x(-[a-zA-Z0-9]{1,8})+)?$"
            }
          }
        ]
      }
    }
  }
}

{
  "$id": "https://json.schemastore.org/sourcehut-build-0.65.0.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "description": "A recipe for Sourcehut CI service. For details, see https://man.sr.ht/builds.sr.ht/manifest.md.",
  "properties": {
    "image": {
      "description": "Which OS image to build in. A list of available build images can be found at https://man.sr.ht/builds.sr.ht/compatibility.md",
      "type": "string",
      "examples": ["archlinux", "alpine/latest"]
    },
    "arch": {
      "description": "Which architecture to build for. See https://man.sr.ht/builds.sr.ht/compatibility.md for a list of available architectures.",
      "type": "string",
      "examples": ["aarch64", "x86_64"]
    },
    "packages": {
      "description": "A list of packages to install on the image. For image-specific details, consult https://man.sr.ht/builds.sr.ht/compatibility.md",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "repositories": {
      "description": "A list of extra repositories to enable with the image's package manager. The specific format varies by base image, consult https://man.sr.ht/builds.sr.ht/compatibility.md for details.",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      }
    },
    "artifacts": {
      "description": "A list of files to extract from the completed build environment and make available for downloading from the jobs page. Artifacts are only uploaded for successful jobs and are pruned after 90 days. \nNote that the file names are interpreted literally: do not use ~ or any shell code. If a relative path is used (e.g. example/my-artifact.tar.gz), it will be interpreted relative to the build user's home directory.",
      "type": "array",
      "items": {
        "type": "string"
      },
      "examples": ["example/my-artifact.tar.gz"]
    },
    "shell": {
      "description": "Whether to keep the build VM alive after all of the tasks have finished, even if it doesn't fail, so you can SSH in. You can also SSH in before the tasks have finished and tail the output of the build in your terminal. Learn more at https://man.sr.ht/builds.sr.ht/build-ssh.md",
      "type": "boolean"
    },
    "sources": {
      "description": "A list of repositories to clone into the home directory of the build user in the build environment. Optionally, prefix the protocol with the source control management scheme, to specify a protocol other than git. To specify a non-default git revision, append #commit-object to the repository.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": [
          "https://git.sr.ht/~sircmpwn/scdoc",
          "https://git.sr.ht/~sircmpwn/scdoc#devel",
          "git@git.sr.ht:~sircmpwn/scdoc",
          "hg+https://hg.sr.ht/~sircmpwn/scdoc",
          "hg+ssh://hg.sr.ht/~sircmpwn/scdoc"
        ]
      }
    },
    "tasks": {
      "description": "A list of scripts to execute in the build environment. \nTask names must use only lowercase alphanumeric characters, underscores or dashes and must be <=128 characters in length. Tasks are executed in the order specified. \nEach task is run in a separate login session, so if you modify the groups of the build user they will be effective starting from the subsequent task.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": {
          "type": "string"
        },
        "propertyNames": {
          "pattern": "^[a-z0-9_-]{1,128}$"
        },
        "examples": [
          {
            "package": "cd $site\ntar -cvz . > ../site.tar.gz"
          }
        ]
      }
    },
    "triggers": {
      "description": "A list of triggers to execute post-build, which can be used to send emails or do other post-build tasks. \nLearn more at https://man.sr.ht/builds.sr.ht/triggers.md",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "action": {
            "description": "Trigger type",
            "type": "string",
            "enum": ["email", "webhook"]
          },
          "condition": {
            "description": "When to execute this trigger",
            "type": "string",
            "enum": ["always", "failure", "success"]
          }
        },
        "required": ["action", "condition"]
      }
    },
    "environment": {
      "description": "A list of key/value pairs for options to set in the build environment via ~/.buildenv",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      },
      "examples": [
        {
          "site": "your-username.srht.site"
        }
      ]
    },
    "secrets": {
      "description": "List of secret UUIDs to be added to the guest during the build. Learn more at https://man.sr.ht/builds.sr.ht/#secrets",
      "type": "array",
      "items": {
        "type": "string",
        "examples": ["46f739e5-4538-45dd-a79f-bf173b7a2ed9"]
      }
    },
    "oauth": {
      "description": "If present, and secrets are enabled for this build, an OAuth 2.0 bearer token is generated for this build with the given string as the list of grants. The acurl command may be used in the task scripts to perform authenticated GraphAL API requests (https://man.sr.ht/graphql.md).",
      "type": "string",
      "examples": ["pages.sr.ht/PAGES:RW"]
    }
  },
  "required": ["image", "tasks"],
  "title": "Sourcehut Build Manifest",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "IBM zCodeFormatSettings",
  "description": "JSON schema for zcodeformat.yaml or zcodeformat.json code formatter preferences files. Version 0.0.1 -- Licensed Materials - Property of IBM - (c) Copyright IBM Corporation 2022. All Rights Reserved.",
  "type": "object",
  "properties": {
    "additionalProperties": false,
    "cobol": {
      "$ref": "#/definitions/cobol"
    },
    "copybook": {
      "$ref": "#/definitions/copybook"
    }
  },
  "definitions": {
    "copybookCapitalizationOptions": { "enum": ["upper", "lower"] },
    "cobolCapitalizationOptions": { "enum": ["none", "upper", "lower", "mixed"] },
    "cobol": {
      "additionalProperties": false,
      "type": "object",
      "properties": {
        "dataDivision": {
          "additionalProperties": false,
          "type": "object",
          "properties": {
            "enableIndentation": {
              "type": "boolean",
              "description": "Enable indentation of record descriptions\nIf false, startOfAreaA and indentLength are not allowed",
              "default": true
            },
            "indentation": {
              "type": "object",
              "description": "Indentation objects based on enableIndentation",
              "$ref": "#/definitions/dataDivIndent"
            },
            "alignPictureClauses": {
              "type": "boolean",
              "description": "Align PICTURE Clauses",
              "default": true
            },
            "alignValueClauses": {
              "type": "boolean",
              "description": "Align VALUE Clauses",
              "default": true
            }
          },
          "anyOf": [
            {
              "properties": {
                "enableIndentation": { "const": false },
                "indentation": { "type": "object", "additionalProperties": false }
              }
            },
            {
              "properties": {
                "enableIndentation": { "const": true },
                "indentation": {
                  "$ref": "#/definitions/dataDivIndent"
                }
              }
            }
          ]
        },
        "procedureDivision": {
          "additionalProperties": false,
          "type": "object",
          "properties": {
            "enableIndentation": {
              "type": "boolean",
              "description": "Enable indentation of procedure divisions",
              "default": true
            },
            "indentation": {
              "type": "object",
              "description": "Indentation objects based on enableIndentation",
              "$ref": "#/definitions/procDivIndent"
            }
          },
          "anyOf": [
            {
              "properties": {
                "enableIndentation": { "const": false },
                "indentation": { "type": "object", "additionalProperties": false }
              }
            },
            {
              "properties": {
                "enableIndentation": { "const": true },
                "indentation": {
                  "$ref": "#/definitions/procDivIndent"
                }
              }
            }
          ]
        },
        "reservedWordCase": {
          "type": "string",
          "description": "Reserved words",
          "default": "upper",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "userDefinedWordCase": {
          "type": "string",
          "description": "User-defined words",
          "default": "upper",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "commentCase": {
          "type": "string",
          "description": "Comment",
          "default": "none",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "functionCase": {
          "type": "string",
          "description": "Function",
          "default": "upper",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "dateFormatCase": {
          "type": "string",
          "description": "Date format",
          "default": "upper",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "compilerDirectiveCase": {
          "type": "string",
          "description": "Compiler directive",
          "default": "upper",
          "$ref": "#/definitions/cobolCapitalizationOptions"
        },
        "endOfAreaB": {
          "type": "integer",
          "description": "End of Area B\n\nIf -1, will use Margin R as the end of Area B",
          "default": -1,
          "oneOf": [
            { "minimum": -1, "maximum": -1 },
            { "minimum": 50, "maximum": 100 }
          ]
        },
        "lineWrappingStyle": {
          "type": "string",
          "description": "If indentation moves code beyond Area B",
          "default": "wrapToNextLine",
          "enum": ["wrapToNextLine", "noIndent", "indentToAreaB", "indentPastAreaB"]
        }
      }
    },
    "copybook": {
      "additionalProperties": false,
      "type": "object",
      "properties": {
        "codeCase": {
          "type": "string",
          "description": "Format copybook code in uppercase",
          "default": "upper",
          "$ref": "#/definitions/copybookCapitalizationOptions"
        },
        "commentCase": {
          "type": "string",
          "description": "Format copybook comments in uppercase",
          "default": "upper",
          "$ref": "#/definitions/copybookCapitalizationOptions"
        }
      }
    },
    "dataDivIndent": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "startOfAreaA": {
          "type": "integer",
          "description": "Start of Area A\nCannot be used if enableIndentation is false",
          "default": 8,
          "minimum": 8,
          "maximum": 11
        },
        "indentLength": {
