      "enum": ["true"]
    },
    "resource": {
      "type": "object",
      "required": ["url", "style", "content"],
      "properties": {
        "url": {
          "description": "The URL to be referenced. For resources that require authentication, the URL must be HTTPS.",
          "type": "string",
          "format": "uri"
        },
        "style": {
          "description": "Specifies the kind of web resource being accessed. Permitted values are 'Simple' and 'Feed'.",
          "type": "string",
          "pattern": "^([sS]imple|[fF]eed)$",
          "default": "Simple"
        },
        "content": {
          "description": "This member specifies how to extract content from the web response.",
          "type": "object",
          "minProperties": 1,
          "additionalProperties": {
            "type": "string"
          }
        }
      }
    },
    "page": {
      "required": ["layout"],
      "properties": {
        "layout": {
          "description": "The name of the layout for the page. The layout name should refer to one of the predefined page layouts.",
          "enum": [
            "MSBand_ScrollingText",
            "MSBand_NoScrollingText",
            "MSBand_SingleMetric",
            "MSBand_SingleMetricWithIcon",
            "MSBand_MetricsWithIcons",
            "MSBand_SingleMetricWithSecondary"
          ]
        },
        "condition": {
          "$ref": "#/definitions/condition"
        },
        "iconBindings": {
          "description": "Similar to textBindings, but used to select one of the web tile icons in icons list for each icon in the page. If there are no icon elements on the page, this member may be omitted.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/definitions/iconBinding"
          }
        },
        "textBindings": {
          "description": "An array of objects corresponding to each page element that contains string content. Each binding object provides the numeric id of the page element based on the predefined layout selected, and the string value that it should contain.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/definitions/textBinding"
          }
        }
      }
    },
    "iconBinding": {
      "required": ["conditions", "elementId"],
      "type": "object",
      "properties": {
        "elementId": {
          "$ref": "#/definitions/elementId"
        },
        "conditions": {
          "description": "For this release, this must contain an array with a single 'condition' object whose 'condition' is true, and whose 'icon' member specifies the name of the icon to be used.",
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "condition": {
                "$ref": "#/definitions/condition"
              },
              "icon": {
                "description": "The name of the icon as specified in the 'icons' node.",
                "type": "string"
              }
            }
          }
        }
      }
    },
    "textBinding": {
      "required": ["elementId", "value"],
      "properties": {
        "elementId": {
          "$ref": "#/definitions/elementId"
        },
        "value": {
          "type": "string"
        }
      }
    },
    "notification": {
      "type": "object",
      "required": ["condition", "title"],
      "properties": {
        "condition": {
          "description": "The condition to be evaluated to determine whether to trigger the notification. The conditional expression has the syntax '<Operand1> <Operator> <Operand2>' or 'true'.",
          "type": "string"
        },
        "title": {
          "description": "The text to use for the notification title. If longer than 20 characters, it will be truncated.",
          "type": "string"
        },
        "body": {
          "description": "The text to use for the notification body. If longer than 20 characters, it will be truncated.",
          "type": "string"
        }
      }
    }
  },
  "id": "https://json.schemastore.org/band-manifest.json",
  "properties": {
    "manifestVersion": {
      "description": "Defines the contract between the web tile developer and the Microsoft Health app. It must be set to 1 for the current release.",
      "enum": [1]
    },
    "name": {
      "description": "Defines the name of the web tile.",
      "type": "string",
      "maxLength": 21
    },
    "description": {
      "description": "Provides description about the web tile.",
      "type": "string",
      "maxLength": 100
    },
    "version": {
      "description": "Indicates the version number of the web tile which will not be shown to users.",
      "type": "number"
    },
    "versionString": {
      "description": "Indicates the web tile version as shown to users. If not provided, it displays the version.",
      "type": "string",
      "maxLength": 10
    },
    "author": {
      "description": "Specifies the author of the web tile.",
      "type": "string",
      "maxLength": 50
    },
    "organization": {
      "description": "Specifies the organization associated with the web tile.",
      "type": "string",
      "maxLength": 100
    },
    "contactEmail": {
      "description": "Provides contact info of the web tile author. Used for administrative purposes and analytics by Microsoft Band team.",
      "type": "string",
      "format": "email",
      "maxLength": 100
    },
    "tileIcon": {
      "description": "Specifies the location of the large tile icon.",
      "type": "object",
      "required": ["46"],
      "properties": {
        "46": {
          "$ref": "#/definitions/icon"
        }
      }
    },
    "badgeIcon": {
      "description": "Specifies the location of the small tile icon. If not provided, the badging functionality is not enabled.",
      "type": "object",
      "required": ["24"],
      "properties": {
        "24": {
          "$ref": "#/definitions/icon"
        }
      }
    },
    "tileTheme": {
      "description": "Specifies the custom theme colors for the web tile.",
      "type": "object",
      "properties": {
        "base": {
          "$ref": "#/definitions/color"
        },
        "highlight": {
          "$ref": "#/definitions/color"
        },
        "lowlight": {
          "$ref": "#/definitions/color"
        },
        "secondary": {
          "$ref": "#/definitions/color"
        },
        "highcontrast": {
          "$ref": "#/definitions/color"
        },
        "muted": {
          "$ref": "#/definitions/color"
        }
      }
    },
    "refreshIntervalMinutes": {
      "description": "Specifies the desired data refresh interval, in minutes. Refresh intervals shorter than 15 will not be honored. If not provided, it defaults to 30.",
      "type": "integer",
      "default": 30,
      "minimum": 15
    },
    "resources": {
      "description": "Each web tile must refer to one or more web resources. Each resource object describes a web data from which content for the tile will be extracted.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/resource"
      }
    },
    "icons": {
      "description": "All PNG icons used by the tile within its pages must be provided here.",
      "type": "object",
      "maxProperties": 8,
      "additionalProperties": {
        "$ref": "#/definitions/icon"
      }
    },
    "pages": {
      "description": "Each tile consists of one or more pages, as described by the objects in this array. Each page object specifies the layout and content of the page.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/page"
      }
    },
    "notifications": {
      "description": "Creates notification that gets delivered when certain conditions are detected in the new web data.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/notification"
      }
    }
  },
  "required": ["manifestVersion", "name", "tileIcon", "resources", "pages"],
  "title": "JSON schema for Microsoft Band manifests",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/pgap_yaml_input_reader",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {},
  "description": "NCBI Prokaryotic Genome Annotation Pipeline (PGAP) input metadata (submol) JSON/YAML configuration file",
  "properties": {
    "$schema": {
      "$id": "/$schema",
      "type": "string",
      "title": "Schema",
      "description": "The value of this keyword MUST be a URI (containing a scheme) and this URI MUST be normalized. ",
      "default": "",
      "examples": ["https://json.schemastore.org/pgap_yaml_input_reader"]
    },
    "consortium": {
      "$id": "/properties/consortium",
      "type": "string",
      "title": "Consortium",
      "description": "Name of the project that generated the genome assembly",
      "default": "",
      "examples": ["SkyNet"]
    },
    "comment": {
      "$id": "/properties/comment",
      "type": "string",
      "title": "Free text comment about the genome assembly",
      "description": "Appears in the COMMENT section of each GenBank sequence record.",
      "default": "",
      "examples": [
        "This draft WGS assembly was generated by running SKESA to generate a de-novo assembly. The de-novo assembly was then concatenated with  configs generated using a guided assembler using antimicrobial resistance genes as baits to comprehensively catalog the set of resistance genes in the isolate. Note, some parts of the configs derived from the guided assembler may overlap de-novo configs, and other guided assembler configs. De-novo configs can be differentiated from guided assembler configs by their names, which include either 'denovo' or 'guided'."
      ]
    },
    "tp_assembly": {
      "$id": "/properties/tp_assembly",
      "type": "boolean",
      "title": "Reserved",
      "description": "NCBI internal flag used for testing.",
      "default": false,
      "examples": [false]
    },
    "sra": {
      "$id": "/properties/sra",
      "type": "array",
      "title": "SRA assembly data",
      "description": "Sequence reads used to build the assembly",
      "items": {
        "$id": "/properties/sra/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["accession"],
        "properties": {
          "accession": {
            "$id": "/properties/sra/items/properties/accession",
            "type": "string",
            "title": "SRA Accession",
            "description": "Sequence Read Archive (SRA) accession for the run (with SRR, ERR or DRR prefix)",
            "default": "",
            "examples": ["SRR8796989"]
          }
        }
      }
    },
    "authors": {
      "$id": "/properties/authors",
      "type": "array",
      "title": "Author(s) of the genome assembly",
      "description": "Optional, but include if intending to submit to GenBank. Authors can be different from the contact.",
      "items": {
        "$id": "/properties/authors/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["author"],
        "properties": {
          "author": {
            "$id": "/properties/authors/items/properties/author",
            "type": "object",
            "additionalProperties": false,
            "required": ["first_name", "last_name"],
            "properties": {
              "first_name": {
                "$id": "/properties/authors/items/properties/author/properties/first_name",
                "type": "string",
                "title": "First name",
                "default": "",
                "examples": ["Arnold"]
              },
              "last_name": {
                "$id": "/properties/authors/items/properties/author/properties/last_name",
                "type": "string",
                "title": "Last name",
                "default": "",
                "examples": ["Schwarzenegger"]
              },
              "middle_initial": {
                "$id": "/properties/authors/items/properties/author/properties/middle_initial",
                "type": "string",
                "title": "First letter of middle name",
                "default": "",
                "examples": ["T800"]
              }
            }
          }
        }
      }
    },
    "bioproject": {
      "$id": "/properties/bioproject",
      "type": "string",
      "title": "BioProject ID (PRJXX) for the project, if available",
      "default": "",
      "examples": ["PRJ9999999"]
    },
    "biosample": {
      "$id": "/properties/biosample",
      "type": "string",
      "title": "BioSample ID (SAMXXX) for the sequenced sample, if available",
      "default": "",
      "examples": ["SAMN99999999"]
    },
    "contact_info": {
      "$id": "/properties/contact_info",
      "type": "object",
      "title": "Submitter contact information",
      "description": "Optional, but include if intending to submit to GenBank. The main contact for this genome assembly.",
      "additionalProperties": false,
      "required": [
        "organization",
        "department",
        "city",
        "country",
        "street",
        "email",
        "first_name",
        "last_name",
        "postal_code"
      ],
      "properties": {
        "state": {
          "$id": "/properties/contact_info/properties/state",
          "type": "string",
          "title": "State or region",
          "default": "",
          "examples": ["MD", "Florida"]
        },
        "fax": {
          "$id": "/properties/contact_info/properties/fax",
          "type": "string",
          "title": "Fax number",
          "default": "",
          "examples": ["301-555-1234", "+7 095 555 1234"]
        },
        "city": {
          "$id": "/properties/contact_info/properties/city",
          "type": "string",
          "title": "City",
          "default": "",
          "examples": ["Docker"]
        },
        "country": {
          "$id": "/properties/contact_info/properties/country",
          "type": "string",
          "title": "Country",
          "default": "",
          "examples": ["Lappland"]
        },
        "department": {
          "$id": "/properties/contact_info/properties/department",
          "type": "string",
          "title": "Department or division submitting the genome assembly",
          "default": "",
          "examples": ["Department of Using NCBI"]
        },
        "email": {
          "$id": "/properties/contact_info/properties/email",
          "type": "string",
          "title": "Email address",
          "default": "",
          "examples": ["jane_doe@gmail.com"]
        },
        "first_name": {
          "$id": "/properties/contact_info/properties/first_name",
          "type": "string",
          "title": "First name",
          "default": "",
          "examples": ["Jane"]
        },
        "middle_initial": {
          "$id": "/properties/contact_info/properties/middle_initial",
          "type": "string",
          "title": "First letter of middle name",
          "default": "",
          "examples": ["N"]
        },
        "last_name": {
          "$id": "/properties/contact_info/properties/last_name",
          "type": "string",
          "title": "Last name",
          "default": "",
          "examples": ["Doe"]
        },
        "organization": {
          "$id": "/properties/contact_info/properties/organization",
          "type": "string",
          "title": "Organization or consortium submitting the genome assembly",
          "default": "",
          "examples": ["Institute of Klebsiella foobarensis research"]
        },
        "phone": {
          "$id": "/properties/contact_info/properties/phone",
          "type": "string",
          "title": "Phone number",
          "default": "",
          "examples": ["301-555-0245"]
        },
        "postal_code": {
          "$id": "/properties/contact_info/properties/postal_code",
          "type": "string",
          "title": "Postal code",
          "default": "",
          "examples": ["12345"]
        },
        "street": {
          "$id": "/properties/contact_info/properties/street",
          "type": "string",
          "title": "Street address",
          "default": "",
          "examples": ["1234 Main St"]
        }
      }
    },
    "fasta": {
      "$id": "/properties/fasta",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "class": {
          "$id": "/properties/fasta/properties/class",
          "type": "string",
          "title": "Class of input type",
          "default": "",
          "examples": ["File"]
        },
        "location": {
          "$id": "/properties/fasta/properties/location",
          "type": "string",
          "title": "Location of input file",
          "default": "",
          "examples": ["sample_fasta_input.fasta"]
        }
      }
    },
    "locus_tag_prefix": {
      "$id": "/properties/locus_tag_prefix",
      "type": "string",
      "title": "Locus tag prefix",
      "description": "One to 9-letter prefix to use for naming genes on this genome assembly. If an official locus tag prefix was already reserved from an INSDC organization (GenBank, ENA or DDBJ) for the given BioSample and BioProject pair, provide here. Otherwise, provide a string of your choice. If no value is provided, the prefix 'pgaptmp' will be used. See more details in this Note about locus tags at: https://github.com/ncbi/pgap/wiki/Input-Files#Note-about-locus-tags",
      "default": "",
      "examples": ["tmp"]
    },
    "organism": {
      "$id": "/properties/organism",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "strain": {
          "$id": "/properties/organism/properties/strain",
          "type": "string",
          "title": "Strain",
          "description": "Strain of the sequenced organism",
          "default": "",
          "examples": ["my_strain"]
        },
        "genus_species": {
          "$id": "/properties/organism/properties/genus_species",
          "type": "string",
          "title": "Genus and species",
          "description": "Binomial name or, if the species is unknown, genus for the sequenced organism. This identifier must be valid in NCBI Taxonomy. See Taxonomy information for how to find out if the name is valid: https://github.com/ncbi/pgap/wiki/Input-Files#Taxonomy-information",
          "default": "",
          "examples": ["Escherichia coli"]
        }
      }
    },
    "publications": {
      "$id": "/properties/publications",
      "type": "array",
      "title": "Publication describing the genome assembly",
      "items": {
        "$id": "/properties/publications/items",
        "type": "object",
        "additionalProperties": false,
        "required": ["publication"],
        "properties": {
          "publication": {
            "$id": "/properties/publications/items/properties/publication",
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "authors": {
                "$id": "/properties/publications/items/properties/publication/properties/authors",
                "title": "Author(s)",
                "type": "array",
                "items": {
                  "$id": "/properties/publications/items/properties/publication/properties/authors/items",
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "author": {
                      "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author",
                      "type": "object",
                      "additionalProperties": false,
                      "required": ["first_name", "last_name"],
                      "properties": {
                        "first_name": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/first_name",
                          "type": "string",
                          "title": "First name",
                          "default": "",
                          "examples": ["Arnold"]
                        },
                        "last_name": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/last_name",
                          "type": "string",
                          "title": "Last name",
                          "default": "",
                          "examples": ["Schwarzenegger"]
                        },
                        "middle_initial": {
                          "$id": "/properties/publications/items/properties/publication/properties/authors/items/properties/author/properties/middle_initial",
                          "type": "string",
                          "title": "First letter of middle name",
                          "default": "",
                          "examples": ["T800"]
                        }
                      }
                    }
                  }
                }
              },
              "status": {
                "$id": "/properties/publications/items/properties/publication/properties/status",
                "type": "string",
                "title": "Publication status",
                "description": "Can be only one of: published, in-press, unpublished",
                "default": "",
                "enum": ["published", "in-press", "unpublished"]
              },
              "pmid": {
                "$id": "/properties/publications/items/properties/publication/properties/pmid",
                "type": "integer",
                "title": "PubMed ID for the publication",
                "default": ""
              },
              "title": {
                "$id": "/properties/publications/items/properties/publication/properties/title",
                "type": "string",
                "title": "Title",
                "default": "",
                "examples": [
                  "Discrete CHARMm of Klebsiella foobarensis. Journal of Improbable Results, vol. 34, issue 13, pages: 10001-100005, 2018"
                ]
              }
            }
          }
        }
      }
    },
    "topology": {
      "$id": "/properties/topology",
      "type": "string",
      "title": "Topology of the sequences included in the fasta file",
      "description": "Possible values are linear or circular. Circular means that the first base in the sequence is adjacent to the last base. Please provide the topology in the metadata YAML file only if it is applicable to ALL sequences in the fasta file. If some sequences in the assembled genome are circular and others linear, include the topology in the definition line of each sequence in the fasta file with the tag value pair [topology=circular] or [topology=linear], after the SeqID and a space (e.g. >seq1 [topology=circular]). If the topology is provided in neither the metadata YAML nor the fasta file, the sequences will be presumed to be linear.",
      "default": "",
      "examples": ["circular", "linear"]
    },
    "location": {
      "$id": "/properties/location",
      "type": "string",
      "title": "Location of the sequences included in the fasta file",
      "description": "Possible values are chromosome or plasmid. Please provide the location in the metadata YAML file only if it is applicable to ALL sequences in the fasta file. If some sequences in the assembled genome are chromosomes and others plasmids, include the location in the definition line of each sequence in the fasta file with the tag value pair [location=chromosome] or [location=plasmid], after the SeqID and a space (e.g. >seq1 [location=plasmid]). In plasmid case add [plasmid-name=<plasmidname>]. If the location is provided in neither the metadata YAML nor the fasta file, the sequences will be presumed to be chromosome. Note: since 2021 releases of PGAPx this will affect noticeably the annotation on the molecule",
      "default": "",
      "examples": ["chromosome", "plasmid"]
    }
  },
  "required": ["authors", "contact_info"],
  "title": "NCBI PGAP submol YAML",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "description": "plagiarize.yaml configuration schema",
  "id": "https://json.schemastore.org/plagiarize",
  "properties": {
    "repo": {
      "required": ["url"],
      "type": "object",
      "description": "Configuration for strings, files, and file paths to replace in target file",
      "properties": {
        "url": {
          "description": "Git url of project to plagiarize",
          "type": "string"
        },
        "checkout": {
          "description": "Branch, tag, or commit to checkout from project to be plagiarized",
          "type": "string"
        }
      }
    },
    "strings": {
      "type": "object",
      "description": "Strings to find in target project and be replaced with plagiarized project's values",
      "additionalProperties": {
        "type": ["string", "integer", "boolean"]
      },
      "required": ["project"],
      "properties": {
        "project": {
          "type": "string"
        }
      }
    },
    "vars": {
      "type": "object",
      "description": "Variables available to be used for finding and replacing by variable name. For example `$var_name: hello` would replace string '$var_name' with 'hello' in target project",
      "additionalProperties": {
        "type": ["string", "integer", "boolean"]
      }
    }
  },
  "required": ["repo", "strings"],
  "title": "Plagiarize configuration",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "description": "Ignored. Can be set to get completions, validations and documentation in some editors.",
      "example": [
        "https://openapi.vercel.sh/vercel.json"
      ],
      "type": "string"
    },
    "alias": {
      "description": "Aliases that will get assigned when the deployment is `READY` and the target is `production`. The client needs to make a `GET` request to its API to ensure the assignment",
      "example": [
        "example.vercel.app"
      ],
      "oneOf": [
        {
          "private": true,
          "type": "string"
        },
        {
          "items": {
            "maxLength": 253,
            "type": "string"
          },
          "maxItems": 50,
          "maxLength": 253,
          "type": "array"
        }
      ]
    },
    "build": {
      "additionalProperties": false,
      "description": "An object containing another object with information to be passed to the Build Process",
      "deprecated": true,
      "properties": {
        "env": {
          "additionalProperties": false,
          "description": "An object containing the deployment's environment variable names and values to be passed to Builds. Secrets can be referenced by prefixing the value with `@`",
          "example": {
            "A_SECRET": "@a-secret"
          },
          "deprecated": true,
          "maxProperties": 100,
          "minProperties": 0,
          "patternProperties": {
            ".+": {
              "maxLength": 65536,
              "minLength": 0,
              "type": "string"
            }
          },
          "type": "object"
        }
      },
      "type": "object"
    },
    "builds": {
      "description": "A list of build descriptions whose src references valid source files.",
      "deprecated": true,
      "items": {
        "additionalProperties": false,
        "properties": {
          "config": {
            "description": "Optionally, an object including arbitrary metadata to be passed to the Builder",
            "type": "object"
          },
          "src": {
