    "version": {
      "description": "Version of the op",
      "$ref": "#/properties/opspec"
    },
    "opspec": {
      "description": "Version of [opspec](https://opspec.io) used by the op",
      "title": "semVer",
      "type": "string",
      "pattern": "^([0-9]+)\\.([0-9]+)\\.([0-9]+)(?:(-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?(?:\\+[0-9A-Za-z-\\-\\.]+)?$"
    }
  },
  "required": ["name"],
  "title": "Op File"
}

{
  "$comment": "https://minecraft.fandom.com/wiki/Loot_table",
  "$id": "https://json.schemastore.org/minecraft-loot-table.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "numberProvider": {
      "$comment": "https://minecraft.fandom.com/wiki/Loot_table#Number_Providers",
      "properties": {
        "type": {
          "title": "Type",
          "description": "The number provider type.",
          "type": "string",
          "enum": [
            "minecraft:constant",
            "minecraft:uniform",
            "minecraft:binomial",
            "minecraft:score"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:constant"
              }
            }
          },
          "then": {
            "description": "A constant value.",
            "properties": {
              "value": {
                "title": "Value",
                "description": "The exact value.",
                "type": "number"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:uniform"
              }
            }
          },
          "then": {
            "description": "A random number following a uniform distribution between two values (inclusive).",
            "properties": {
              "min": {
                "title": "Minimum",
                "description": "The minimum value.",
                "type": ["number", "object"],
                "$ref": "#/definitions/numberProvider"
              },
              "max": {
                "title": "Max",
                "description": "The maximum value.",
                "type": ["number", "object"],
                "$ref": "#/definitions/numberProvider"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:binomial"
              }
            }
          },
          "then": {
            "description": "A random number following a binomial distribution.",
            "properties": {
              "n": {
                "title": "n",
                "description": "The amount of trials.",
                "type": ["integer", "object"],
                "$ref": "#/definitions/numberProvider"
              },
              "p": {
                "title": "p",
                "description": "The probability of success on an individual trial.",
                "$ref": "#/definitions/numberProvider"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "minecraft:score"
              }
            }
          },
          "then": {
            "description": "A scoreboard value.",
            "properties": {
              "target": {
                "title": "Target",
                "description": "Scoreboard name provider.",
                "type": ["string", "object"],
                "enum": ["this", "killer", "direct_killer", "player_killer"],
                "properties": {
                  "type": {
                    "title": "Type",
                    "description": "Resource location.",
                    "type": "string",
                    "enum": ["fixed", "context"]
                  }
                },
                "allOf": [
                  {
                    "if": {
                      "properties": {
                        "type": {
                          "const": "fixed"
                        }
                      }
                    },
                    "then": {
                      "properties": {
                        "name": {
                          "title": "Name",
                          "description": "A UUID or player name.",
                          "type": "string"
                        }
                      }
                    }
                  },
                  {
                    "if": {
                      "properties": {
                        "type": {
                          "const": "context"
                        }
                      }
                    },
                    "then": {
                      "properties": {
                        "target": {
                          "title": "Target",
                          "type": "string",
                          "enum": [
                            "this",
                            "killer",
                            "direct_killer",
                            "player_killer"
                          ]
                        }
                      }
                    }
                  }
                ]
              },
              "score": {
                "title": "Score",
                "description": "The scoreboard objective.",
                "type": "string"
              },
              "scale": {
                "title": "Scale",
                "description": "Scale to multiply the score before returning it.",
                "type": "number"
              }
            }
          }
        }
      ]
    }
  },
  "description": "Configuration file defining a loot table for a data pack for Minecraft.",
  "properties": {
    "type": {
      "title": "Type",
      "type": "string",
      "enum": [
        "minecraft:empty",
        "empty",
        "minecraft:entity",
        "entity",
        "minecraft:block",
        "block",
        "minecraft:chest",
        "chest",
        "minecraft:fishing",
        "fishing",
        "minecraft:gift",
        "gift",
        "minecraft:advancement_reward",
        "advancement_reward",
        "minecraft:barter",
        "barter",
        "minecraft:command",
        "command",
        "minecraft:selector",
        "selector",
        "minecraft:advancement_entity",
        "advancement_entity",
        "minecraft:generic",
        "generic"
      ]
    },
    "functions": {
      "title": "Functions",
      "description": " Applies functions to all item stacks produced by this table. Functions are applied in order, so for example looting_enchant must be after set_count to work correctly.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": {
          "description": "A function.",
          "type": "object",
          "properties": {
            "function": {
              "title": "Function",
              "description": "Namespaced ID of the function to apply.",
              "type": "string"
            },
            "conditions": {
              "title": "Conditions",
              "description": "Determines conditions for this function to be applied. If multiple conditions are specified, all must pass.",
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": {
                  "description": "A function.",
                  "type": "object",
                  "properties": {
                    "condition": {
                      "title": "Condition",
                      "description": "Namespaced ID of condition.",
                      "type": "string"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "pools": {
      "title": "Pools",
      "description": "A list of all pools for this loot table. Each pool used generates items from its list of items based on the number of rolls. Pools are applied in order.",
      "type": "array",
      "items": {
        "description": "A pool.",
        "type": "object",
        "properties": {
          "conditions": {
            "title": "Conditions",
            "description": "Determines conditions for this pool to be used. If multiple conditions are specified, all must pass.",
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": {
                "description": "A condition.",
                "properties": {
                  "condition": {
                    "title": "Condition",
                    "description": "Namespaced ID of condition.",
                    "type": "string"
                  }
                }
              }
            }
          },
          "functions": {
            "title": "Functions",
            "description": "Applies functions to all item stacks produced by this pool. Functions are applied in order, so for example looting_enchant must be after set_count to work correctly.",
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": {
                "description": "A function.",
                "properties": {
                  "function": {
                    "title": "Function",
                    "description": "Namespaced ID of the function to apply.",
                    "type": "string"
                  },
                  "conditions": {
                    "title": "Conditions",
                    "description": "Determines conditions for this function to be applied. If multiple conditions are specified, all must pass.",
                    "type": "array",
                    "items": {
                      "description": "A condition.",
                      "type": "object",
                      "properties": {
                        "condition": {
                          "title": "Condition",
                          "description": "Namespaced ID of condition.",
                          "type": "string"
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "rolls": {
            "title": "Rolls",
            "description": "Specifies the number of rolls on the pool.",
            "type": ["integer", "object"],
            "$ref": "#/definitions/numberProvider"
          },
          "bonus_rolls": {
            "title": "Bonus Rolls",
            "description": "Specifies the number of bonus rolls on the pool per point of luck. Rounded down after multiplying.",
            "type": ["number", "object"],
            "$ref": "#/definitions/numberProvider"
          },
          "entries": {
            "title": "Entries",
            "description": "A list of all things that can be produced by this pool. One entry is chosen per roll as a weighted random selection from all entries without failing conditions.",
            "type": "array",
            "items": {
              "description": "An entry.",
              "type": "object",
              "properties": {
                "conditions": {
                  "title": "Conditions",
                  "description": "Determines conditions for this entry to be used. If multiple conditions are specified, all must pass.",
                  "type": "array",
                  "items": {
                    "type": "object",
                    "additionalProperties": {
                      "description": "A condition.",
                      "properties": {
                        "condition": {
                          "title": "Condition",
                          "description": "Namespaced ID of condition.",
                          "type": "string"
                        }
                      }
                    }
                  }
                },
                "functions": {
                  "title": "Functions",
                  "description": "Applies functions to the item stack or item stacks being produced. Functions are applied in order, so for example looting_enchant must be after set_count to work correctly.",
                  "type": "array",
                  "items": {
                    "type": "object",
                    "additionalProperties": {
                      "description": "A function.",
                      "properties": {
                        "function": {
                          "title": "Function",
                          "description": "Namespaced ID of the function to apply.",
                          "type": "string"
                        },
                        "conditions": {
                          "title": "Conditions",
                          "description": "Determines conditions for this function to be applied. If multiple conditions are specified, all must pass.",
                          "type": "array",
                          "items": {
                            "description": "A condition.",
                            "type": "object",
                            "properties": {
                              "condition": {
                                "title": "Condition",
                                "description": "Namespaced ID of condition.",
                                "type": "string"
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                },
                "type": {
                  "title": "Type",
                  "description": "Namespaced ID type of entry.",
                  "type": "string",
                  "enum": [
                    "minecraft:item",
                    "minecraft:tag",
                    "minecraft:loot_table",
                    "minecraft:group",
                    "minecraft:alternatives",
                    "minecraft:sequence",
                    "minecraft:dynamic",
                    "minecraft:empty"
                  ]
                },
                "name": {
                  "title": "Name",
                  "type": "string"
                },
                "children": {
                  "title": "Children",
                  "type": "array"
                },
                "expand": {
                  "title": "Expand",
                  "description": "For type 'tag', if set to true, it chooses one item of the tag, each with the same weight and quality. If false, it generates one of each of the items in the tag.",
                  "type": "boolean"
                },
                "weight": {
                  "title": "Weight",
                  "description": "Determines how often this entry is chosen out of all the entries in the pool. Entries with higher weights are used more often (chance is this entry's weight⁄total of all considered entries' weights).",
                  "type": "integer"
                },
                "quality": {
                  "title": "Quality",
                  "description": "Modifies the entry's weight based on the killing/opening/fishing player's luck attribute. Formula is floor( weight + (quality * generic.luck)).",
                  "type": "integer"
                }
              }
            }
          }
        }
      }
    }
  },
  "title": "Minecraft Data Pack Loot Table"
}

{
    "$schema": "http://json-schema.org/draft-07/schema",
    "$id": "https://raw.githubusercontent.com/hexagonkt/codecv/master/cv.schema.json",
    "$ref": "#/$defs/Cv",
    "$defs": {
        "Language": {
            "type": "string",
            "pattern": "[a-z]{2}"
        },
        "Country": {
            "type": "string",
            "pattern": "[A-Z]{2}"
        },
        "NullableCountry": {
            "type": [
                "string",
                "null"
            ],
            "pattern": "[A-Z]{2}"
        },
        "Disability": {
            "title": "Disability information",
            "type": "object",
            "required": [
                "Type"
            ],
            "additionalProperties": false,
            "properties": {
                "Type": {
                    "title": "Kind of disability",
                    "type": "string",
                    "enum": [
                        "visual",
                        "auditory",
                        "movement",
                        "mental"
                    ]
                },
                "Level": {
                    "title": "Disability degree",
                    "description": "Disability degree. Value must be between 1.0 (fully disabled) and 0",
                    "$ref": "#/$defs/NullableNumber"
                },
                "Summary": {
                    "title": "Text describing the disability",
                    "$ref": "#/$defs/NullableString"
                }
            }
        },
        "DrivingLicense": {
            "title": "Driving license details",
            "type": "object",
            "required": [
                "Country",
                "License"
            ],
            "additionalProperties": false,
            "properties": {
                "Country": {
                    "title": "Country issuing the driver license",
                    "$ref": "#/$defs/Country"
                },
                "License": {
                    "title": "Kind of driver licence, i",
                    "description": "Kind of driver licence, i.e.: A, B1, etc",
                    "type": "string"
                }
            }
        },
        "IdDocument": {
            "title": "Identification document",
            "description": "Identification document, I.e.: passport",
            "type": "object",
            "required": [
                "Country",
                "Document",
                "Id"
            ],
            "additionalProperties": false,
            "properties": {
                "Country": {
                    "title": "Issuer of the document",
                    "$ref": "#/$defs/Country"
                },
                "Document": {
                    "title": "Document name",
                    "description": "Document name. It could be a national document name, or passport",
                    "type": "string"
                },
                "Id": {
                    "title": "Code with the serial number of the document for the CV principal",
                    "type": "string"
                }
            }
        },
        "Personal": {
            "title": "Personal information, not related with professional skills or qualifications",
            "type": "object",
            "required": [
                "Given Name",
                "Family Name",
                "Native Language"
            ],
            "additionalProperties": false,
            "properties": {
                "Given Name": {
                    "title": "Given name",
                    "description": "Given name. It can be multiple words for compound names",
                    "type": "string"
                },
                "Family Name": {
                    "title": "Family name",
                    "description": "Family name. Depending on cultures, this field can be very different",
                    "type": "string"
                },
                "Native Language": {
                    "title": "First learned language",
                    "description": "First learned language. Or preferred language if you had many",
                    "$ref": "#/$defs/Language"
                },
                "Pronoun": {
                    "title": "Pronoun to state how do you like to be addressed",
                    "type": [
                        "null",
                        "string"
                    ],
                    "enum": [
                        "feminine",
                        "masculine",
                        "neutral"
                    ]
                },
                "Gender": {
                    "title": "Gender role",
                    "type": [
                        "null",
                        "string"
                    ],
                    "enum": [
                        "woman",
                        "man",
                        "lesbian",
                        "gay",
                        "transgender woman",
                        "transgender man",
                        "bisexual",
                        "intersexual",
                        "queer",
                        "agender",
                        "other"
                    ]
                },
                "Birth": {
                    "title": "Date of birth",
                    "$ref": "#/$defs/NullableDate"
                },
                "Birth Country": {
                    "title": "Country of birth",
                    "$ref": "#/$defs/NullableCountry"
                },
                "Alias": {
                    "title": "Short name you commonly use or nickname",
                    "$ref": "#/$defs/NullableString"
                },
                "Photo": {
                    "title": "Photo address",
                    "$ref": "#/$defs/NullableUri"
                },
                "Avatar": {
                    "title": "Avatar",
                    "description": "Avatar. Image used to represent you without being an actual photo",
                    "$ref": "#/$defs/NullableUri"
                },
                "Nationalities": {
                    "title": "Set of nationalities",
                    "description": "Set of nationalities. If none is supplied, the birth of country is used",
                    "type": "array",
                    "uniqueItems": true,
                    "items": {
                        "$ref": "#/$defs/Country"
                    }
                },
                "Disabilities": {
                    "title": "List of disabilities of a person",
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/Disability"
                    }
                },
                "Driving Licenses": {
                    "title": "List of driving permissions",
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/DrivingLicense"
                    }
                },
                "Ids": {
                    "title": "Id documents owned by country",
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/IdDocument"
                    }
                }
            }
        },
        "Location": {
            "title": "Area that may have different degrees of precision, from a whole country, to a street address",
            "type": "object",
            "required": [
                "Country"
            ],
            "additionalProperties": false,
            "properties": {
                "Country": {
                    "title": "Location country",
