        },
        "character_limit": {
          "type": [
            "integer"
          ]
        },
        "antlers": {
          "$ref": "#/$defs/antlers"
        },
        "default": {
          "type": "string"
        },
        "append": {
          "type": "string"
        },
        "prepend": {
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "textarea": {
      "description": "A long textarea field that functions like a swimming pool for letters and numbers on a hot day.",
      "type": "object",
      "properties": {
        "type": {
          "const": "textarea"
        },
        "placeholder": {
          "$ref": "#/$defs/placeholder"
        },
        "character_limit": {
          "type": [
            "integer",
            "string"
          ]
        },
        "antlers": {
          "$ref": "#/$defs/antlers"
        },
        "default": {
          "type": "string"
        }
      },
      "additionalProperties": true
    },
    "time": {
      "description": "The original time field from the set of Kiefer Sutherland's hit drama \"24\".",
      "type": "object",
      "properties": {
        "type": {
          "const": "time"
        },
        "default": {
          "type": "string",
          "pattern": "^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$"
        }
      },
      "additionalProperties": true
    },
    "toggle": {
      "description": "A nice little toggle switch generally used to manage settings-type variables.",
      "type": "object",
      "properties": {
        "type": {
          "const": "toggle"
        },
        "default": {
          "type": "boolean",
          "default": false
        }
      },
      "additionalProperties": true
    },
    "user_groups": {
      "description": "The User Group fieldtype gives your users a way to pick one or more User Groups to attach to the current entry.",
      "type": "object",
      "properties": {
        "type": {
          "const": "user_groups"
        },
        "max_items": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 1,
          "default": null
        },
        "mode": {
          "$ref": "#/$defs/userSelectModes"
        }
      },
      "additionalProperties": true
    },
    "user_roles": {
      "description": "The User Role fieldtype gives your users a way to pick one or more User Groups to attach to the current entry.",
      "type": "object",
      "properties": {
        "type": {
          "const": "user_roles"
        },
        "max_items": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 1,
          "default": null
        },
        "mode": {
          "$ref": "#/$defs/userSelectModes"
        }
      },
      "additionalProperties": true
    },
    "users": {
      "description": "The most common use for the Users fieldtype is to set the \"author\" for entries, but it's not the only use.",
      "type": "object",
      "properties": {
        "type": {
          "const": "users"
        },
        "max_items": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 1,
          "default": null
        },
        "mode": {
          "$ref": "#/$defs/userSelectModes"
        },
        "default": {
          "type": "string",
          "const": "current"
        }
      },
      "additionalProperties": true
    },
    "video": {
      "description": "",
      "type": "object",
      "properties": {
        "type": {
          "const": "video"
        },
        "placeholder": {
          "$ref": "#/$defs/placeholder"
        },
        "default": {
          "type": "string",
          "format": "url"
        }
      },
      "additionalProperties": true
    },
    "yaml": {
      "description": "This field is a code fieldtype that gets saved as YAML instead of a string.",
      "type": "object",
      "properties": {
        "type": {
          "const": "yaml"
        },
        "default": {
          "type": [
            "object",
            "string"
          ]
        }
      },
      "additionalProperties": true
    },
    "display": {
      "description": "The label shown above the field.",
      "type": "string"
    },
    "icon": {
      "description": "The icon",
      "type": "string"
    },
    "instructions": {
      "description": "Shown under the field's display label, like this very text. Markdown is supported.",
      "type": "string"
    },
    "instructions_position": {
      "description": "Where the instructions should be positioned relative to the field. Options: Above or Below.",
      "type": "string",
      "enum": [
        "above",
        "below"
      ]
    },
    "listable": {
      "description": "Controls whether the field should be shown in control panel listings.",
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "string",
          "pattern": "hidden"
        }
      ]
    },
    "required": {
      "description": "Control whether or not this field is required.\n\n",
      "type": "boolean"
    },
    "localizable": {
      "description": "",
      "type": "boolean"
    },
    "validate": {
      "description": "The validation rules for that field",
      "type": "array",
      "items": {
        "anyOf": [
          {
            "$ref": "#/$defs/ruleMin"
          },
          {
            "$ref": "#/$defs/validationRules"
          }
        ],
        "minItems": 1,
        "uniqueItems": true
      }
    },
    "ruleMin": {
      "type": "string",
      "pattern": "^((accepted|declined|exclude)_if:\\S+,\\S+|(after|before):[\\w\\d_-]+|(after|before)_or_equal:[\\w\\d_-]+|between:\\d+,\\d+|date_equals:[\\w\\d_-]+|date_format:[\\w\\d_-]+|different:\\S+|digits:\\d+|digits_between:\\d+,\\d+|ends_with:\\S+,\\S+|exclude_unless:\\S+,\\S+|exclude_without:\\S+|exists:\\S+,\\S+|[lg]t(e)?:\\S+|in:\\S+,\\S+|in_array:\\S+|(min|max):\\d+|mimetypes:\\S+|mimes:\\S+|multiple_of:\\d+|not_in:\\S+,\\S+|(not_)?regex:\\S+|prohibited_(if|unless):[\\S_]+,\\S+|prohibits:(\\S)+,(\\S)+|required_(if|unless):\\S+,\\d+|required_(with|with_all|without|without_all):\\S+,\\S+|same:\\S+|size:\\d+|starts_with:\\S+,\\S+|unique:\\S+,\\S+|unique_user_value:[\\{(collection|id|site)\\}]+)$"
    },
    "validationRules": {
      "type": "string",
      "enum": [
        "accepted",
        "active_url",
        "required",
        "alpha",
        "alpha_dash",
        "alpha_num",
        "array",
        "bail",
        "boolean",
        "confirmed",
        "current_password",
        "date",
        "declined",
        "dimensions",
        "distinct",
        "email",
        "enum",
        "exclude",
        "file",
        "filled",
        "image",
        "integer",
        "ip",
        "ipv4",
        "ipv6",
        "json",
        "nullable",
        "numeric",
        "password",
        "present",
        "prohibited",
        "string",
        "timezone",
        "url",
        "uuid"
      ]
    },
    "userSelectModes": {
      "type": "string",
      "enum": [
        "default",
        "select",
        "typeahead"
      ]
    },
    "placeholder": {
      "type": "string"
    },
    "antlers": {
      "description": "Enable Antlers parsing in this field's content.",
      "type": "boolean",
      "default": false
    },
    "max_items": {
      "type": "integer",
      "minimum": 1
    }
  }
}

{
    "$schema": "http://json-schema.org/draft-07/schema",
    "description": "Freifunk Community API 0.5.2",
    "type": "object",
    "definitions": {

        "city": {
