                        "pattern": "^([0-9]{4})(?:-?W([0-9]+)(?:-?([0-9]+)D?)?|(?:-([0-9]+))?-([0-9]+))(?:[T ]([0-9]+):([0-9]+)(?::([0-9]+)(?:\\.([0-9]+))?)?)?(?:Z(-?[0-9]*))?"
                    },
                    "url": {
                        "$ref": "#/definitions/url",
                        "title": "URL",
                        "description": "URL to details of this timeline-element"
