                        "default": ""
                    },
                    "mapType": {
                        "type": "string",
                        "title": "Maptype",
                        "description": "",
                        "enum": [ "", "geographical", "structural", "list/status" ],
                        "default": ""
                    }
                },
                "additionalProperties": false
            }
        },

        "services": {
            "type": "array",
            "title": "Services",
            "description": "Services Provided by your community",
            "items": {
                "type": "object",
                "properties": {
                    "serviceName": {
                        "type": "string",
                        "title": "Service Name",
                        "description": "Name of your service (e.g. jabber...)"
                    },
                    "serviceDescription": {
                        "type": "string",
                        "title": "Service Description",
                        "description": "Describe your service"
                    },
                    "externalUri": {
                        "type": "string",
                        "title": "External URI",
                        "description": "URI to use your service from the internet"
                    },
                    "internalUri": {
                        "type": "string",
                        "title": "Internal URI",
                        "description": "URI to use your service from Freifunk or icvpn-networks"
                    }
                },
                "additionalProperties": false
            }
        },

        "support": {
            "type": "object",
            "title": "Support for your community",
            "properties": {
                "club": {
                    "type": "object",
                    "title": "Supporting Club",
                    "properties": {
                        "name": {
                            "type": "string",
                            "title": "Club Name",
                            "description": "Name of the Club"
                        },
                        "street": {
                            "type": "string",
                            "title": "Street",
                            "description": "Address - Street"
                        },
                        "zip": {
                            "type": "string",
                            "title": "ZIP",
                            "description": "Address - ZIP"
                        },
                        "city": { "$ref": "#/definitions/city" },
                        "url": {
                            "$ref": "#/definitions/url",
                            "title": "HomePage",
                            "description": "The club's website (http{s}://...)"
                        },
                        "email": {
                            "$ref": "#/definitions/email",
                            "description": "Email address to contact the club (user@domain.com)"
                        },
                        "board": {
                            "type": "array",
                            "title": "Board Members",
                            "description": "Who are the board members of the club?",
                            "items": {
                                "type": "string",
                                "title": "Name"
                            }
                        }
                    },
                    "additionalProperties": false
                },
                "donations": {
                    "type": "object",
                    "title": "Donations",
                    "properties": {
                        "bankaccount": {
                            "type": "object",
                            "title": "Bank Account",
                            "properties": {
                                "IBAN": {
                                    "type": "string",
                                    "title": "IBAN"
                                },
                                "BIC": {
                                    "type": "string",
                                    "title": "BIC"
                                },
                                "usage": {
                                    "type": "string",
                                    "title": "Usage of the donations",
                                    "description": "Please use this string as transfer-purpose to define a special usage of your donation."
                                }
                            },
                            "additionalProperties": false
                        },
                        "campaigns": {
                            "type": "array",
                            "title": "Campaigns",
