{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "stringOrStringArray": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
    },
    "rule": {
      "oneOf": [
        {
          "description": "ESLint rule\n\n0 - turns the rule off\n1 - turn the rule on as a warning (doesn't affect exit code)\n2 - turn the rule on as an error (exit code is 1 when triggered)\n",
          "type": "integer",
          "minimum": 0,
          "maximum": 2
        },
        {
          "description": "ESLint rule\n\n\"off\" - turns the rule off\n\"warn\" - turn the rule on as a warning (doesn't affect exit code)\n\"error\" - turn the rule on as an error (exit code is 1 when triggered)\n",
          "type": "string",
          "enum": ["off", "warn", "error"]
        },
        {
          "type": "array"
        }
      ]
    },
    "possibleErrors": {
      "type": "object",
      "properties": {
        "comma-dangle": {
          "$ref": "#/definitions/rule",
          "description": "Require or disallow trailing commas"
        },
        "for-direction": {
          "$ref": "#/definitions/rule",
          "description": "Enforce \"for\" loop update clause moving the counter in the right direction"
        },
        "getter-return": {
          "$ref": "#/definitions/rule",
          "description": "Enforce return statements in getters"
        },
        "no-await-in-loop": {
          "$ref": "#/definitions/rule",
          "description": "Disallow await inside of loops"
        },
        "no-compare-neg-zero": {
          "$ref": "#/definitions/rule",
          "description": "Disallow comparing against -0"
        },
        "no-cond-assign": {
          "$ref": "#/definitions/rule",
          "description": "Disallow assignment operators in conditional expressions"
        },
        "no-console": {
          "$ref": "#/definitions/rule",
          "description": "Disallow the use of console"
        },
        "no-constant-condition": {
          "$ref": "#/definitions/rule",
          "description": "Disallow constant expressions in conditions"
        },
        "no-control-regex": {
          "$ref": "#/definitions/rule",
          "description": "Disallow control characters in regular expressions"
        },
        "no-debugger": {
          "$ref": "#/definitions/rule",
          "description": "Disallow the use of debugger"
        },
        "no-dupe-args": {
          "$ref": "#/definitions/rule",
          "description": "Disallow duplicate arguments in function definitions"
        },
        "no-dupe-keys": {
          "$ref": "#/definitions/rule",
          "description": "Disallow duplicate keys in object literals"
        },
        "no-duplicate-case": {
          "$ref": "#/definitions/rule",
          "description": "Disallow duplicate case labels"
        },
        "no-empty": {
          "$ref": "#/definitions/rule",
          "description": "Disallow empty block statements"
        },
        "no-empty-character-class": {
          "$ref": "#/definitions/rule",
          "description": "Disallow empty character classes in regular expressions"
        },
        "no-ex-assign": {
          "$ref": "#/definitions/rule",
