    "parserOptions": {
      "description": "The JavaScript language options to be supported",
      "type": "object",
      "properties": {
        "ecmaFeatures": {
          "$ref": "#/properties/ecmaFeatures"
        },
        "ecmaVersion": {
          "enum": [
            3,
            5,
            6,
            2015,
            7,
            2016,
            8,
            2017,
            9,
            2018,
            10,
            2019,
            11,
            2020,
            12,
            2021,
            13,
            2022,
            14,
            2023,
            "latest"
          ],
          "default": 11,
          "description": "Set to 3, 5, 6, 7, 8, 9, 10, 11 (default), 12, 13, 14 or \"latest\" to specify the version of ECMAScript syntax you want to use. You can also set to 2015 (same as 6), 2016 (same as 7), 2017 (same as 8), 2018 (same as 9), 2019 (same as 10), 2020 (same as 11), 2021 (same as 12), 2022 (same as 13) or 2023 (same as 14) to use the year-based naming. \"latest\" always enables the latest supported ECMAScript version."
        },
        "sourceType": {
          "enum": ["script", "module"],
          "default": "script",
          "description": "set to \"script\" (default) or \"module\" if your code is in ECMAScript modules"
        }
      }
    },
    "plugins": {
      "description": "ESLint supports the use of third-party plugins. Before using the plugin, you have to install it using npm.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "root": {
      "description": "By default, ESLint will look for configuration files in all parent folders up to the root directory. This can be useful if you want all of your projects to follow a certain convention, but can sometimes lead to unexpected results. To limit ESLint to a specific project, set this to `true` in a configuration in the root of your project.",
      "type": "boolean"
    },
    "ignorePatterns": {
      "description": "Tell ESLint to ignore specific files and directories. Each value uses the same pattern as the `.eslintignore` file.",
      "$ref": "#/definitions/stringOrStringArray"
    },
    "rules": {
      "description": "ESLint comes with a large number of rules. You can modify which rules your project uses either using configuration comments or configuration files.",
      "type": "object",
      "allOf": [
        {
          "$ref": "#/definitions/possibleErrors"
        },
        {
          "$ref": "#/definitions/bestPractices"
        },
        {
          "$ref": "#/definitions/strictMode"
        },
        {
          "$ref": "#/definitions/variables"
        },
        {
          "$ref": "#/definitions/nodeAndCommonJs"
        },
        {
          "$ref": "#/definitions/stylisticIssues"
        },
        {
          "$ref": "#/definitions/ecmaScript6"
        },
        {
          "$ref": "#/definitions/legacy"
        }
      ]
    },
    "settings": {
      "description": "ESLint supports adding shared settings into configuration file. You can add settings object to ESLint configuration file and it will be supplied to every rule that will be executed. This may be useful if you are adding custom rules and want them to have access to the same information and be easily configurable.",
      "type": "object"
    },
    "overrides": {
      "type": "array",
      "description": "Allows to override configuration for files and folders, specified by glob patterns",
      "items": {
        "type": "object",
        "properties": {
          "files": {
            "description": "Glob pattern for files to apply 'overrides' configuration, relative to the directory of the config file",
            "oneOf": [
              {
                "type": "string"
              },
              {
                "minItems": 1,
                "type": "array",
                "items": {
                  "type": "string"
                }
              }
            ]
          },
          "extends": {
            "description": "If you want to extend a specific configuration file, you can use the extends property and specify the path to the file. The path can be either relative or absolute.",
            "$ref": "#/definitions/stringOrStringArray"
          },
          "excludedFiles": {
            "description": "If a file matches any of the 'excludedFiles' glob patterns, the 'overrides' configuration won't apply",
            "$ref": "#/definitions/stringOrStringArray"
          },
          "ecmaFeatures": {
            "$ref": "#/properties/ecmaFeatures"
          },
          "env": {
            "$ref": "#/properties/env"
          },
          "globals": {
            "$ref": "#/properties/globals"
          },
          "parser": {
            "$ref": "#/properties/parser"
          },
          "parserOptions": {
            "$ref": "#/properties/parserOptions"
          },
          "plugins": {
            "$ref": "#/properties/plugins"
          },
          "processor": {
            "description": "To specify a processor, specify the plugin name and processor name joined by a forward slash",
            "type": "string"
          },
          "rules": {
            "$ref": "#/properties/rules"
          },
          "settings": {
            "$ref": "#/properties/settings"
          },
          "overrides": {
            "$ref": "#/properties/overrides"
          }
        },
        "additionalProperties": false,
        "required": ["files"]
      }
    }
  },
  "title": "JSON schema for ESLint configuration files",
  "type": "object"
}

{
  "title": "JSON schema for Outblocks App configuration files",
  "$schema": "http://json-schema.org/draft-07/schema",
  "$ref": "#/definitions/OutblocksApp",
  "definitions": {
    "OutblocksApp": {
      "title": "OutblocksApp",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "name": {
          "description": "Name of the app. Defaults to directory name.",
          "type": "string"
        },
        "type": {
          "description": "Type of the app.",
          "type": "string",
          "enum": [
            "static",
            "function",
            "service"
          ]
        },
        "env": {
          "description": "Environment variables common for all operations.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "dir": {
          "description": "Working directory of the app where all commands will be run. Defaults to location of this yaml. All other dirs will be relative to this one.",
          "type": "string"
        },
        "url": {
          "description": "External URL of the app.",
          "type": "string"
        },
        "path_redirect": {
          "description": "Path redirect rewrites URL to specified path. URL path from 'url' field will be stripped and replaced with value below.",
          "type": "string"
        },
        "needs": {
          "description": "Application dependencies to inject.",
          "$ref": "#/definitions/Needs"
        },
        "run": {
          "description": "Run config used for dev builds during run.",
          "$ref": "#/definitions/Run"
        },
        "cdn": {
          "description": "CDN settings.",
          "$ref": "#/definitions/CDN"
        },
        "build": {
          "type": "object"
        }
      },
      "required": [
        "type"
      ],
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "static"
              }
            }
          },
          "then": {
            "properties": {
              "routing": {
                "description": "Routing type. Defaults to 'react'.",
                "type": "string",
                "enum": [
                  "react",
                  "gatsby",
                  "disabled"
                ]
              },
              "remove_trailing_slash": {
                "description": "Remove trailing slash with permanent redirect. Currently used only for deployments. Defaults to 'true' when gatsby routing is used, 'false' otherwise.",
                "type": "boolean"
              },
              "basic_auth": {
                "description": "Static application basic authentication config. Currently used only for deployments.",
                "$ref": "#/definitions/StaticBasicAuth"
              },
              "build": {
                "description": "Static application build config used for deployment builds.",
                "$ref": "#/definitions/StaticBuild"
              },
              "deploy": {
                "description": "Static deploy config.",
                "$ref": "#/definitions/StaticDeploy"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "service"
              }
            }
          },
          "then": {
            "properties": {
              "private": {
                "description": "Marks app as private - won't allow unauthenticated access.",
                "type": "boolean"
              },
              "build": {
                "description": "Service application build config used for deployment builds.",
                "$ref": "#/definitions/ServiceBuild"
              },
              "container": {
                "description": "Service application container config used for docker based deployments/runs.",
                "$ref": "#/definitions/ServiceContainer"
              },
              "deploy": {
                "description": "Service deploy config.",
                "$ref": "#/definitions/ServiceDeploy"
              },
              "scheduler": {
                "description": "Service scheduler config.",
                "$ref": "#/definitions/Scheduler"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "function"
              }
            }
          },
          "then": {
            "required": [
              "type"
            ],
            "properties": {
              "private": {
                "description": "Marks app as private - won't allow unauthenticated access.",
                "type": "boolean"
              },
              "runtime": {
                "description": "The runtime in which the function is going to run, refer to cloud provider docs for possible options.",
                "type": "string"
              },
              "entrypoint": {
                "description": "Name of the function that will be executed when the function is triggered. Not all deployment plugins support it. Defaults to application name.",
                "type": "string"
              },
              "build": {
                "description": "Function application build config used for deployment builds.",
                "$ref": "#/definitions/FunctionBuild"
              },
              "deploy": {
                "description": "Function deploy config.",
                "$ref": "#/definitions/FunctionDeploy"
              },
              "package": {
                "description": "Function package config.",
                "$ref": "#/definitions/FunctionPackage"
              },
              "scheduler": {
                "description": "Function scheduler config.",
                "$ref": "#/definitions/Scheduler"
              }
            }
          }
        }
      ]
    },
    "Needs": {
      "title": "Needs",
      "type": "object",
      "additionalProperties": false,
      "patternProperties": {
        "^[_a-zA-Z][a-zA-Z0-9_-]*$": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "type": "object"
            }
          ]
        }
      }
    },
    "Run": {
      "title": "Run config",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Run plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "command": {
          "description": "Command to be run to for dev mode.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "port": {
          "description": "Port override, by default just assigns next port starting from listen-port.",
          "type": "integer"
        },
        "env": {
          "description": "Additional environment variables available local run.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        }
      }
    },
    "StaticDeploy": {
      "title": "Static deploy config",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Deploy plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "min_scale": {
          "description": "Minimum scale of container deployment (used if deployment uses a container).",
          "type": "integer"
        },
        "max_scale": {
          "description": "Maximum scale of container deployment (used if deployment uses a container).",
          "type": "integer"
        },
        "timeout": {
          "description": "Execution timeout. Execution is considered failed and can be terminated if the function is not completed at the end of the timeout period.",
          "type": "integer"
        },
        "patterns": {
          "description": "File/dir patterns to exclude (or force include if starts with '!').",
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "ServiceDeploy": {
      "title": "Service deploy config",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Deploy plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "env": {
          "description": "Additional environment variables.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "cpu_limit": {
          "description": "CPU limit of container deployment. 1.0 means 1 full core of CPU will be used.",
          "type": "number"
        },
        "memory_limit": {
          "description": "Memory limit in MiB of container deployment.",
          "type": "integer"
        },
        "min_scale": {
          "description": "Minimum scale of container deployment.",
          "type": "integer"
        },
        "max_scale": {
          "description": "Maximum scale of container deployment.",
          "type": "integer"
        },
        "timeout": {
          "description": "Execution timeout. Execution is considered failed and can be terminated if the function is not completed at the end of the timeout period.",
          "type": "integer"
        },
        "container": {
          "description": "Service application container config used for docker based deployments.",
          "$ref": "#/definitions/ServiceContainer"
        }
      }
    },
    "Scheduler": {
      "title": "Scheduler config",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "cron"
        ],
        "properties": {
          "cron": {
            "description": "Scheduler cron, e.g. */30 * * * * runs every 30 minutes.",
            "type": "string"
          },
          "name": {
            "description": "Name of cron (just for information purpose).",
            "type": "string"
          },
          "method": {
            "description": "HTTP method to use. Defaults to 'GET'.",
            "type": "string",
            "enum": [
              "GET", "POST", "HEAD", "PUT", "DELETE", "PATCH", "OPTIONS"
            ]
          },
          "path": {
            "description": "Path to call in current app url.",
            "type": "string"
          },
          "headers": {
            "description": "Additional headers to use for this call.",
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          }
        }
      }
    },
    "FunctionDeploy": {
      "title": "Function deploy config",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "plugin": {
          "description": "Deploy plugin override. Defaults to first supported plugin available.",
          "type": "string"
        },
        "env": {
          "description": "Additional environment variables.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "memory_limit": {
          "description": "Memory limit in MiB of function deployment.",
          "type": "integer"
        },
        "min_scale": {
          "description": "Minimum scale of container deployment (used if deployment uses a container).",
          "type": "integer"
        },
        "max_scale": {
          "description": "Maximum scale of container deployment (used if deployment uses a container).",
          "type": "integer"
        },
        "timeout": {
          "description": "Execution timeout. Execution is considered failed and can be terminated if the function is not completed at the end of the timeout period.",
          "type": "integer"
        }
      }
    },
    "FunctionPackage": {
      "title": "Function package config",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "patterns": {
          "description": "Package patterns to exclude (or force include if starts with '!').",
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "CDN": {
      "title": "CDN",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        }
      }
    },
    "StaticBasicAuth": {
      "title": "Static app basic auth config",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "realm": {
          "description": "Basic auth realm name, defaults to 'restricted'.",
          "type": "string"
        },
        "users": {
          "description": "Basic auth users in form of `user: password` where password is either in plain text or in a form of apr1 hash (used by htpasswd).",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        }
      }
    },
    "StaticBuild": {
      "title": "Build static app",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "env": {
          "description": "Additional environment variables available during build.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "command": {
          "description": "Command to be run to generate output files.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "dir": {
          "description": "Output dir to where static files end up.",
          "type": "string"
        }
      }
    },
    "ServiceBuild": {
      "title": "Service app build definition",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "image": {
          "description": "Docker image to use. If specified, will try to pull this image if skip-build is enabled.",
          "type": "string"
        },
        "skip_build": {
          "description": "Skip this image build phase. If enabled, requires image to be either present on docker host or custom image to be possible to pull.",
          "type": "boolean"
        },
        "skip_pull": {
          "description": "Skip this image dependencies pull phase. As a result, doesn't check for newer versions of tagged dependencies. Useful if dependencies do not exist outside of local docker.",
          "type": "boolean"
        },
        "build_args": {
          "description": "Docker build-args.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "context": {
          "description": "Docker context directory, relative to application dir.",
          "type": "string"
        },
        "dockerfile": {
          "description": "Dockerfile to use, relative to context path. Defaults to 'Dockerfile'.",
          "type": "string"
        }
      }
    },
    "FunctionBuild": {
      "title": "Build function app",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "env": {
          "description": "Additional environment variables available during build.",
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "command": {
          "description": "Command to be run to generate output files.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "dir": {
          "description": "Output dir to where built files end up.",
          "type": "string"
        }
      }
    },
    "ServiceContainer": {
      "title": "Service app container definition",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "port": {
          "description": "Docker container port to use.",
          "type": "integer"
        },
        "command": {
          "description": "Docker command (CMD) to override.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "entrypoint": {
          "description": "Docker entrypoint (ENTRYPOINT) to override.",
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": {
    "$ref": "#/definitions/job"
  },
  "definitions": {
    "deployment": {
      "type": "object",
      "title": "Deployment projects",
      "description": "A deployment project in Bamboo is a container for holding the software project you are deploying: releases that have been built and tested, and the environments to which releases are deployed",
      "properties": {
        "name": {
          "type": "string"
        },
        "source-plan": {
          "type": "string"
        }
      }
    },
    "docker": {
      "title": "Docker",
      "description": "Builds and deployments are normally run on the Bamboo agent's native operating system",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "properties": {
            "image": {
              "type": "string"
            },
            "volumes": {
              "type": "object",
              "default": {}
            },
            "use-default-volumes": {
              "type": "boolean",
              "default": false
            },
            "docker-run-arguments": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          },
          "required": ["image"]
        }
      ]
    },
    "events": {
      "type": "string",
      "enum": [
        "plan-failed",
        "plan-completed",
        "plan-status-changed",
        "plan-comment-added",
        "plan-responsibility-changed",
        "job-completed",
        "job-status-changed",
        "job-failed",
        "job-error",
        "job-first-failed",
        "job-hung",
        "job-queue-timeout",
        "job-queued-without-capable-agents"
      ]
    },
    "job": {
      "title": "Job",
      "description": "A job is a single build unit within a plan and is made up of one or more tasks.",
      "definitions": {
        "artifact": {
          "type": "object",
          "title": "Artifact",
          "description": "Artifacts are files created by a job build (e.g. JAR files)",
          "properties": {
            "location": {
              "description": "The relative path to find your artifact; it's a path relative to the workspace directory; do not use absolute paths.",
              "type": "string"
            },
            "name": {
              "description": "Name of the artifact; in case artifact is shared, name must be unique within the plan.",
              "type": "string"
            },
            "pattern": {
              "description": "Name or Ant pattern of file(s) to keep.",
              "type": "string"
            },
            "required": {
              "type": "boolean"
            },
            "shared": {
              "type": "boolean",
              "description": "You can share an artifact among other jobs or plans.",
              "default": false
            }
          }
        },
        "task": {
          "description": "A task is a small unit of work, such as source code checkout, or running a script",
          "type": "object",
          "properties": {
            "interpreter": {
              "type": "string"
            },
            "clean": {
              "type": "object"
            },
            "checkout": {
              "type": "object",
              "properties": {
                "repository": {
                  "type": "string"
                },
                "path": {
                  "type": "string"
                },
                "force-clean-build": {
                  "type": "string",
                  "default": false
                }
              }
            },
            "inject-variables": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "file": {
                      "type": "string"
                    },
                    "scope": {
                      "type": "string"
                    },
                    "namespace": {
                      "type": "string"
                    }
                  }
                }
              ]
            },
            "test-parser": {
              "description": "The Test Results Parser task in Bamboo parses test data",
              "anyOf": [
                {
                  "$ref": "#/definitions/testParser"
                },
                {
                  "type": "object",
                  "properties": {
                    "type": {
                      "$ref": "#/definitions/testParser"
                    },
                    "ignore-time": {
                      "type": "boolean"
                    },
                    "test-results": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "required": ["type"]
                }
              ]
            },
            "scripts": {
              "type": "array",
              "minItems": 1,
              "items": {
                "$ref": "#/definitions/script"
              }
            }
          }
        }
      },
      "type": "object",
      "properties": {
        "docker": {
          "$ref": "#/definitions/docker"
        },
        "final-tasks": {
          "type": "array"
        },
        "key": {
          "type": "string"
        },
        "other": {
          "type": "object",
          "properties": {
            "clean-working-dir": {
              "type": "boolean"
            }
          }
        },
        "requirements": {
          "type": "array",
          "items": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "object",
                "patternProperties": {
                  ".": {
                    "type": "string"
                  }
                }
              }
            ]
          }
        },
        "tasks": {
          "type": "array",
          "items": {
            "anyOf": [
              {
                "$ref": "#/definitions/predefinedTask"
              },
              {
                "$ref": "#/definitions/script"
              },
              {
                "$ref": "#/definitions/job/definitions/task"
              }
            ]
          }
        }
      }
    },
    "keyValue": {
      "description": "Variables can be used to make values available when building plans in Bamboo.",
      "type": "object",
      "patternProperties": {
        "[a-zA-Z0-9_]": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "integer"
            },
            {
              "type": "boolean"
            },
            {
              "type": "number"
            }
          ]
        }
      }
    },
    "notification": {
      "type": "object",
      "properties": {
        "recipients": {
          "type": "array",
          "anyOf": [
            {
              "type": "object",
              "properties": {
                "users": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              }
            },
            {
              "type": "object",
              "properties": {
                "groups": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              }
            }
          ]
        },
        "events": {
          "type": "array",
          "minLength": 1,
          "items": {
            "$ref": "#/definitions/events"
          }
        }
      }
    },
    "permission": {
      "type": "object",
      "description": "Plan permissions allow a user to control access to the functions of the build plan.",
      "definitions": {
        "permission": {
          "description": "Plan permissions allow a user to control access to the functions of the build plan",
          "type": "string",
          "enum": ["view", "edit", "build", "admin", "clone", "deploy"]
        }
      },
      "properties": {
        "groups": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "permissions": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "$ref": "#/definitions/permission/definitions/permission"
              }
            },
            {
              "$ref": "#/definitions/permission/definitions/permission"
            }
          ]
        },
        "roles": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "users": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "plan": {
      "description": "A plan defines everything about your continuous integration build process in Bamboo.",
      "type": "object",
      "properties": {
        "project-key": {
          "type": "string"
        },
        "key": {
          "type": "string"
        },
        "name": {
          "type": "string"
        }
      }
    },
    "predefinedTask": {
      "type": "string",
      "enum": ["inject-variables", "clean", "checkout", "artifact-download"]
    },
    "releaseNaming": {
      "type": "object",
      "properties": {
        "next-version-name": {
          "type": "string"
        },
        "applies-to-branches": {
          "type": "boolean"
        },
        "auto-increment": {
          "type": "boolean"
        },
        "auto-increment-variables": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        }
      }
    },
    "script": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "properties": {
            "script": {
              "type": "string"
            }
          }
        }
      ]
    },
    "stage": {
      "title": "Stage",
      "description": "Stages group jobs to individual steps within a plan's build process.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "manual": {
          "description": "Will await for execution by user",
          "type": "boolean"
        },
        "final": {
          "description": "Will be executed regardless of other stages state (pass or fail)",
          "type": "boolean"
        },
        "jobs": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "task": {
      "description": "A task is a small unit of work, such as source code checkout, or running a script.",
      "type": "object",
      "definitions": {
        "trigger": {
          "anyOf": [
            {
              "type": "object",
              "properties": {
                "stage": {
                  "type": "string"
                },
                "branch": {
                  "type": "string"
                }
              }
            },
            {
              "type": "object",
              "patternProperties": {
                "[a-zA-Z0-9\\s+_-]": {
                  "type": "string"
                }
              }
            }
          ]
        }
      },
      "properties": {
        "source-plan": {
          "type": "string"
        },
        "artifacts": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/job/definitions/artifact"
          }
        },
        "triggers": {
          "type": "array",
          "items": {
            "type": "object",
            "patternProperties": {
              "(build|stage|environment)-success": {
                "$ref": "#/definitions/task/definitions/trigger"
              }
            }
          }
        },
        "notifications": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/notification"
          }
        }
      }
    },
    "testParser": {
      "type": "string",
      "enum": ["junit", "mstest", "nunit", "mocha", "testng"]
    },
    "triggers": {
      "type": "array",
      "definitions": {
        "polling": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "polling": {
              "anyOf": [
                {
                  "type": "integer"
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "period": {
                      "type": "integer"
                    },
                    "conditions": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "patternProperties": {
                          "[a-zA-Z0-9\\s+_-]": {
                            "type": "object",
                            "additionalProperties": {
                              "type": "boolean"
                            }
                          }
                        }
                      }
                    }
                  }
                }
              ]
            }
          }
        },
        "remote": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "remote": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "object",
                  "properties": {
                    "ip": {
                      "type": "string"
                    }
                  }
                }
              ]
            }
          }
        },
        "cron": {
          "type": "object",
          "description": "Execute deployment by schedule.",
          "additionalProperties": false,
          "properties": {
            "cron": {
              "oneOf": [
                {
                  "type": "string"
                },
                {
                  "type": "object",
                  "properties": {
                    "expression": {
                      "type": "string"
                    }
                  }
                }
              ]
            }
          }
        }
      },
      "items": {
        "anyOf": [
          {
            "$ref": "#/definitions/triggers/definitions/polling"
          },
          {
            "$ref": "#/definitions/triggers/definitions/cron"
          },
          {
            "$ref": "#/definitions/triggers/definitions/remote"
          },
          {
            "type": "string"
          }
        ]
      }
    }
  },
  "description": "Full spec reference: https://docs.atlassian.com/bamboo-specs-docs/7.2.4/specs.html",
  "id": "https://json.schemastore.org/bamboo-spec.json",
  "properties": {
    "default-environment-permissions": {
      "title": "Default Environment Permissions",
      "description": "These permissions apply to all environments defined in this deployment project",
      "type": "array",
      "items": {
        "$ref": "#/definitions/permission"
