  "definitions": {
    "pathPattern": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "properties": {
            "re": {
              "type": "string"
            }
          },
          "additionalProperties": false,
          "required": ["re"],
          "description": "Regular expression"
        }
      ]
    },
    "terminationSignals": {
      "anyOf": [
        {
          "const": "SIGTERM"
        },
        {
          "const": "SIGINT"
        },
        {
          "const": "SIGQUIT"
        },
        {
          "const": "SIGKILL"
        },
        {
          "const": "SIGHUP"
        }
      ]
    },
    "variables": {
      "anyOf": [
        {
          "const": "{{pwd}}",
          "description": "The current directory"
        },
        {
          "const": "{{filename}}",
          "description": "The filename you pass to nodemon"
        }
      ]
    }
  },
  "dependencies": {
    "pollingInterval": {
      "required": ["legacyWatch"]
    },
    "nodeArgs": {
      "exec": {
        "const": "node"
      },
      "required": ["exec"]
    }
  },
  "properties": {
    "colours": {
      "default": true,
      "description": "set to false to disable color output",
      "type": "boolean"
    },
    "cwd": {
      "description": "change into <dir> before running the script",
      "type": "string"
    },
    "delay": {
      "default": 0,
      "description": "debounce restart for a number of milliseconds",
      "type": "number"
