              "pageCapture",
              "tabs",
              "topSites",
              "webNavigation",
              "webRequest",
              "webRequestBlocking"
            ]
          }
        ]
      }
    },
    "options_ui": {
      "type": "object",
      "description": "Use the options_ui key to define an options page for your add-on.",
      "required": ["page"],
      "properties": {
        "page": {
          "type": "string",
          "description": "The path to an HTML file containing the specification of your options page."
        },
        "browser_style": {
          "type": "boolean",
          "default": true,
          "description": "Use this to include a stylesheet in your page that will make it look consistent with the browser's UI and with other add-ons that use the browser_style property."
        },
        "open_in_tab": {
          "type": "boolean",
          "default": false,
          "description": "If true, the options page will open in a normal browser tab, rather than being integrated into the browser's add-ons manager."
        }
      }
    },
    "page_action": {
      "description": "Use the chrome.pageAction API to put icons inside the address bar. Page actions represent actions that can be taken on the current page, but that aren't applicable to all pages.",
      "type": "object",
      "properties": {
        "browser_style": {
          "description": "Use this to include a stylesheet in your popup that will make it look consistent with the browser's UI and with other add-ons that use the browser_style property. Although this key defaults to false, it's recommended that you include it and set it to true.",
          "type": "boolean",
          "default": false
        },
        "default_icon": {
          "$ref": "#/definitions/icon"
        },
        "default_popup": {
          "type": "string",
          "description": "The popup appears when the user clicks the icon."
        },
        "default_title": {
          "type": "string",
          "description": "Tooltip for the main toolbar icon."
        }
      }
    },
    "permissions": {
      "$ref": "#/definitions/permissions",
      "description": "Permissions help to limit damage if your extension or app is compromised by malware. Some permissions are also displayed to users before installation, as detailed in Permission Warnings."
    },
    "protocol_handlers": {
      "type": "array",
      "description": "Use this key to register one of more web-based protocol handlers.",
      "items": {
        "type": "object",
        "description": "Use this object to register a single web-based protocol handler",
        "properties": {
          "protocol": {
            "description": "A string defining the protocol.",
            "anyOf": [
              {
                "enum": [
                  "bitcoin",
                  "geo",
                  "im",
                  "irc",
                  "ircs",
                  "magnet",
                  "mailto",
                  "mms",
                  "news",
                  "nntp",
                  "sip",
                  "sms",
                  "smsto",
                  "ssh",
                  "tel",
                  "urn",
                  "webcal",
                  "wtai",
                  "xmpp"
                ],
                "description": "A pre-existing protocol allowed for use with WebExtensions. See https://developer.mozilla.org/en-US/docs/Mozilla/Add-ons/WebExtensions/manifest.json/protocol_handlers for more information."
              },
              {
                "type": "string",
                "pattern": "^(ext|web)\\+[0-9a-z]+",
                "description": "A custom-named protocol. These MUST be prefixed with 'web+' or 'ext+', followed by a string consisting of only lower-case ASCII characters."
              }
            ]
          },
          "name": {
            "description": "A string representing the name of the protocol handler. This will be displayed to the user when they are being asked if they want this handler to open the link.",
            "type": "string"
          },
          "uriTemplate": {
            "description": "A string representing the URL of the handler. This string must include \"%s\" as a placeholder: this will be replaced with the escaped URL of the document to be handled. This URL might be a true URL, or it could be a phone number, email address, or so forth.",
            "pattern": "%s"
          }
        }
      }
    },
    "short_name": {
      "type": "string",
      "description": "The short name is typically used where there is insufficient space to display the full name.",
      "minLength": 2,
      "maxLength": 12
    },
    "sidebar_action": {
      "type": "object",
      "description": "A sidebar is a pane that is displayed at the left-hand side of the browser window, next to the web page. The browser provides a UI that enables the user to see the currently available sidebars and to select a sidebar to display.",
      "properties": {
        "default_icon": {
          "$ref": "#/definitions/icon"
        },
        "default_panel": {
          "type": "string",
          "description": "The path to an HTML file that specifies the sidebar's contents."
        },
        "default_title": {
          "type": "string",
          "description": "Title for the sidebar. This is used in the browser UI for listing and opening sidebars, and is displayed at the top of the sidebar when it is open."
        }
      }
    },
    "version": {
      "description": "One to four dot-separated integers identifying the version of this extension.",
      "pattern": "^(?:\\d{1,5}\\.){0,3}\\d{1,5}$"
    },
    "web_accessible_resources": {
      "type": "array",
      "description": "An array of strings specifying the paths (relative to the package root) of packaged resources that are expected to be usable in the context of a web page.",
      "uniqueItems": true,
      "items": {
        "type": "string"
      }
    }
  },
  "required": ["manifest_version", "name", "version"],
  "title": "JSON schema for WebExtensions manifest files",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/prometheus.rules.test.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "alert": {
      "properties": {
        "exp_annotations": {
          "$ref": "#/definitions/labels",
          "description": "Expanded annotations of the expected alert"
        },
        "exp_labels": {
          "$ref": "#/definitions/labels",
          "description": "Expanded labels and annotations of the expected alert. This also include the labels of the sample associated with the alert (same as what you see in `/alerts`, without series `__name__` and `alertname`)."
        }
      },
      "required": ["exp_labels"],
      "type": "object"
    },
    "alert_test_case": {
      "additionalProperties": false,
      "properties": {
        "alertname": {
          "description": "Name of the alert to be tested.",
          "type": "string"
        },
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "exp_alerts": {
          "description": "List of expected alerts firing under the given alertname at the given evaluation time",
          "items": {
            "$ref": "#/definitions/alert"
          },
          "type": "array"
        }
      },
      "required": ["eval_time", "alertname"],
      "type": "object"
    },
    "duration": {
      "minLength": 1,
      "pattern": "^([0-9]+y)?([0-9]+w)?([0-9]+d)?([0-9]+h)?([0-9]+m)?([0-9]+s)?([0-9]+ms)?$",
      "type": ["string", "null"]
    },
    "label_value": {
      "type": "string"
    },
    "labels": {
      "additionalProperties": false,
      "patternProperties": {
        "^[a-zA-Z_][a-zA-Z0-9_]*$": {
          "$ref": "#/definitions/label_value"
        }
      },
      "type": ["object", "null"]
    },
    "promql_test_case": {
      "additionalProperties": false,
      "properties": {
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the expression has to be evaluated."
        },
        "exp_samples": {
          "description": "Expected samples at the given evaluation time.",
          "items": {
            "$ref": "#/definitions/sample"
          },
          "type": "array"
        },
        "expr": {
          "description": "PromQL expression to evaluate",
          "type": "string"
        }
      },
      "required": ["expr", "eval_time"],
      "type": "object"
    },
    "sample": {
      "properties": {
        "labels": {
          "description": "Labels of the sample in the usual series notation '<metric name>{<label name>=<label value>, ...}'",
          "type": "string"
        },
        "value": {
          "description": "Expected value of the PromQL expression.",
          "type": "number"
        }
      },
      "required": ["labels", "value"],
      "type": "object"
    },
    "series": {
      "additionalProperties": false,
      "properties": {
        "series": {
          "description": "This follows the usual series notation '<metric name>{<label name>=<label value>, ...}'.",
          "type": "string"
        },
        "values": {
          "description": "This uses expanded notation to project time series. There are also the special `_` and `stale` values to indicate missing or stale samples",
          "type": "string"
        }
      },
      "required": ["series", "values"],
      "type": "object"
    },
    "test_group": {
      "additionalProperties": false,
      "properties": {
        "alert_rule_test": {
          "description": "Unit tests for alerting rules. We only consider the alerting rules from the input files.",
          "items": {
            "$ref": "#/definitions/alert_test_case"
          },
          "type": "array"
        },
        "external_labels": {
          "$ref": "#/definitions/labels",
          "description": "External labels accessible to the alert template."
        },
        "external_url": {
          "description": "External URL accessible to the alert template. Usually set using --web.external-url.",
          "type": "string"
        },
        "input_series": {
          "description": "A list of time series",
          "items": {
            "$ref": "#/definitions/series"
          },
          "type": "array"
        },
        "interval": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "name": {
          "description": "Name of the test group",
          "type": "string"
        },
        "promql_expr_test": {
          "description": "Unit tests for PromQL expressions",
          "items": {
            "$ref": "#/definitions/promql_test_case"
          },
          "type": "array"
        }
      },
      "required": ["interval", "input_series"],
      "type": "object"
    }
  },
  "description": "Prometheus rules test file. See https://prometheus.io/docs/prometheus/latest/configuration/unit_testing_rules/ for details.",
  "properties": {
    "evaluation_interval": {
      "default": "1m",
      "description": "The evaluation interval for the tests. [duration] format.",
      "type": ["string", "null"]
    },
    "group_eval_order": {
      "description": "The order in which group names are listed below will be the order of evaluation of rule groups (at a given evaluation time).",
      "items": {
        "type": "string"
      },
      "type": ["array", "null"]
    },
    "rule_files": {
      "description": "List of rule files to consider for testing. Globs are supported.",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "tests": {
      "items": {
        "$ref": "#/definitions/test_group",
        "description": "All the tests are listed here."
      },
      "type": "array"
    }
  },
  "title": "Prometheus Rules Test File",
  "type": "object"
}

