{
  "$schema": "http://json-schema.org/draft-07/schema",
  "$id": "https://dwp.gov.uk/exchange/publishing-tools/apigw/catalogue-entry-schema.json",
  "title": "Catalogue entry",
  "type": "object",
  "required": [
    "description",
    "primaryContact",
    "filters",
    "searchTags"
  ],
  "properties": {
    "description": {
      "type": "string",
      "minLength": 10,
      "maxLength": 200
    },
    "primaryContact": {
      "type": "object",
      "title": "Primary contact",
      "description": "Contact details for the owner of the asset, i.e. the Product Owner.These details will be used when customers make enquiries or request access to the asset through the portal.",
      "required": [
        "emailAddress"
      ],
      "properties": {
        "name": {
          "type": "string",
          "minLength": 2,
          "maxLength": 35
        },
        "emailAddress": {
          "type": "string",
          "description": "must end with `gov.uk`",
          "pattern": "^.*@.*gov\\.uk$"
        },
        "role": {
          "type": "string",
          "minLength": 2
        }
      },
      "additionalProperties": false,
      "examples": [
        {
          "name": "Jo Doe",
          "emailAddress": "jo.doe@dwp.gov.uk",
          "role": "PO"
        }
      ]
    },
    "technical_documentation": {
      "type": "object",
      "title": "Technical documentation",
      "description": "Allows you to provide paths to technical documentation to be published to the portal.",
      "required": [
        "oas_path"
      ],
      "properties": {
        "oas_path": {
          "type": "string",
          "description": "Path to the technical documentation, relative to the current working directory.",
          "pattern": "((?:[^\/]*\/)*)(?=\\.(yaml|yml|json))"
        }
      },
      "additionalProperties": false,
      "examples": [
        {
          "oas_path": "../oas/pet-store.yaml"
        }
      ]
    },
    "filters": {
      "title": "Filters",
      "type": "object",
      "description": "A list of filtering options to improve searchability on the portal. Please check the README file to check the valid combinations of `lifecycle`, `profile`, and `access`.",
      "required": [
        "asset_type",
        "owner",
        "categories",
        "visibility",
        "lifecycle",
        "profile",
        "access"
      ],
      "allOf": [
        {"$ref": "#/properties/filters/definitions/active-lifecycle"},
        {"$ref": "#/properties/filters/definitions/deprecated-lifecycle"}
      ],
      "definitions": {
        "active-lifecycle": {
          "if": {
            "properties": {
              "lifecycle": {
                "enum": [
                  "In Development",
                  "Pre-Prod",
                  "Prod"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "profile": {
                "enum": [
                  "Strategic",
                  "Transitional"
                ]
              },
              "access": {
                "enum": [
                  "Open",
                  "Closed"
                ]
              }
            }
          }
        },
        "deprecated-lifecycle": {
          "if": {
            "properties": {
              "lifecycle": {
                "enum": [
                  "Deprecated",
                  "Removed"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "profile": {
                "const": "Legacy"
              },
              "access": {
                "const": "Closed"
              }
            }
          }
        }
      },
      "properties": {
        "asset_type": {
          "type": "string",
          "enum": [
            "REST API",
            "SOAP API",
            "Event",
            "Datasets"
          ],
          "examples": [
            "REST API"
          ]
        },
        "owner": {
          "type": "string",
          "enum": [
            "AME Payments",
            "Citizen Income",
            "Citizen Information",
            "Document Repository Services",
            "Integration",
            "Legacy Bridge",
            "Notifications Platform",
            "Personal Independence Payment",
            "Reference Data Service",
            "Retirement, Bereavement & Care",
            "Common Capabilities",
            "Other"
          ],
          "examples": [
            "Integration"
          ]
        },
        "categories": {
          "title": "Categories",
          "type": "array",
          "minLength": 1,
          "maxLength": 3,
          "items": {
            "type": "string",
            "enum": [
              "Address",
              "Awards",
              "Citizen",
              "Data",
              "Document Services",
              "Financial",
              "GUID",
              "SMS",
              "Other"
            ]
          },
          "examples": [
            [
              "Address"
            ]
          ]
        },
        "visibility": {
          "type": "string",
          "enum": [
            "Internal",
            "Public"
          ],
          "examples": [
            "Internal"
          ]
        },
        "lifecycle": {
          "type": "string",
          "enum": [
            "In Development",
            "Pre-Prod",
            "Prod",
            "Deprecated",
            "Removed"
          ],
          "examples": [
            "In Development"
          ]
        },
        "profile": {
          "type": "string",
          "title": "The profile Schema",
          "enum": [
            "Strategic",
            "Transitional",
            "Legacy"
          ],
          "examples": [
            "Strategic"
          ]
        },
        "access": {
          "type": "string",
          "enum": [
            "Open",
            "Closed"
          ],
          "examples": [
            "Open"
          ]
        }
      },
      "additionalProperties": false,
      "examples": [
        {
          "asset_type": "REST API",
          "owner": "Integration",
          "categories": [
            "Address"
          ],
          "visibility": "Internal",
          "lifecycle": "Prod",
          "profile": "Transitional",
          "access": "Open"
        }
      ]
    },
    "searchTags": {
      "type": "string",
      "description": "Tags to label the asset in order to increase discoverability. Minimum of 3 in CSV format.",
      "pattern": "^([^,]+(,|$)){3,}$",
      "examples": [
        "tag1, tag2, tag3"
      ]
    },
    "relatedAssets": {
      "title": "Related assets",
      "description": "A list of other assets that are related to the asset being published. Must match the Asset ID on the related asset's business documentation page on the portal at https://gitlab.com/dwp/integration/api-exchange/exchange-content/-/tree/main/output/dwp/portal/workspaces/primary/content/_catalogueEntries.",
      "type": "array",
      "items": {
        "type": "string",
        "examples": [
          "integration-alive-check-service-v1"
        ]
      }
    }
  },
  "additionalProperties": false,
  "examples": [
    {
      "description": "This is an example service",
      "primaryContact": {
        "emailAddress": "test@gov.uk"
      },
      "technical_documentation": {
        "oas_path": "../oas/path-to-spec.yml"
      },
      "filters": {
        "asset_type": "REST API",
        "owner": "Integration",
        "categories": [
          "Address"
        ],
        "visibility": "Internal",
        "lifecycle": "Pre-Prod",
        "profile": "Transitional",
        "access": "Closed"
      },
      "searchTags": "test1,test2,test3"
    }
  ]
}

{
  "$schema": "http://json-schema.org/draft-07/schema",
  "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Configuring-your-actions",
  "definitions": {
    "commonTypes": {
      "description": "Some of the reusable base types",
      "definitions": {
        "charSet": {
          "description": "Standard character sets.",
          "type": "string",
          "enum": [
            "ISO-8859-1",
            "US-ASCII",
            "UTF-16",
            "UTF-16BE",
            "UTF-16LE",
            "UTF-8"
          ],
          "additionalItems": false
        },
        "chronoUnit": {
          "description": "The chrono unit we want to use.",
          "type": "string",
          "enum": [
            "NANOS",
            "MICROS",
            "MILLIS",
            "SECONDS",
            "MINUTES",
            "HOURS",
            "HALF_DAYS",
            "DAYS",
            "WEEKS",
            "MONTHS",
            "YEARS",
            "DECADES",
            "CENTURIES",
            "MILLENNIA",
            "ERAS",
            "FOREVER"
          ],
          "additionalItems": false
        },
        "httpHeaders": {
          "type": "object",
          "description": "HTTP header map.",
          "additionalProperties": {
            "type": "string"
          },
          "uniqueItems": true
        },
        "httpMethod": {
          "description": "Supported HTTP methods.",
          "type": "string",
          "enum": [
            "GET",
            "POST"
          ],
          "additionalItems": false
        },
        "jsonPath": {
          "$comment": "https://github.com/json-path/JsonPath",
          "description": "A JSON Path selecting one or more nodes of the parsed JSON document.",
          "type": "string",
          "pattern": "^[$@](((\\.|\\.\\.)([$_a-zA-Z]+[$a-zA-Z0-9\\-_]*|\\*))|\\[\\*]|\\[[0-9]+((, [0-9]+)*|:[0-9]+)]|\\['[$_a-zA-Z]+[$a-zA-Z0-9\\-_]*'(, '[$_a-zA-Z]+[$a-zA-Z0-9\\-_]*')*]|\\[\\?\\(.+\\)])*$"
        },
        "name": {
          "description": "A single JSON key name",
          "type": "string",
          "pattern": "^[$_a-zA-Z]+[$a-zA-Z0-9\\-_]*$"
        }
      }
    },
    "functionTypes": {
      "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions",
      "description": "Definition of known function types",
      "definitions": {
        "functionAbsoluteValue": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#absolute-value-function",
          "description": "Absolute value function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "absoluteValue",
              "description": "The name of the component."
            },
            "scale": {
              "type": "integer",
              "description": "The number of digits we want to keep right of the decimal point."
            }
          },
          "required": [
            "name",
            "scale"
          ],
          "additionalProperties": false
        },
        "functionAdd": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#decimal-add-function",
          "description": "Decimal add function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "add",
              "description": "The name of the component."
            },
            "operand": {
              "type": "number",
              "description": "Second operand of the calculation."
            },
            "scale": {
              "type": "integer",
              "description": "The number of digits we want to keep right of the decimal point."
            }
          },
          "required": [
            "name",
            "operand",
            "scale"
          ],
          "additionalProperties": false
        },
        "functionChangeCase": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#change-case",
          "description": "Change case",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "changeCase",
              "description": "The name of the component."
            },
            "to": {
              "description": "Defines what is the desired case change operation we want to do.",
              "type": "string",
              "enum": [
                "CAPITALIZED",
                "UNCAPITALIZED",
                "LOWER_CASE",
                "UPPER_CASE"
              ],
              "additionalItems": false
            }
          },
          "required": [
            "name",
            "to"
          ],
          "additionalProperties": false
        },
        "functionCloneKey": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#clone-key-function",
          "description": "Clone key function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "cloneKey",
              "description": "The name of the component."
            },
            "from": {
              "allOf": [
                {
                  "$ref": "#/definitions/commonTypes/definitions/name"
                },
                {
                  "description": "The name of the key we need to duplicate."
                }
              ]
            },
            "to": {
              "allOf": [
                {
                  "$ref": "#/definitions/commonTypes/definitions/name"
                },
                {
                  "description": "The name of the destination key."
                }
              ]
            }
          },
          "required": [
            "from",
            "name",
            "to"
          ],
          "additionalProperties": false
        },
        "functionDivide": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#decimal-divide-function",
          "description": "Decimal divide function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "divide",
              "description": "The name of the component."
            },
            "operand": {
              "type": "number",
              "description": "Second operand of the calculation."
            },
            "scale": {
              "type": "integer",
              "description": "The number of digits we want to keep right of the decimal point."
            }
          },
          "required": [
            "name",
            "operand",
            "scale"
          ],
          "additionalProperties": false
        },
        "functionDividend": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#decimal-dividend-function",
          "description": "Decimal dividend function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "dividend",
              "description": "The name of the component."
            },
            "operand": {
              "type": "number",
              "description": "First operand of the calculation."
            },
            "scale": {
              "type": "integer",
              "description": "The number of digits we want to keep right of the decimal point."
            }
          },
          "required": [
            "name",
            "operand",
            "scale"
          ],
          "additionalProperties": false
        },
        "functionEpochMillisDateAdd": {
          "$comment": "https://github.com/nagyesta/yippee-ki-json/wiki/Built-in-functions#epoch-millis-date-add-function",
          "description": "Epoch millis date add function",
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "const": "epochMillisDateAdd",
              "description": "The name of the component."
            },
            "amount": {
              "type": "integer",
              "description": "The amount of time units we need to add to the date time."
