              "type": "array",
              "minItems": 0,
              "items": {
                "type": "string"
              },
              "uniqueItems": true
            }
          }
        }
      ]
    },
    "validateIndentation": {
      "description": "Validates indentation for switch statements and block statements.",
      "type": ["integer", "null", "object", "string"],
      "oneOf": [
        {
          "description": "A positive number of spaces.",
          "type": "integer",
          "minimum": 0
