    "defaultProvider": {
      "properties": {
        "defaultProvider": {
          "description": "The unique identifier of the provider to use as default.",
          "type": "string",
          "minLength": 1
        }
      }
    },
    "specifiedDestination": {
      "properties": {
        "libraries": {
          "items": {
            "required": ["destination"]
          }
        }
      },
      "not": {
        "required": ["defaultDestination"]
