                    "type": "integer",
                    "default": 60
                }
            }
        },
        "Service": {
            "type": "object",
            "description": "User defined service",
            "properties": {
                "command": {
                    "description": "Command to execute. Can be any command here which can be executed.",
                    "type": "string"
                },
                "env": {
                    "description": "Environment variables for the process",
                    "type": "object",
